BEGIN;

INSERT INTO public.subjects (slug, name, description, color, sort_order)
VALUES ('g-kentei-f', 'G検定（JDLA ジェネラリスト検定） Set F 苦手強化',
        'JDLA G検定 対策 第6弾。機械学習の概要・ディープラーニングの概要/要素技術/応用例の4分野に絞った苦手強化セット。誤答実績の多いテーマ（プーリング、RNN/LSTM、正則化、最適化手法など）を別角度から問い直す。学習用オリジナル。',
        '#0B5CAB', 55)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('3. 機械学習の概要', '#3fb950', 0),
  ('4. ディープラーニングの概要', '#a371f7', 1),
  ('5. ディープラーニングの要素技術', '#d2a8ff', 2),
  ('6. ディープラーニングの応用例', '#f0883e', 3)
) AS v(name, color, sort_order)
WHERE s.slug = 'g-kentei-f'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('g-kentei-f-q1', '3. 機械学習の概要',
   '工場のセンサーが集めた大量のデータに、正解ラベルは一切付いていない。このデータだけを使って「似た状態のグループ」を自動で見つけ出す学習はどれか。',
   NULL::text,
   '["教師なし学習", "教師あり学習", "強化学習", "半教師あり学習"]',
   0, '[0]', 'single',
   '{"asked": "正解ラベルなしのデータからグループを見つける学習方式を選ぶ問題。", "point": "正解ラベルが1つも無く、構造だけを見つけるなら教師なし学習。", "kid": "「これは正常」「これは異常」という答え（ラベル）を誰も教えてくれない状態で、データだけを見て「なんとなく似ているもの同士」を自分でまとめる学び方。それが教師なし学習。", "eg": "たとえるなら、答えの書いていない大量の写真の山を渡されて、「なんとなく似ている写真同士」で自分の判断だけで束ねていく作業。誰も正解を教えてくれない。", "terms": [["教師あり学習", "問題と正解のペアで学ぶ。ラベル（正解）が必須"], ["教師なし学習", "正解ラベルなしで、データの構造やまとまりを自分で見つける"], ["強化学習", "行動した結果もらえる報酬を手がかりに、試行錯誤で学ぶ"]], "think": "見分け方は「正解ラベルがあるか」「報酬という形の手がかりがあるか」の2段構え。正解ラベルが付いていれば教師あり学習。ラベルは無いが、行動した結果として点数や報酬が返ってくるなら強化学習。ラベルも報酬も無く、データの中の似た者同士をまとめるだけなら教師なし学習。この問題は「正解ラベルは一切付いていない」「グループを見つける」としか書かれておらず、報酬や行動の記述も無いので教師なし学習に絞れる。", "vs": "強化学習と混同しやすいが、強化学習には「行動」と「報酬」という手がかりが要る。ここにはその記述が無く、あるのはラベルなしデータだけなので教師なし学習。", "why_asked": "3つの学習方式の名前だけを覚えていても、文章の状況から見分けられないと得点にならない。この問題は「ラベルが無い」だけで即断せず、報酬の有無まで確認する癖を試している。", "usecase": "顧客データを事前の正解ラベルなしに自動でグループ分けし、似た傾向の顧客層を見つけるといった場面で使われる。", "opt": ["正解。正解ラベルも報酬も無く、データの構造だけを手がかりにグループを見つけているので教師なし学習。", "教師あり学習は「正解ラベル」が必須。この問題文には正解ラベルが無いと明記されているので当てはまらない。", "強化学習は行動の結果として得られる報酬が手がかり。この問題文には行動や報酬の記述が無い。", "半教師あり学習は少量のラベル付きデータと大量のラベルなしデータを組み合わせる方式。この問題文にはラベル付きデータの記述が無い。"]}'),
  ('g-kentei-f-q2', '3. 機械学習の概要',
   '主成分分析（PCA）とk-means法は、どちらも正解ラベルを使わない教師なし学習だが、目的が異なる。この違いの説明として最も適切なものはどれか。',
   NULL::text,
   '["PCAは情報のばらつきを保ったまま次元（項目数）を減らす手法で、k-meansはデータを指定した数のグループに分ける手法である", "PCAはデータを指定した数のグループに分ける手法で、k-meansは次元を減らす手法であり、両者の役割が丸ごと入れ替わっている", "どちらも次元を減らす手法であり、減らす軸の数をあらかじめいくつに決めておくかという計算式の細部だけが異なる", "どちらもデータを似た者どうしのグループに分ける手法であり、点と点の距離をどう測るかという計算方法だけが異なる"]',
   0, '[0]', 'single',
   '{"asked": "PCAとk-meansという2つの教師なし学習の「目的の違い」を選ぶ問題。", "point": "「軸をまとめて項目数を減らす」ならPCA、「点をグループに割り振る」ならk-means。", "kid": "PCAは、たくさんある項目（例えば身長・体重・座高…）を、情報をなるべく失わずに少ない軸にまとめ直す作業。k-means法は、バラバラに散らばった点を、近い者同士でいくつかのグループに仕分ける作業。「まとめ直す」のと「仕分ける」のとで、そもそもやっていることが違う。", "eg": "たとえるなら、PCAは「たくさんの科目のテスト結果を、『文系力』『理系力』という2つの総合指標にまとめ直す」作業。k-means法は「クラスの生徒を、仲の良さで3つのグループに分ける」作業。同じ生徒データを使っても、やることは別物。", "terms": [["PCA（Principal Component Analysis、主成分分析）", "直訳は「主な・成分の・分析」。項目の数を、情報を保ちながら少数の軸に圧縮する次元削減の手法"], ["k-means法", "データをk個のグループ（クラスタ）に分けるクラスタリングの手法"], ["次元削減", "項目（変数）の数を減らすこと。PCAはその代表例"], ["クラスタリング", "データを似た者同士のまとまりに分けること。k-means法はその代表例"]], "think": "教師なし学習という括りは同じでも、「出力として何を作るか」で区別できる。PCAが作るのは「少数の新しい軸（数値）」で、点の個数は変わらず各点の表し方が変わるだけ。k-means法が作るのは「どのグループに属するかというラベル」で、各点に新しい所属先が割り振られる。目的（次元を減らしたいのか、グループに分けたいのか）から先に考えると迷わない。", "vs": "「どちらも教師なし学習だから似た働き」と思い込むと選択肢3・4に引っかかる。次元削減とクラスタリングは、教師なし学習という同じ棚に並んでいるだけで役割は別物。", "why_asked": "G検定では「教師なし学習」とひとくくりにされがちな手法どうしの役割の違いを、名前だけでなく目的から説明できるかを問う。丸暗記だと似た名前の手法を取り違えやすい。", "usecase": "PCAはアンケートの多数の質問項目を少数の指標にまとめて可視化するときに、k-means法は顧客を購買傾向で複数グループに仕分けるときに使われる。", "opt": ["正解。PCAは項目数を減らす次元削減、k-meansは点をグループに割り振るクラスタリングで、目的が異なる。", "PCAとk-meansの役割を入れ替えて説明しており誤り。", "PCAは次元削減だが、k-meansは次元削減ではなくクラスタリングなので誤り。", "PCAは点をグループに分ける手法ではなく次元削減の手法なので誤り。"]}'),
  ('g-kentei-f-q3', '3. 機械学習の概要',
   'k-means法と階層的クラスタリングは、どちらもデータをグループに分ける教師なし学習だが、進め方に違いがある。この違いとして最も適切なものはどれか。',
   NULL::text,
   '["k-meansは先にグループ数を決めて割り振るが、階層的クラスタリングはまず木構造を作り、後から好きな高さで切ってグループ数を決められる", "k-meansは木構造をまず作ってから後で切り、階層的クラスタリングは先にグループ数を決めて割り振るもので、両者の説明が丸ごと入れ替わっている", "どちらも計算を始める前に先にグループ数を決めておく必要があり、そのグループ数の決め方の計算式だけが異なる", "どちらも近い点どうしを結んで木構造を作る手法であり、できあがった木の形の表し方だけが異なる"]',
   0, '[0]', 'single',
   '{"asked": "k-means法と階層的クラスタリングの「進め方の違い」を選ぶ問題。", "point": "先にグループ数を決めるならk-means、木を作ってから切るのは階層的クラスタリング。", "kid": "k-means法は、最初に「グループはいくつ作るか」を人間が決めてから、その数に点を割り振っていくやり方。階層的クラスタリングは逆で、まず近い点同士をどんどん結んでいって木（枝分かれの図）を作り、その木を後からどの高さで切るかによって、グループ数が変わる。", "eg": "たとえるなら、k-meansは「今日は3チームで遊ぶ」と先に決めてから人を割り振る遊び。階層的クラスタリングは、まず「仲の良い順」に手をつないで大きな輪を作っておき、後から「どこで輪を切るか」でチーム数を決める遊び。切る場所を変えれば2チームにも5チームにもできる。", "terms": [["k-means法", "先に決めたグループ数kに沿って、点を近い中心へ割り振るクラスタリング"], ["階層的クラスタリング", "近い点から順に結合し、木構造（デンドログラム）を作るクラスタリング"], ["デンドログラム", "階層的クラスタリングの結果を表す、枝分かれした木の形の図"]], "think": "違いのカギは「グループ数をいつ決めるか」。k-meansは計算を始める前にグループ数kを人間が指定しないと動かせない。一方、階層的クラスタリングは計算の過程でグループ数を指定する必要がなく、全部結合し終えた後にできた木を、好きな高さで切ることで初めてグループ数が決まる。だから同じ木から「2グループ」も「5グループ」も後付けで作れる。", "vs": "「どちらも教師なしのクラスタリングだから同じ」と考えると進め方の違いを見落とす。k-means法は事前にkを決める必要があるが、階層的クラスタリングは木を作ってから決められるという柔軟さが違う。", "why_asked": "似た結果（グループ分け）を出す2手法を、結果ではなく手順の違いで区別できるかを試す。「グループ数を先に決めるか、後で決めるか」という一点を覚えておくと迷わない。", "usecase": "グループ数の見当がすでに付いているならk-means法が速く、グループ数を試行錯誤しながら決めたいならデンドログラムを見ながら切る高さを調整できる階層的クラスタリングが向く。", "opt": ["正解。k-meansは先にグループ数を決め、階層的クラスタリングは木を作ってから後で切る高さでグループ数を決める。", "k-meansと階層的クラスタリングの説明が入れ替わっている。", "階層的クラスタリングは木を作った後で切る高さを変えればグループ数を後から選べるため、先に決める必要はない。", "k-meansは木構造を作らず、直接グループへ割り振る手法なので誤り。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"8\" y=\"14\" text-anchor=\"start\" font-size=\"9\" fill=\"#e8eaf0\">k-means（先にk=3を決める）</text>\n<line x1=\"10\" y1=\"24\" x2=\"150\" y2=\"24\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"10\" y1=\"24\" x2=\"10\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"10\" y1=\"130\" x2=\"150\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<circle cx=\"35\" cy=\"50\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"45\" cy=\"60\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"30\" cy=\"65\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"42\" cy=\"45\" r=\"4.5\" fill=\"#3b82f6\" stroke=\"#e8eaf0\" stroke-width=\"1\"/>\n<circle cx=\"95\" cy=\"45\" r=\"3.5\" fill=\"#6ab08d\"/>\n<circle cx=\"105\" cy=\"55\" r=\"3.5\" fill=\"#6ab08d\"/>\n<circle cx=\"88\" cy=\"55\" r=\"3.5\" fill=\"#6ab08d\"/>\n<circle cx=\"97\" cy=\"50\" r=\"4.5\" fill=\"#6ab08d\" stroke=\"#e8eaf0\" stroke-width=\"1\"/>\n<circle cx=\"60\" cy=\"105\" r=\"3.5\" fill=\"#c9a04a\"/>\n<circle cx=\"72\" cy=\"115\" r=\"3.5\" fill=\"#c9a04a\"/>\n<circle cx=\"55\" cy=\"118\" r=\"3.5\" fill=\"#c9a04a\"/>\n<circle cx=\"66\" cy=\"110\" r=\"4.5\" fill=\"#c9a04a\" stroke=\"#e8eaf0\" stroke-width=\"1\"/>\n<text x=\"80\" y=\"144\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">◎ = 中心点。3つに割り振る</text>\n\n<text x=\"185\" y=\"14\" text-anchor=\"start\" font-size=\"9\" fill=\"#e8eaf0\">階層的（木を作ってから切る）</text>\n<line x1=\"190\" y1=\"120\" x2=\"200\" y2=\"120\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"190\" y1=\"105\" x2=\"200\" y2=\"105\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"190\" y1=\"90\" x2=\"200\" y2=\"90\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"190\" y1=\"75\" x2=\"200\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"190\" y1=\"60\" x2=\"200\" y2=\"60\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"200\" y1=\"105\" x2=\"200\" y2=\"120\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"200\" y1=\"112.5\" x2=\"212\" y2=\"112.5\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"200\" y1=\"75\" x2=\"200\" y2=\"90\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"200\" y1=\"82.5\" x2=\"212\" y2=\"82.5\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"212\" y1=\"60\" x2=\"212\" y2=\"82.5\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"212\" y1=\"71\" x2=\"224\" y2=\"71\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"212\" y1=\"71\" x2=\"212\" y2=\"112.5\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"212\" y1=\"91.5\" x2=\"236\" y2=\"91.5\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"224\" y1=\"60\" x2=\"224\" y2=\"71\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/>\n<line x1=\"185\" y1=\"98\" x2=\"330\" y2=\"98\" stroke=\"#c47070\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n<text x=\"255\" y=\"94\" text-anchor=\"middle\" font-size=\"8\" fill=\"#c47070\">↑ここで切る＝グループ数が決まる</text>\n<text x=\"255\" y=\"144\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">木を先に作り、後で好きな高さで切る</text>\n</svg>"}'),
  ('g-kentei-f-q4', '3. 機械学習の概要',
   '手元のデータが少ないとき、1回だけ訓練用とテスト用に分けるホールドアウト法よりも、k分割交差検証の方が評価が安定しやすいと言われる。その理由として最も適切なものはどれか。',
   NULL::text,
   '["検証に使うデータの組を毎回入れ替えてk回評価し平均するため、たまたま簡単・難しいデータが検証側に偏る運の悪さが均される", "k分割交差検証は、手元のデータそのものを増やせるわけではないのに、訓練に使えるデータの量をホールドアウト法より多く増やせるから", "k分割交差検証は、予測が正しかったかどうかを照らし合わせる正解ラベルが無くても評価を進められる方式だから", "ホールドアウト法は分け方の性質上、必ずテスト用データの件数が訓練用データの件数より多くなる方式だから"]',
   0, '[0]', 'single',
   '{"asked": "k分割交差検証がホールドアウト法より評価が安定しやすい「理由」を選ぶ問題。", "point": "検証を1回で終わらせず何回も役割を交代して平均するなら安定する。", "kid": "ホールドアウト法は、データを訓練用とテスト用に1回だけ分けて、その1回の結果だけを成績にする。もしテスト用にたまたま簡単な問題ばかり、あるいは難しい問題ばかりが集まってしまったら、実力とズレた点数が出てしまう。k分割交差検証は、データをk個に分け、検証役を1グループずつ交代しながらk回評価し、その平均を成績にする。1回だけの運に左右されにくくなる。", "eg": "たとえるなら、模試を1回受けただけの点数で実力を判断するのがホールドアウト法。たまたまその回だけ得意な単元ばかり出れば高得点、苦手な単元ばかり出れば低得点になる。k分割交差検証は、同じ人が5回模試を受けて平均点を見るようなもの。1回の運の良し悪しが薄まる。", "terms": [["ホールドアウト法", "データを訓練用とテスト用に1回だけ分けて評価する方法"], ["k分割交差検証", "データをk個に分け、検証役を交代しながらk回評価し平均する方法"]], "think": "なぜ平均を取ると安定するのかがカギ。データの分け方が違えば、検証用に集まる問題の難易度にも毎回ばらつきが出る。1回の分け方だけを見ると、そのばらつきがそのまま点数のブレになる。k分割交差検証はデータをk個の組に分け、毎回違う組を検証役にしてk回評価するので、簡単な組に当たった回も難しい組に当たった回も両方含まれる。それらを平均すれば、特定の1回の運の良し悪しが打ち消し合い、実力に近い値に近づく。だから安定する。", "vs": "「データ量が増えるから安定する」と誤解しやすいが、k分割交差検証も使えるデータの総量はホールドアウト法と同じ。安定する理由はデータ量ではなく、検証を複数回行い平均を取ることにある。", "why_asked": "ホールドアウト法とk分割交差検証、どちらも定義は覚えていても「なぜk分割の方が安定するのか」という理由まで説明できるかを試す。定義の丸暗記では答えられない。", "usecase": "手元のデータ件数が少なく、1回の分け方による点数のブレが無視できない場面（医療データなど件数が限られる分析）でk分割交差検証が選ばれる。", "opt": ["正解。検証役を交代しながらk回評価して平均するため、1回だけの分け方に潜む運の偏りが均される。", "k分割交差検証でも、使えるデータの総量はホールドアウト法と変わらない。増えるのは評価の回数であって量ではない。", "交差検証も正解ラベルを使って評価する教師あり学習の評価手法であり、ラベルは必要。", "ホールドアウト法の訓練用とテスト用の比率は決め方次第で、テスト用が多くなるとは限らない。"], "calc": "5分割交差検証を例に、実際の動きを数字で見てみる。①日本語で言うと：データ全部を5つの箱に分け、毎回1箱だけ検証役、残り4箱を訓練役にする。これを5回繰り返し、5回分の点数を平均する。②小さい数字でステップを追う：データが100件あるとする。100件を5つの箱（1箱20件）に分ける。1回目は箱1が検証用（20件）、箱2〜5が訓練用（80件）。2回目は箱2が検証用、残りが訓練用。これを5回目（箱5が検証用）まで繰り返す。5回分の点数（例：82点、79点、85点、80点、84点）が出たら、これを合計して5で割り、平均82点を最終成績とする。③記号で書くと、k=5（分割数）のとき、毎回の訓練データは全体の (k-1)/k = 4/5 = 80%、検証データは 1/k = 1/5 = 20%。5回分の点数の平均が最終スコアになる。", "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"10\" y=\"16\" font-size=\"11\" fill=\"#e8eaf0\">ホールドアウト（1回だけ分ける）</text>\n<rect x=\"10\" y=\"24\" width=\"256\" height=\"18\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"266\" y=\"24\" width=\"64\" height=\"18\" fill=\"#c47070\" opacity=\"0.6\"/>\n<text x=\"138\" y=\"37\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">訓練 80%</text>\n<text x=\"298\" y=\"37\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">検証20%</text>\n<text x=\"10\" y=\"58\" font-size=\"9\" fill=\"#8892a4\">→ 検証の1回がたまたま簡単/難しいと評価がぶれる</text>\n\n<text x=\"10\" y=\"80\" font-size=\"11\" fill=\"#e8eaf0\">5分割交差検証（役割を交代しながら5回）</text>\n<g>\n<rect x=\"10\" y=\"90\" width=\"64\" height=\"16\" fill=\"#c47070\" opacity=\"0.6\"/>\n<rect x=\"74\" y=\"90\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"138\" y=\"90\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"202\" y=\"90\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"266\" y=\"90\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n</g>\n<g>\n<rect x=\"10\" y=\"110\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"74\" y=\"110\" width=\"64\" height=\"16\" fill=\"#c47070\" opacity=\"0.6\"/>\n<rect x=\"138\" y=\"110\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"202\" y=\"110\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n<rect x=\"266\" y=\"110\" width=\"64\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.55\"/>\n</g>\n<text x=\"10\" y=\"140\" font-size=\"9\" fill=\"#8892a4\">赤=検証に回る番。5回の平均を成績にする→運のブレを均せる</text>\n</svg>"}'),
  ('g-kentei-f-q5', '3. 機械学習の概要',
   '退会予測モデルを作る際、次のうちデータリーケージ（本来使えないはずの情報が紛れ込む問題）に該当する操作はどれか。',
   NULL::text,
   '["「退会手続き完了日」など、退会が確定した後にしか分からない項目を、退会するかどうかを予測する特徴量として使ってしまう", "訓練データとテストデータを、時系列の前後関係を無視せずに古い期間と新しい期間できちんと分けて用意する", "訓練データだけを使って標準化に使う平均や分散を計算しておき、その同じ値をテストデータの変換にも適用する", "特徴量を選ぶかなり前の段階で、目的（退会するかどうか）とはあまり関係が薄いとすでに分かっている項目をあらかじめ除いておく"]',
   0, '[0]', 'single',
   '{"asked": "データリーケージに当たる具体的な操作はどれかを選ぶ問題。", "point": "予測したい未来の答えに直結する情報が、こっそり入力側に混ざっているならリーケージ。", "kid": "データリーケージとは、本番でモデルが実際に予測を行う時点ではまだ分からないはずの情報が、訓練データにこっそり混ざってしまう問題。「退会手続き完了日」は、退会した人にしか存在しない項目で、これが分かっているなら「退会するかどうか」はもう答えが出ているのと同じ。これを予測の材料に使うと、訓練やテストでは異常に高い点数が出るのに、本番では全く当たらなくなる。", "eg": "たとえるなら、テスト前に「今日のテストで何点取ったか」という結果の欄を見ながら「何点取れそうか」を予想する練習をするようなもの。練習中は毎回満点に見えるが、本番でその結果欄は存在しないので、全く役に立たない。", "terms": [["データリーケージ", "予測時点では手に入らない情報が、訓練データに紛れ込んでしまう問題"], ["特徴量", "予測のために入力として使うデータの各項目"]], "think": "見分け方は「その項目は、実際に予測したい未来の瞬間より前に分かる情報か」を確認すること。「退会手続き完了日」は退会という結果が起きた後にしか存在しない項目であり、これを特徴量に使うのは、答えを先に教えてから同じ答えを当てさせているのと同じ状態。他の3つの選択肢は、時系列を守った分割、訓練データだけで統計量を計算してテストに流用する正しいやり方、目的と無関係な項目の除去であり、いずれも未来の答えを混ぜ込んではいない。", "vs": "「特徴量を減らす操作」全般をリーケージと混同しやすいが、無関係な項目を除く（選択肢4）のはむしろ正しい前処理。リーケージの本質は「未来の答えが混ざること」であって、項目を選ぶこと自体ではない。", "why_asked": "定義（未来の情報が混ざる問題）は暗記していても、実際の操作のどれがそれに当たるかを見抜けるかを試す。検証では高得点なのに本番で急に精度が落ちるという実務の落とし穴に直結する。", "usecase": "特徴量を設計する際、各項目が「予測したい時点より前に本当に手に入るデータか」を一つずつ確認する習慣が、本番での精度低下を防ぐ。", "opt": ["正解。退会手続き完了日は退会という結果が確定した後にしか存在せず、これを使うのは未来の答えを混ぜ込むデータリーケージに当たる。", "時系列を守って古い期間と新しい期間で分けるのは、むしろリーケージを防ぐ正しいやり方。", "訓練データだけで統計量を計算しテストへ適用するのは、リーケージを避ける標準的な正しい手順。", "目的と関係の薄い項目を事前に除くのは通常の前処理であり、未来の情報を混ぜ込む操作ではない。"]}'),
  ('g-kentei-f-q6', '3. 機械学習の概要',
   '機械学習モデルの「汎化性能」とは何を指す言葉か。最も適切なものを選べ。',
   NULL::text,
   '["訓練データには含まれていない、未知のデータに対してどれだけ正しく予測できるかという性能", "訓練データそのものに対して、学習を重ねながらどれだけ誤差を小さくして当てはめられるかという性能", "モデルの中で調整できるパラメータの数を、どこまで増やせるかという上限の大きさ", "モデルを1回学習させ終えるまでにかかった計算時間の短さ"]',
   0, '[0]', 'single',
   '{"asked": "「汎化性能」という言葉が何を指すかを選ぶ問題。", "point": "汎化性能は「見たことのないデータ」に対する強さを指す言葉。", "kid": "汎化性能とは、モデルが訓練で見たことのないデータ（本番で初めて出会うデータ）に対して、どれだけ正しく予測できるかという力のこと。訓練データに対してどれだけ点数が良いかとは別の話。", "eg": "たとえるなら、授業で解いた問題だけを丸暗記して満点を取れる生徒より、授業では見なかった新しい問題でもちゃんと解ける生徒の方が「応用力（汎化性能）が高い」と言える。試験の点数（訓練データの成績）が良くても、応用力が高いとは限らない。", "terms": [["汎化性能", "未知のデータに対する予測の正しさ"], ["過学習（オーバーフィッティング）", "訓練データに合わせすぎて、汎化性能が下がってしまった状態"]], "think": "本来モデルに求めているのは、訓練データそのものを覚えることではなく、本番で出会う未知のデータをうまく扱えること。訓練データの成績だけを追い求めて複雑にしすぎると、訓練データの細かいクセや誤差まで覚え込んでしまい、未知のデータでは逆に外しやすくなる。この「未知のデータでの強さ」そのものを指す言葉が汎化性能であり、これが低い状態を指す言葉が過学習。つまり汎化性能は目指すゴール、過学習はそのゴールから外れた失敗状態という関係。", "vs": "「訓練データの成績が良い＝汎化性能が高い」と思い込みやすいが、これは誤り。訓練データの成績は汎化性能を保証しない。むしろ訓練データに合わせすぎると汎化性能が下がることもある（過学習）。", "why_asked": "過学習・未学習という失敗の名前は覚えていても、その裏にある「本来目指すべき状態」を指す言葉（汎化性能）を正確に説明できるかを試す。目的語を取り違えると評価指標の選び方も誤る。", "usecase": "モデルを訓練データだけで評価せず、検証データやテストデータでの成績を見て汎化性能を確認する、という評価の基本姿勢につながる。", "opt": ["正解。汎化性能は、訓練で見ていない未知のデータに対する予測の正しさを指す。", "これは訓練データへの当てはまりの良さの説明で、汎化性能とは別の話。訓練成績が良くても汎化性能が高いとは限らない。", "パラメータ数の上限は汎化性能と直接は関係ない。むしろ増やしすぎは汎化性能を下げる原因になりうる。", "計算時間の短さは効率の話であり、予測の正しさを指す汎化性能とは無関係。"]}'),
  ('g-kentei-f-q7', '3. 機械学習の概要',
   '工場の検品AIで「不良品を絶対に見逃したくない（多少、正常品を不良品と誤って止めてしまっても構わない）」場合、優先して高めたい評価指標はどれか。',
   NULL::text,
   '["再現率", "適合率", "正解率（Accuracy）", "決定係数"]',
   0, '[0]', 'single',
   '{"asked": "「見逃しを避けたい」場面でどの評価指標を優先すべきかを選ぶ問題。", "point": "見逃しを避けたいなら再現率、誤検知を避けたいなら適合率。", "kid": "再現率は「本当に不良品だったものの中で、ちゃんと不良品だと言い当てられた割合」を測る指標。見逃し（本当は不良品なのに正常品と判定してしまうこと）を減らしたいときは、この再現率を優先して高くする。適合率は「不良品だと判定したものの中で、本当に不良品だった割合」を測る指標で、こちらは誤検知（本当は正常品なのに不良品と判定してしまうこと）を減らしたいときに優先する。", "eg": "たとえるなら、空港の手荷物検査。危険物を1つも見逃したくないので、少しでも怪しい荷物は全部止めて再検査する。これにより「本当は問題ない荷物」まで多く止めてしまう（誤検知が増える＝適合率は下がる）が、それでも見逃し（再現率の低下）の方を絶対に避けたい、という考え方と同じ。", "terms": [["再現率（Recall）", "実際に陽性（不良品）だったものの中で、正しく陽性と判定できた割合。見逃しの少なさを表す"], ["適合率（Precision）", "陽性と判定したものの中で、実際に陽性だった割合。誤検知の少なさを表す"], ["混同行列", "予測と実際の正解を突き合わせて、正解・見逃し・誤検知・正しい棄却の4つに分けた表"]], "think": "見逃した場合の損害と、誤って止めてしまった場合の損害、どちらが大きいかで優先すべき指標が変わる。工場の検品で不良品を1つでも市場に出してしまうと、事故やクレームなど大きな損害につながる。一方、正常品を誤って止めてしまっても、再検査すれば済む程度の損害で収まる。つまり「見逃しの損害 ＞ 誤検知の損害」という場面なので、見逃しの少なさを表す再現率を優先して高める判断になる。", "vs": "「正解率が一番大事」と考えがちだが、不良品が全体のごく一部しかない場合、全部を正常品と判定するだけで正解率は高く出てしまう罠がある。見逃しを避けたい場面では正解率ではなく再現率を見る。", "why_asked": "適合率と再現率、それぞれの定義は覚えていても、場面に応じてどちらを優先すべきかを判断できるかを試す。この試験では数値計算よりも場面判断で問われることが多い。", "usecase": "がん検診、不正取引の検出、工場の検品など「見逃すと大きな損害が出る」業務では再現率を優先し、迷惑メール判定など「誤検知が利用者の不満に直結する」業務では適合率を優先するといった使い分けに直結する。", "opt": ["正解。見逃し（本当は不良品なのに正常品と判定すること）を減らしたい場面では、再現率を優先して高める。", "適合率は誤検知の少なさを表す指標。誤検知は多少許容するとこの問題文にある以上、優先すべきは適合率ではない。", "正解率は不良品が少数派のデータでは高く出やすく、見逃しの多さを隠してしまうことがあるため、この場面では適していない。", "決定係数は回帰（連続値の予測）の当てはまりを測る指標で、不良品を見分ける分類の場面には使わない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">混同行列：どの列・行を見るか</text>\n<line x1=\"90\" y1=\"30\" x2=\"90\" y2=\"118\" stroke=\"#2a2f3f\"/>\n<line x1=\"90\" y1=\"74\" x2=\"270\" y2=\"74\" stroke=\"#2a2f3f\"/>\n<line x1=\"90\" y1=\"30\" x2=\"270\" y2=\"30\" stroke=\"#2a2f3f\"/>\n<line x1=\"90\" y1=\"118\" x2=\"270\" y2=\"118\" stroke=\"#2a2f3f\"/>\n<line x1=\"180\" y1=\"30\" x2=\"180\" y2=\"118\" stroke=\"#2a2f3f\"/>\n<line x1=\"270\" y1=\"30\" x2=\"270\" y2=\"118\" stroke=\"#2a2f3f\"/>\n<text x=\"135\" y=\"24\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">陽性と予測</text>\n<text x=\"225\" y=\"24\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">陰性と予測</text>\n<text x=\"60\" y=\"55\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">実際は</text>\n<text x=\"60\" y=\"65\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">陽性</text>\n<text x=\"60\" y=\"99\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">実際は</text>\n<text x=\"60\" y=\"109\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">陰性</text>\n<rect x=\"90\" y=\"30\" width=\"90\" height=\"44\" fill=\"#6ab08d\" opacity=\"0.35\"/>\n<text x=\"135\" y=\"55\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">正解(TP)</text>\n<rect x=\"180\" y=\"30\" width=\"90\" height=\"44\" fill=\"#c47070\" opacity=\"0.3\"/>\n<text x=\"225\" y=\"55\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">見逃し(FN)</text>\n<rect x=\"90\" y=\"74\" width=\"90\" height=\"44\" fill=\"#c47070\" opacity=\"0.3\"/>\n<text x=\"135\" y=\"99\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">誤検知(FP)</text>\n<rect x=\"180\" y=\"74\" width=\"90\" height=\"44\" fill=\"#8892a4\" opacity=\"0.15\"/>\n<text x=\"225\" y=\"99\" text-anchor=\"middle\" font-size=\"10\" fill=\"#e8eaf0\">正解(TN)</text>\n<rect x=\"88\" y=\"28\" width=\"94\" height=\"92\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\" rx=\"4\"/>\n<text x=\"135\" y=\"133\" text-anchor=\"middle\" font-size=\"9\" fill=\"#3b82f6\">適合率＝この列に注目（予測が当たっていた率）</text>\n</svg>"}'),
  ('g-kentei-f-q8', '3. 機械学習の概要',
   'アンサンブル学習の代表的な方式であるバギングとブースティングの違いとして、最も適切なものはどれか。',
   NULL::text,
   '["バギングは複数の学習器を並行して独立に学習させ多数決するのに対し、ブースティングは前の学習器の間違いを次の学習器が重点的に学びながら順番に追加していく", "バギングは前の学習器の間違いを次の学習器が重点的に学びながら順番に追加していく方式で、ブースティングは複数の学習器を並行して独立に学習させ多数決する方式であり、役割が丸ごと逆になっている", "どちらも学習器を1つずつ順番に追加していく方式であり、後の学習器にどれだけ重みを与えるかという計算式の細部だけが異なる", "どちらも複数の学習器を並行して独立に学習させる方式であり、最後の多数決の取り方の細部だけが異なる"]',
   0, '[0]', 'single',
   '{"asked": "バギングとブースティングという2つのアンサンブル学習の「違い」を選ぶ問題。", "point": "同時並行で多数決ならバギング、前の間違いを次が引き継ぐ順番方式ならブースティング。", "kid": "バギングは、複数の学習器（例えば決定木）を、それぞれ違うデータの組を使って同時に・お互い関係なく学習させ、最後にその全員の多数決で答えを決める方式。ブースティングは、学習器を1つずつ順番に作っていき、後から作る学習器ほど「前の学習器がよく間違えた問題」を重点的に練習させる方式。", "eg": "たとえるなら、バギングは複数の人がそれぞれ別々にテスト問題を解き、最後に多数決で答えを決めるグループ学習。ブースティングは、1人目が解いた後、間違えた問題を先生がチェックして、2人目にはその間違えた問題を重点的に練習させ、3人目にはさらに残った間違いを練習させる、というリレー形式の勉強。", "terms": [["バギング（Bagging）", "複数の学習器を並行・独立に学習させ、多数決や平均でまとめる方式。ランダムフォレストが代表例"], ["ブースティング（Boosting）", "前の学習器の間違いを次の学習器が重点的に学びながら、順番に追加していく方式"], ["アンサンブル学習", "複数の学習器を組み合わせて、単体より高い精度を狙う手法の総称"]], "think": "なぜ「並行か、順番か」という違いが生まれるかがカギ。バギングは、それぞれの学習器がバラバラなデータの組を見て学ぶことで、各学習器の間違いのクセを散らし、多数決でそのクセを打ち消し合ってばらつき（分散）を減らす狙いがある。だから学習器同士は互いを見る必要が無く、並行に学習できる。一方ブースティングは、1つの学習器だけでは実力不足な部分（弱点）を、次の学習器が意図的に狙って補うことで、全体としての精度そのものを底上げする狙いがある。次の学習器は前の学習器の間違いを知らないと弱点を狙えないため、必ず順番に学習する必要がある。", "vs": "「両方とも複数の学習器を使うから同じ」と考えると、並行か順番かという構造の違いを見落とす。バギングは独立、ブースティングは前の結果に依存するという点が本質的に異なる。", "why_asked": "ランダムフォレスト（バギングの代表例）とブースティングの個々の定義は覚えていても、両者を並べて「何が違うか」を説明できるかを試す。定義の丸暗記だけでは頭の中で区別がつかなくなりやすい。", "usecase": "個々の学習器のばらつきを抑えて安定させたいならバギング、個々の学習器の実力そのものを底上げして精度を追求したいならブースティングが選ばれる。", "opt": ["正解。バギングは並行・独立に学習し多数決、ブースティングは前の間違いを次が重点的に学びながら順番に追加していく。", "バギングとブースティングの説明が入れ替わっている。", "バギングは学習器を並行・独立に学習させる方式であり、順番に追加していくのはブースティングの特徴。", "ブースティングは学習器を順番に追加していく方式であり、並行・独立に学習させるのはバギングの特徴。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"80\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">バギング（並行・独立）</text>\n<circle cx=\"30\" cy=\"40\" r=\"12\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<circle cx=\"80\" cy=\"40\" r=\"12\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<circle cx=\"130\" cy=\"40\" r=\"12\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"30\" y=\"44\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">木1</text>\n<text x=\"80\" y=\"44\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">木2</text>\n<text x=\"130\" y=\"44\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">木3</text>\n<line x1=\"30\" y1=\"52\" x2=\"75\" y2=\"80\" stroke=\"#60a5fa\"/>\n<line x1=\"80\" y1=\"52\" x2=\"80\" y2=\"80\" stroke=\"#60a5fa\"/>\n<line x1=\"130\" y1=\"52\" x2=\"85\" y2=\"80\" stroke=\"#60a5fa\"/>\n<rect x=\"55\" y=\"80\" width=\"50\" height=\"18\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/>\n<text x=\"80\" y=\"92\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">多数決</text>\n<text x=\"80\" y=\"112\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">別々のデータで同時に学習し</text>\n<text x=\"80\" y=\"123\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">ばらつきを平均でならす</text>\n\n<text x=\"255\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">ブースティング（直列・逐次）</text>\n<circle cx=\"190\" cy=\"50\" r=\"12\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/>\n<text x=\"190\" y=\"54\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">木1</text>\n<line x1=\"202\" y1=\"50\" x2=\"228\" y2=\"50\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/>\n<circle cx=\"240\" cy=\"50\" r=\"12\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/>\n<text x=\"240\" y=\"54\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">木2</text>\n<line x1=\"252\" y1=\"50\" x2=\"278\" y2=\"50\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/>\n<circle cx=\"290\" cy=\"50\" r=\"12\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/>\n<text x=\"290\" y=\"54\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">木3</text>\n<text x=\"240\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#c47070\">前の木の間違いを次の木が重点的に学ぶ</text>\n<text x=\"240\" y=\"112\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">1つずつ順番に、弱点を狙って直していく</text>\n<text x=\"240\" y=\"123\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">精度を段階的に押し上げる</text>\n</svg>"}'),
  ('g-kentei-f-q9', '3. 機械学習の概要',
   'サポートベクターマシンで、境界の内側に一部のデータ点がはみ出すことをあらかじめ許容し、その分だけ罰則を与えながら境界を引く方式を何と呼ぶか。',
   NULL::text,
   '["ソフトマージン", "ハードマージン", "グリッドサーチ", "アンサンブル学習"]',
   0, '[0]', 'single',
   '{"asked": "SVMで境界の内側への一部のはみ出しを許容する方式の名前を選ぶ問題。", "point": "はみ出しを一切許さないならハードマージン、少し許すならソフトマージン。", "kid": "サポートベクターマシンは、2つのグループを分ける境界線を、その境界からの余白（マージン）が最大になるように引く手法。ハードマージンは、この境界の内側に1点も入り込むことを許さない、厳しいやり方。ソフトマージンは、境界の内側に多少のデータ点が入り込んでも構わないとして、その分だけ小さな罰則を与えながら、それでもなるべく広いマージンを探すやり方。", "eg": "たとえるなら、ハードマージンは「1人の落第者も出さずに完璧に2クラスに分ける」ことにこだわる先生。少しでも紛らわしい生徒が1人いるだけで分け方自体が決まらなくなってしまう。ソフトマージンは「多少の例外（分けにくい生徒）は仕方ないと割り切りつつ、できるだけきれいに2クラスに分ける」先生。現実のデータにはノイズや例外がつきものなので、この割り切りが役立つ。", "terms": [["ハードマージン", "境界の内側に1点も入ることを許さない、厳格なSVMの引き方"], ["ソフトマージン", "境界の内側への多少のはみ出しを罰則付きで許容する、現実的なSVMの引き方"], ["サポートベクターマシン（SVM）", "境界と最も近いデータとの余白（マージン）が最大になるように境界を引く分類手法"]], "think": "なぜソフトマージンの方が実務で使われやすいのかがカギ。現実のデータには、測定ミスや例外的な事例（ノイズ）がどうしても混ざる。ハードマージンのように「1点もはみ出させない」と決めてしまうと、たった1つの例外的な点のせいで境界の引き方が大きく歪んだり、そもそも完全に分け切れる境界が存在せず計算自体が成立しなくなったりする。ソフトマージンは、少数の点がはみ出すことを罰則付きで許すことで、1つの例外に振り回されずに、全体として見たときに一番自然な境界を引ける。だからノイズが混ざりがちな現実のデータではソフトマージンの方が扱いやすい。", "vs": "「マージンが広い方が良い」というSVMの基本と、「はみ出しを許すかどうか」という別の軸を混同しないこと。マージンを広く取る目的は共通だが、はみ出しを許すか許さないかで呼び方が変わる。", "why_asked": "SVMの「マージン最大化」という基本原理は知っていても、現実のノイズを扱うためのソフトマージンという工夫まで理解しているかを試す。ハードマージンだけを覚えていると、ノイズのあるデータへの対応を問われたときに答えられない。", "usecase": "実際の業務データには測定誤差や例外事例がほぼ必ず混ざるため、SVMを使う場面ではソフトマージンが標準的に使われる。", "opt": ["正解。境界の内側への多少のはみ出しを罰則付きで許容しながら境界を引く方式をソフトマージンと呼ぶ。", "ハードマージンは、境界の内側への1点のはみ出しも許さない厳格な方式で、この問題の説明とは逆。", "グリッドサーチはハイパーパラメータの候補を総当たりで試す方法で、マージンの許容とは無関係。", "アンサンブル学習は複数の学習器を組み合わせる手法で、境界のはみ出しの許容とは無関係。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"8\" y=\"14\" text-anchor=\"start\" font-size=\"9\" fill=\"#e8eaf0\">ハードマージン（1つも許さない）</text>\n<line x1=\"20\" y1=\"30\" x2=\"20\" y2=\"120\" stroke=\"#2a2f3f\"/>\n<line x1=\"20\" y1=\"120\" x2=\"150\" y2=\"120\" stroke=\"#2a2f3f\"/>\n<circle cx=\"40\" cy=\"50\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"55\" cy=\"40\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"35\" cy=\"65\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"100\" cy=\"95\" r=\"3.5\" fill=\"#6ab08d\"/>\n<circle cx=\"115\" cy=\"105\" r=\"3.5\" fill=\"#6ab08d\"/>\n<circle cx=\"120\" cy=\"85\" r=\"3.5\" fill=\"#6ab08d\"/>\n<line x1=\"65\" y1=\"35\" x2=\"90\" y2=\"115\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/>\n<line x1=\"55\" y1=\"35\" x2=\"80\" y2=\"115\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/>\n<line x1=\"75\" y1=\"35\" x2=\"100\" y2=\"115\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/>\n<text x=\"80\" y=\"135\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">境界の内側に1点も入れない</text>\n\n<text x=\"190\" y=\"14\" text-anchor=\"start\" font-size=\"9\" fill=\"#e8eaf0\">ソフトマージン（少しはみ出し許す）</text>\n<line x1=\"195\" y1=\"30\" x2=\"195\" y2=\"120\" stroke=\"#2a2f3f\"/>\n<line x1=\"195\" y1=\"120\" x2=\"325\" y2=\"120\" stroke=\"#2a2f3f\"/>\n<circle cx=\"215\" cy=\"50\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"230\" cy=\"40\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"210\" cy=\"65\" r=\"3.5\" fill=\"#3b82f6\"/>\n<circle cx=\"252\" cy=\"60\" r=\"3.5\" fill=\"#3b82f6\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n<circle cx=\"275\" cy=\"95\" r=\"3.5\" fill=\"#6ab08d\"/>\n<circle cx=\"290\" cy=\"105\" r=\"3.5\" fill=\"#6ab08d\"/>\n<circle cx=\"295\" cy=\"85\" r=\"3.5\" fill=\"#6ab08d\"/>\n<line x1=\"240\" y1=\"35\" x2=\"265\" y2=\"115\" stroke=\"#e8eaf0\" stroke-width=\"1.5\"/>\n<line x1=\"228\" y1=\"35\" x2=\"253\" y2=\"115\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/>\n<line x1=\"252\" y1=\"35\" x2=\"277\" y2=\"115\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/>\n<text x=\"255\" y=\"135\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">赤枠1点は境界の内側でも許容</text>\n</svg>"}'),
  ('g-kentei-f-q10', '3. 機械学習の概要',
   'モデルを少しずつ複雑にしながら訓練誤差と検証誤差を記録したところ、訓練誤差は下がり続けたが、検証誤差はある地点から下げ止まり、逆に上がり始めた。この「検証誤差が上がり始めた地点」から起きていると考えられる現象はどれか。',
   NULL::text,
   '["過学習（訓練データに合わせすぎて、未知データへの精度が落ちる状態）", "未学習（そもそも訓練データにすら十分に当てはめられていない状態）", "データリーケージ（本来使えないはずの未来の答えに当たる情報が紛れ込む問題）", "勾配消失（学習の合図が層を伝わるうちに小さくなり消えていく問題）"]',
   0, '[0]', 'single',
   '{"asked": "訓練誤差と検証誤差のグラフの形から、何が起きているかを読み取る問題。", "point": "訓練誤差は下がり続けるのに検証誤差が上がり始めたら過学習のサイン。", "kid": "訓練誤差は「訓練データそのものへの当てはまりの良さ」を表し、モデルを複雑にすればするほど基本的に下がり続ける（訓練データを丸暗記に近づけていけるから）。検証誤差は「まだ見ていないデータへの強さ」を表す。最初はモデルを複雑にするほど検証誤差も一緒に下がるが、あるところを境に、訓練データの細かいクセまで覚え込みすぎて、未知のデータでは逆に外しやすくなり、検証誤差が上がり始める。これが過学習の始まりのサイン。", "eg": "たとえるなら、参考書の例題を解けば解くほど、その例題自体はどんどん速く正確に解けるようになる（訓練誤差が下がり続ける）。しかし、例題の言い回しやクセまで丸暗記するようになると、初めて見る応用問題（検証データ）ではかえって間違いが増え始める。この「例題は完璧なのに応用問題で崩れ始める」瞬間が、グラフで検証誤差が上がり始める地点にあたる。", "terms": [["訓練誤差", "訓練データそのものに対する予測の誤差"], ["検証誤差", "訓練に使っていない検証データに対する予測の誤差"], ["過学習（オーバーフィッティング）", "訓練データに合わせすぎて、未知のデータへの精度がかえって落ちる状態"]], "think": "なぜ2つの誤差の動きが途中で分かれるのかがカギ。モデルを複雑にすると、訓練データのパターンだけでなく、訓練データに含まれる偶然のノイズ（たまたまの誤差やばらつき）まで拾って覚え込めるようになる。訓練データそのものに対しては、ノイズごと覚え込んだ方が誤差は小さくなるので、訓練誤差は複雑にするほど下がり続ける。しかし検証データにはそのノイズが同じ形では存在しないため、ノイズに合わせた部分はむしろ邪魔になり、検証誤差はある地点から悪化に転じる。この「訓練誤差は下がるのに検証誤差は上がる」というズレそのものが過学習の定義。", "vs": "未学習と混同しやすいが、未学習は訓練誤差自体がまだ高いまま下がりきっていない状態を指す。この問題では訓練誤差は下がり続けていると明記されているので、未学習ではなく過学習が起きていると判断できる。", "why_asked": "「過学習」という言葉の定義は暗記していても、実際のグラフの形からその発生地点を読み取れるかを試す。実務ではこのグラフを見て、複雑にしすぎる一歩手前で学習を止める判断（早期終了）につなげる。", "usecase": "訓練の途中で訓練誤差と検証誤差を両方記録し、検証誤差が上がり始めた地点を見つけて学習を止める（早期終了）判断など、実際のモデル開発で常に確認される。", "opt": ["正解。訓練誤差は下がり続けるのに検証誤差が上がり始める地点は、訓練データに合わせすぎて未知データへの精度が落ち始めた過学習のサイン。", "未学習は訓練誤差自体がまだ十分に下がっていない状態を指すが、この問題では訓練誤差は下がり続けていると書かれており当てはまらない。", "データリーケージは未来の情報が紛れ込む問題で、誤差のグラフの形だけからは判断できない別の問題。", "勾配消失は学習中に伝わる勾配（直してねの合図）が小さくなりすぎて学習が進まなくなる問題で、誤差のこのグラフの形とは別の現象。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">モデルを複雑にしていくと誤差はどう動くか</text>\n<line x1=\"30\" y1=\"20\" x2=\"30\" y2=\"120\" stroke=\"#2a2f3f\"/>\n<line x1=\"30\" y1=\"120\" x2=\"310\" y2=\"120\" stroke=\"#2a2f3f\"/>\n<text x=\"20\" y=\"20\" text-anchor=\"end\" font-size=\"8\" fill=\"#8892a4\">誤差</text>\n<text x=\"310\" y=\"132\" text-anchor=\"end\" font-size=\"8\" fill=\"#8892a4\">モデルの複雑さ →</text>\n<path d=\"M40,105 C90,70 160,45 300,35\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<text x=\"300\" y=\"30\" text-anchor=\"end\" font-size=\"8\" fill=\"#3b82f6\">訓練誤差（下がり続ける）</text>\n<path d=\"M40,110 C110,75 170,55 200,55 C240,58 270,80 300,105\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"2\"/>\n<text x=\"300\" y=\"112\" text-anchor=\"end\" font-size=\"8\" fill=\"#c47070\">検証誤差（途中から上がる）</text>\n<line x1=\"200\" y1=\"20\" x2=\"200\" y2=\"120\" stroke=\"#c9a04a\" stroke-width=\"1\" stroke-dasharray=\"3,2\"/>\n<text x=\"200\" y=\"132\" text-anchor=\"middle\" font-size=\"8\" fill=\"#c9a04a\">この境目から過学習</text>\n</svg>"}'),
  ('g-kentei-f-q11', '3. 機械学習の概要',
   'ランダムフォレストのように、多数の決定木をそれぞれ違うデータの組で学習させ多数決を取るバギングが、1本だけの決定木より予測が安定しやすい理由として最も適切なものはどれか。',
   NULL::text,
   '["個々の決定木の間違い方はデータの組ごとにばらつくため、多数決で平均すると、そのばらつき同士が互いに打ち消し合い、全体としての予測のブレが小さくなるから", "個々の決定木がそれぞれ全く同じデータの組をそのまま使って毎回同じ条件で学習するため、間違いの出方が完全に一致し、精度がそのまま足し算されて伸びていくから", "決定木の本数を増やせば増やすほど、1本あたりが実際に使えるデータの量そのものが増えていき、個々の決定木自体の精度が直接高くなっていくから", "全員の答えを多数決でまとめることによって、そもそも訓練データの中に含まれている誤りやノイズそのものが自動的に見つかって修正されるから"]',
   0, '[0]', 'single',
   '{"asked": "バギング（多数の決定木の多数決）が1本の決定木より安定する理由を選ぶ問題。", "point": "個々の間違い方がバラバラなら、多数決で打ち消し合って安定する。", "kid": "1本だけの決定木は、使うデータの組が少し変わるだけで、出来上がる木の形も予測も大きく変わってしまいやすい（不安定）。バギングは、少しずつ違うデータの組で多数の決定木を作り、その全員の多数決で最終的な答えを決める。それぞれの木は違う組で学んでいるので間違え方もバラバラになり、多数決を取ると、ある木の間違いを他の木が正解でカバーする形になって、全体としての予測が安定する。", "eg": "たとえるなら、1人の審査員だけで合否を決めると、その人の体調やクセによって判定がブレやすい。何人もの審査員がそれぞれ別々の視点で審査し、最後に多数決で決めれば、1人の気まぐれなブレは他の審査員の判断で打ち消され、全体としての判定は安定する。", "terms": [["バギング（Bagging）", "複数の学習器を、少しずつ違うデータの組で並行・独立に学習させ、多数決や平均でまとめる方式"], ["分散", "予測結果がどれだけばらつくか、ブレの大きさを表す言葉"], ["ランダムフォレスト", "多数の決定木をバギングで組み合わせたアンサンブル学習の代表例"]], "think": "なぜ多数決を取ると安定するのかがカギ。1本の決定木は、学習に使うデータの組がほんの少し変わるだけで木の形が大きく変わってしまう性質（不安定さ）を持つ。これを複数の木それぞれについて起こすと、ある木はある方向に間違え、別の木は別の方向に間違えるというように、間違い方はバラバラに散らばる。多数決や平均を取ると、ある木の間違いの方向と別の木の間違いの方向が互いに打ち消し合い、全体としての予測結果のブレ（分散）が小さくなる。個々の木の実力そのものを上げているわけではなく、集団としてのブレを均していることが安定の理由。", "vs": "「本数を増やせば個々の木自体が賢くなる」と考えるのは誤り。バギングが改善するのは個々の精度ではなく、集団として見たときの予測のブレ（分散）。個々の木の弱点そのものを補うのはブースティングの役割で、バギングとは狙いが異なる。", "why_asked": "ランダムフォレストの定義（多数の決定木の多数決）は覚えていても、「なぜそれで精度が安定するのか」という因果まで説明できるかを試す。定義止まりだと似た手法との違いを問われたときに答えられない。", "usecase": "1本の決定木では予測が学習データの組み方に敏感でブレやすい場面で、バギングを使い多数の木の多数決を取ることで、安定した予測を得るために使われる。", "opt": ["正解。個々の決定木の間違い方はデータの組ごとにバラバラになり、多数決で平均すると互いに打ち消し合ってブレが小さくなる。", "実際には決定木ごとに違うデータの組を使うのがバギングの前提であり、同じデータの組を使うわけではない。", "木の本数を増やしても1本あたりに使えるデータ量が増えるわけではなく、個々の木の精度が直接上がるとは限らない。", "多数決は個々の木の予測のブレを打ち消すのであって、訓練データそのものに含まれる誤りやノイズを直接修正するわけではない。"]}'),
  ('g-kentei-f-q12', '3. 機械学習の概要',
   'k分割交差検証で分割数kを大きくする（例えばk=10からk=データ件数と同数へ増やす）ほど起こりやすくなることとして最も適切なものはどれか。',
   NULL::text,
   '["毎回の訓練データの割合が増えて評価は元のモデルに近づく一方、評価を繰り返す回数が増えるため計算にかかる時間が長くなる", "毎回の訓練データとして使える割合がかえって減っていくため、評価の精度は分割数を増やすほど必ず悪化していく", "分割数kをどれだけ大きく増やしていっても、学習と評価を繰り返す回数は変わらず、計算にかかる時間もほぼ変わらない", "分割数kを大きく増やしていくと、検証のたびに正解ラベルと予測結果を照らし合わせて確認する作業そのものが不要になっていく"]',
   0, '[0]', 'single',
   '{"asked": "k分割交差検証の分割数kを大きくすると何が起こりやすいかを選ぶ問題。", "point": "kを増やすほど訓練データ割合は増えるが、評価の回数が増えて計算は重くなる。", "kid": "k分割交差検証は、データをk個に分けて、1個を検証用、残りk-1個を訓練用に使うことをk回繰り返す方法。kを大きくすると、毎回の訓練用に使えるデータの割合（k-1個分）が増えていく。ただし、k回評価を繰り返すこと自体は変わらないどころかkが増えた分だけ繰り返しの回数も増えるので、全部の計算にかかる時間は長くなっていく。", "eg": "たとえるなら、100人のクラスを10グループに分けて交代で1グループずつテストするのと、100グループ（1人1グループ）に分けて100回テストを繰り返すのとでは、後者の方が毎回ほぼ全員分のデータで練習できて本番に近い状態を再現できる一方、テストの回数そのものは10回から100回に増えるので、採点にかかる手間（計算時間）は大きく増える。", "terms": [["k分割交差検証", "データをk個に分け、検証役を交代しながらk回評価し平均する方法"], ["LOOCV（Leave-One-Out Cross Validation）", "直訳は「1つを除いて残す・交差検証」。分割数kをデータ件数と同じにする、交差検証の極端な形"]], "think": "なぜトレードオフが生まれるのかがカギ。kを大きくすると、1回あたりに検証用として抜き出すデータが少なくなる分、残りの訓練用データの割合（k-1個/k個）は100%に近づいていく。訓練データの割合が増えるほど、その回の評価は「全データを使って学習した本来のモデル」に近い状態で行われるので、評価としての信頼性は上がりやすい。しかし引き換えに、k回すべてについて毎回モデルを学習し直す必要があるため、kが大きいほど学習を繰り返す回数も増え、全体の計算時間は伸びていく。「評価の質」と「計算コスト」はこのように綱引きの関係にある。", "vs": "「kを増やすと必ず精度が上がる」という単純な話ではない。訓練データ割合が増える効果と、計算コストが増える負担の両方が同時に起きる点を押さえる。", "why_asked": "k分割交差検証の定義だけでなく、kという設定値を動かしたときに何がどう変わるかという実務的な感覚まで問う。定義の暗記だけでは「kはいくつが良いか」という判断ができない。", "usecase": "データ件数が少なく、少しでも多くのデータを訓練に使いたい場面ではkを大きくする判断がされるが、モデルの学習に時間がかかる場合はkを小さくして計算時間を抑えるといった使い分けに直結する。", "opt": ["正解。kを大きくすると毎回の訓練データ割合が増え評価は元のモデルに近づくが、評価を繰り返す回数が増えて計算時間は長くなる。", "訓練データの割合はkを増やすほど減るのではなく増える（k-1個/k個が1に近づく）ため誤り。", "kを増やすと学習・評価をやり直す回数が増えるため、計算時間は伸びるのが通常であり誤り。", "交差検証はどの分割数でも訓練・検証それぞれに正解ラベルを使う教師あり学習の評価手法であり、kを増やしてもラベルが不要になるわけではない。"]}'),
  ('g-kentei-f-q13', '4. ディープラーニングの概要',
   '住宅の価格をそのまま数値で予測するニューラルネットワークを作る。出力層に置く活性化関数として最も適切なものはどれか。',
   NULL::text,
   '["恒等関数（何もせずそのまま出力する）", "シグモイド関数（0〜1に押し込める）", "ソフトマックス関数（合計が1になるよう変える）", "ReLU関数（負の値を0にする）"]',
   0, '[0]', 'single',
   '{"asked": "回帰（数値をそのまま予測する）問題で、出力層にどんな活性化関数を置くべきかを問う設問。", "point": "出力が『そのままの数値』でよいなら、出力層は活性化関数なし（恒等関数）。0〜1に押し込めたり確率にしたりする活性化関数は分類向け。", "kid": "活性化関数は、出て行く数字を『こういう形に整えてね』と変換する装置。0〜1にしたり、合計を1にしたりする。でも住宅価格のように『そのままの数字』が欲しいときは、何も変換せず素通りさせるのが一番都合がいい。この『何もしない』変換のことを恒等関数と呼ぶ。", "eg": "宅配便で言えば、中身をそのまま届ける『そのまま配達』が恒等関数。中身を圧縮したり形を変えたりする配達(シグモイドやソフトマックス)は、分類問題という別の荷物向け。", "terms": [["恒等関数", "入力をそのまま出力する関数。何も変換しない、という意味で使われる"], ["シグモイド関数", "入力を0〜1の範囲に押し込む関数。二値分類の確率表現に使う"], ["ソフトマックス関数", "複数の値を合計が1になる確率分布に変える関数。多クラス分類に使う"]], "think": "出力層の活性化関数は『最終的に欲しい形』から逆算して選ぶ。二値分類なら『陽性である確率』が欲しいのでシグモイド、多クラス分類なら『各クラスの確率』が欲しいのでソフトマックスを使う。では回帰は何が欲しいか。0〜1に押し込められた確率ではなく、価格そのものの数値が欲しい。シグモイドやソフトマックスを出力層に置くと、値の範囲が0〜1や合計1に縛られてしまい、実際の価格(たとえば3000万円)を表現できなくなる。だから回帰では出力層に活性化関数を置かず、直前の層の計算結果をそのまま出力する。これを恒等関数と呼ぶ。", "vs": "シグモイド・ソフトマックスは『分類の確率』を作る道具であって、回帰の『そのままの数値』には向かない。ReLUは中間層でよく使われるが、出力層に置くと0未満の値を表現できず、負の値が必要な回帰では都合が悪い場合がある。", "why_asked": "『活性化関数=とにかく何か挟むもの』と覚えていると、回帰でも反射的にシグモイドやソフトマックスを選んでしまう。出力層の活性化関数は問題の種類(回帰/二値分類/多クラス分類)とセットで覚えているかを問う定番の切り口。", "usecase": "実務でモデルの出力層を設計するとき、回帰タスクなら活性化関数なし(恒等関数)、二値分類ならシグモイド、多クラス分類ならソフトマックスと即断できると、層設計のミスを防げる。", "opt": ["正解。回帰は『そのままの数値』が欲しいので、出力層には活性化関数を置かない（恒等関数）。", "シグモイド関数は出力を0〜1に押し込めるため、確率を表す二値分類の出力層向き。回帰の価格予測には向かない。", "ソフトマックス関数は複数の値の合計を1にする関数で、多クラス分類の確率表現に使う。回帰には使わない。", "ReLU関数は中間層でよく使われる活性化関数で、出力層で数値をそのまま予測する用途には使わない。"]}'),
  ('g-kentei-f-q14', '4. ディープラーニングの概要',
   'ReLU関数を活性化関数に使うと、入力がずっとマイナスのノードでは重みの更新が止まってしまうことがある。この現象は何と呼ばれるか。',
   NULL::text,
   '["dying ReLU（ReLUの死）", "勾配消失（層を重ねるうちに合図が薄まる現象）", "過学習（訓練データに合わせすぎる現象）", "モード崩壊（生成モデルの出力が偏る現象）"]',
   0, '[0]', 'single',
   '{"asked": "ReLU関数で、入力がずっとマイナスに落ち込んだノードが学習を止めてしまう現象の名前を問う設問。", "point": "ReLUはマイナスの入力を常に0にする。0の領域では傾き(勾配)も0なので、『直してね』の合図が止まり、そのノードは二度と目覚めない。これがdying ReLU。", "kid": "ReLUは『マイナスなら0、プラスならそのまま』という単純な関数。でも一度そのノードへの入力がずっとマイナス側に寄ってしまうと、出力はずっと0のまま。傾きが0ということは『どっちに直せばいいか』の合図(勾配)もずっと0で、重みが二度と更新されなくなる。まるでそのノードが眠ったまま起きてこないような状態で、これをdying ReLU(死んだReLU)と呼ぶ。", "eg": "工場のベルトコンベアで、ある機械だけずっと『停止中』ランプがついたまま。周りが動いていても、その機械には指示(勾配)が来ないので永遠に動かない。", "terms": [["ReLU（Rectified Linear Unit）", "直訳は「整流された線形の単位」。入力がマイナスなら0、プラスならそのまま通す活性化関数"], ["dying ReLU", "直訳は「死んでいくReLU」。入力が常にマイナス側になったノードの勾配が0のまま固まり、学習が進まなくなる現象"], ["勾配消失", "層を重ねるうちに『直してね』の合図(勾配)がどんどん小さくなり、手前の層まで届かなくなる現象。dying ReLUとは原因も起き方も別"]], "think": "なぜReLUで学習が止まるノードが出るのかがカギ。ReLUはx<0のとき出力が常に0で、その区間の傾き(微分)も常に0になる。重みの更新は『傾き×何かの量』で決まるので、傾きが0だと更新量も0になり、そのノードの重みは変わらないままになる。一度重みが『入力が常にマイナスになる』方向に振れてしまうと、その状態から抜け出す手段がなくなる。これがdying ReLU。勾配消失は『層を重ねるごとに合図が小さくなっていく』話で、1つのノードが完全に沈黙するdying ReLUとは起きる仕組みが違う。", "vs": "勾配消失は『深い層を伝わるうちに合図が薄まっていく』現象、dying ReLUは『1つのノードの傾きがぴったり0に固まって動かなくなる』現象。どちらも学習が進まなくなる点は似ているが、原因が『層の深さ』か『ReLUの折れ曲がり』かで別物。", "why_asked": "ReLUは『勾配消失を防ぐ』と習うため、ReLU自体には弱点がないと誤解しやすい。ReLUにも別種の弱点(dying ReLU)があることを知っているかを突く定番の切り口。", "usecase": "実務でReLUを使ったのに一部のノードの出力がずっと0のままだと気づいたら、dying ReLUを疑い、Leaky ReLUなど負の側にもわずかな傾きを持たせる改良版に切り替える判断ができる。", "opt": ["正解。ReLUはマイナスの入力を常に0にし、その区間の傾きも0になるため、そのノードの重みが更新されなくなる。これがdying ReLU。", "勾配消失は層を重ねるうちに合図が小さくなっていく現象で、1つのノードの傾きがぴったり0に固まる現象とは原因が異なる。", "過学習は訓練データに適合しすぎて未知データで成績が落ちる現象で、活性化関数の形とは別の話。", "モード崩壊は生成モデルが似たような出力ばかり作るようになる現象で、ReLUの弱点とは関係ない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n  <text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">ReLU関数：マイナス側は傾き0（dying ReLUの温床）</text>\n  <line x1=\"40\" y1=\"112\" x2=\"310\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n  <line x1=\"170\" y1=\"24\" x2=\"170\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n  <text x=\"308\" y=\"126\" font-size=\"9\" fill=\"#8892a4\">入力x</text>\n  <text x=\"176\" y=\"30\" font-size=\"9\" fill=\"#8892a4\">出力y</text>\n  <path d=\"M 40 112 L 170 112\" stroke=\"#c47070\" stroke-width=\"3\" fill=\"none\"/>\n  <path d=\"M 170 112 L 300 28\" stroke=\"#3b82f6\" stroke-width=\"3\" fill=\"none\"/>\n  <text x=\"60\" y=\"100\" font-size=\"10\" fill=\"#c47070\">勾配 0（ここで学習が止まる）</text>\n  <text x=\"200\" y=\"60\" font-size=\"10\" fill=\"#3b82f6\">勾配 1</text>\n  <text x=\"30\" y=\"122\" font-size=\"9\" fill=\"#8892a4\">-2</text>\n  <text x=\"165\" y=\"122\" font-size=\"9\" fill=\"#8892a4\">0</text>\n  <text x=\"295\" y=\"122\" font-size=\"9\" fill=\"#8892a4\">2</text>\n</svg>"}'),
  ('g-kentei-f-q15', '4. ディープラーニングの概要',
   '住宅価格をそのまま数値で予測する回帰モデルを学習させたい。学習の目印として使う誤差関数に最も適切なものはどれか。',
   NULL::text,
   '["平均二乗誤差（MSE）", "交差エントロピー誤差（分類でよく使う）", "ソフトマックス関数（活性化関数の一種）", "L2正則化（過学習を抑える仕組み）"]',
   0, '[0]', 'single',
   '{"asked": "回帰(価格をそのまま予測)で使うべき誤差関数(損失関数)を問う設問。", "point": "『予測値と正解の数値がどれだけ離れているか』を測りたいなら平均二乗誤差(MSE)。『予測した確率がどれだけ正解のクラスから外れているか』を測りたいなら交差エントロピー。回帰か分類かで使い分ける。", "kid": "誤差関数は『どれだけ間違えたか』を1つの数字にする物差し。回帰は『3000万円と予測したのに正解は3200万円だった』のように数値のズレを測りたいので、ズレを2乗して平均した平均二乗誤差(MSE)がぴったり合う。交差エントロピーは『猫である確率90%と予測したのに実は犬だった』のように確率のズレを測る道具で、分類向け。", "eg": "回帰の誤差はダーツの的からの距離(cm)を測るようなもの。分類の誤差は『自信満々で外れたか、迷った末に外れたか』を測るようなもの。物差しの種類が違う。", "terms": [["MSE（Mean Squared Error）", "直訳は「平均・二乗・誤差」。予測値と正解の差を2乗して平均した誤差関数。回帰で使う"], ["交差エントロピー誤差（Cross Entropy Error）", "直訳は「交差する・エントロピー」。予測した確率が正解からどれだけ外れているかを測る誤差関数。分類で使う"], ["損失関数", "誤差関数と同じ意味で使われる語。『どれだけ間違えたか』を1つの数字で表す"]], "think": "なぜ回帰と分類で誤差関数を使い分けるのかがカギ。回帰の出力は『3200万円』のような連続した数値で、正解との差をそのまま測れるので、差を2乗して平均するMSEが自然に合う。分類の出力は『猫である確率90%』のような0〜1の確率で、差をそのまま2乗しても『自信満々で外した』重さがうまく反映されない。交差エントロピーは、正解のクラスに割り当てた確率が低いほど誤差を急激に大きくする仕組みを持つので、確率のズレを厳しく測れる。だから回帰にはMSE、分類には交差エントロピーが使われる。", "vs": "ソフトマックス関数は出力層で確率分布を作る活性化関数であって、誤差を測る関数ではない。L2正則化は重みの大きさに罰を与えて過学習を防ぐ仕組みで、これも誤差関数そのものではない。", "why_asked": "『誤差関数』『活性化関数』『正則化』はどれも学習の途中に出てくる言葉で、名前と役割がごちゃまぜになりやすい。回帰か分類かで正しい誤差関数を即答できるかを突く定番の切り口。", "usecase": "実務でモデルを組むとき、回帰タスクの損失関数にMSE、分類タスクにクロスエントロピーを選ぶのは最初の設計判断そのもの。ここを間違えると学習がうまく進まない。", "opt": ["正解。回帰は数値そのもののズレを測りたいので、差を2乗して平均する平均二乗誤差(MSE)が使われる。", "交差エントロピー誤差は予測した確率のズレを測る誤差関数で、分類タスク向き。数値をそのまま予測する回帰には使わない。", "ソフトマックス関数は出力を確率分布に変える活性化関数であって、誤差を測る関数ではない。", "L2正則化は重みの大きさに罰を与えて過学習を防ぐ仕組みで、誤差関数そのものではない。"]}'),
  ('g-kentei-f-q16', '4. ディープラーニングの概要',
   '2個のデータについて、正解の値が [3, 7]、モデルの予測値が [5, 5] だった。平均二乗誤差(MSE)はいくつか。',
   NULL::text,
   '["4", "8", "0", "2"]',
   0, '[0]', 'single',
   '{"asked": "予測値と正解の値から、平均二乗誤差(MSE)を実際に計算させる設問。", "point": "MSEは『差を求める→2乗する→平均する』の3ステップ。2乗を忘れて差をそのまま平均すると、プラスとマイナスが打ち消し合って誤差を見誤る。", "kid": "MSEは『どれだけ外したか』を数字にする物差し。まず予測と正解の差を求める。次にその差を2乗する(マイナスの差もプラスになる)。最後に全部の2乗を平均する。2乗する理由は、プラスの外れとマイナスの外れが足し算で打ち消し合わないようにするため。", "eg": "ダーツで的の右に2cm外れた矢と、左に2cm外れた矢がある。『外れた向き』を無視して『外れた大きさ』だけを測りたいなら、距離を2乗して(プラスにして)から平均するのが理にかなっている。", "terms": [["MSE（Mean Squared Error）", "直訳は「平均・二乗・誤差」。予測と正解の差を2乗して平均した値"], ["Σ（シグマ）", "「全部足し合わせる」という意味の記号"], ["負の数の2乗", "マイナス×マイナスはプラスになる。だから差がマイナスでも2乗すれば必ずプラスになる"]], "think": "なぜ差をそのまま平均せず、2乗してから平均するのかがカギ。今回の例では、1つ目の差は+2(予測が高すぎた)、2つ目の差は-2(予測が低すぎた)。この2つをそのまま平均すると(2+(-2))÷2=0になり、まるで『完璧に当てた』ように見えてしまう。しかし実際には両方とも2ずつ外している。2乗すればマイナスの差もプラスになるので、打ち消し合わずに『外した大きさ』が正しく積み上がる。だからMSEは2乗してから平均する。", "vs": "差をそのまま平均する(2乗しない)と、プラスの誤差とマイナスの誤差が打ち消し合い、誤差がないように見えてしまう。絶対値の平均(MAE)は打ち消しは防げるが、MSEとは値が変わる(この例ではMAEは2、MSEは4)。", "why_asked": "MSEの定義を言葉だけで覚えていると、実際に数字を当てはめたときに2乗を忘れたり、平均を忘れたりする。手を動かして計算できるかを突く定番の切り口。", "usecase": "実務でモデルの学習曲線を見るとき、MSEの値がどのくらい下がったかを自分で検算できると、ライブラリが出す数字を鵜呑みにせず異常に気づける。", "opt": ["正解。(5-3)の2乗=4、(5-7)の2乗=4を足して8、データ数2で割ると4。これがMSE。", "8は2乗した値を足しただけで、データの個数で割る（平均する）のを忘れた値。", "0は差をそのまま(2乗せず)平均した値。プラスとマイナスの差が打ち消し合ってしまっている。", "2は差の絶対値を平均した値（MAE）。MSEとは計算の仕方が違う。"], "calc": "①日本語で言う: 予測値と正解の差を求めて、2乗して、平均する。\n②小さい数字で全ステップ: 1つ目のデータ、予測5-正解3=2。2乗すると2×2=4。2つ目のデータ、予測5-正解7=-2（マイナスになるが、2乗するとプラスになる）。2乗すると(-2)×(-2)=4。2つの2乗を足すと4+4=8。データの個数2で割ると8÷2=4。だからMSEは4。\n③記号版: MSE = (1/n) × Σ(予測 - 正解)の2乗。Σ(シグマ)は「全部足す」という意味の記号、nはデータの個数。ここではn=2。"}'),
  ('g-kentei-f-q17', '4. ディープラーニングの概要',
   'L1正則化がL2正則化と違って、重みの一部をちょうど0にできる（特徴量を実質的に選べる）のはなぜか。最も適切な理由はどれか。',
   NULL::text,
   '["L1は絶対値に比例した一定の力で引っぱるため、0の近くでも力が弱まらず0まで押し切れるから", "L1は重みを2乗して罰するため、大きい重みほど強く引っぱられ、結果として0に到達しやすいから", "L1は罰の強さをエポックごとに大きくしていく仕組みのため、学習の終盤に重みが0へ収束するから", "L1はドロップアウトと同じ仕組みで、ランダムに選んだ重みを0にリセットするから"]',
   0, '[0]', 'single',
   '{"asked": "L1正則化が重みをちょうど0にできる理由(なぜL2正則化と違うのか)を問う設問。", "point": "L1は重みの大きさに関わらず一定の力で引っぱるので0まで押し切れる。L2は重みが小さくなるほど引っぱる力も弱まるので0の手前で止まる。", "kid": "正則化は『重みを小さくしなさい』という罰を学習に足す仕組み。L2は重みを2乗して罰にするので、重みが小さくなるほど罰(引っぱる力)もどんどん弱くなり、0にたどり着く前に力尽きて止まる。L1は重みの絶対値をそのまま罰にするので、重みがどんなに小さくなっても引っぱる力は同じ強さのまま。だから0のすぐそばまで来ても押し切って、ちょうど0にできる。", "eg": "坂道を下るとき、L2はゴールに近づくほどブレーキが強くかかる坂(だんだん止まる)。L1はどこでも同じ強さで押される坂(最後まで押し切ってゴール＝0に着く)。", "terms": [["L1正則化", "重みの絶対値の合計を罰として誤差に足す仕組み。重みの一部をちょうど0にしやすい"], ["L2正則化", "重みの2乗の合計を罰として誤差に足す仕組み。重みを全体的に小さくするが、ちょうど0にはなりにくい"], ["スパース化", "直訳は「疎(まばら)にする」。重みの多くが0になり、少数の重要な入力だけが残ること"], ["絶対値", "プラスかマイナスかを気にせず、0からどれだけ離れているかの大きさ。-3も+3も絶対値は3"]], "think": "なぜL1だけがちょうど0にできるのかがカギ。正則化は『重みを小さくせよ』という罰を毎回の更新に足す仕組み。L2は重みの2乗を罰にするので、罰の効き目(引っぱる力)は重みの大きさに比例して弱まる。重みが小さくなるほど引っぱられなくなるので、0の手前でつり合って止まる。L1は重みの絶対値を罰にするので、引っぱる力は重みが大きくても小さくても一定のまま働き続ける。重みが小さくなっても力が弱まらないので、そのまま0まで押し切れる。結果として、L1では効かない入力の重みがちょうど0になって消え、効く入力だけが残る＝特徴量の選択が起きる。", "vs": "L2は『全体を薄く均等に小さくする』、L1は『効かないものはゼロに、効くものは残す』。どちらも過学習を防ぐ罰だが、0にできるかどうかの違いが特徴量選択に直結する。", "why_asked": "『L1は0にできる、L2はできない』という結論だけを暗記していると、理由を変えて問われたときに答えられない。なぜそうなるかの因果を理解しているかを突く定番の切り口。", "usecase": "実務で『不要な入力変数を自動的に削りたい』ときはL1正則化(Lasso)を選ぶ判断の根拠になる。逆に『全部の入力を少しずつ使いたい』ときはL2正則化(Ridge)を選ぶ。", "opt": ["正解。L1は絶対値に比例した一定の力で引っぱるため、重みが小さくなっても力が弱まらず、0まで押し切れる。", "これはL2の説明に近い。L2は重みを2乗して罰にするが、力が強まるのではなく、重みが小さいほど力が弱まる方向に働く。", "正則化の罰の強さはエポックごとに変化する仕組みではなく、毎回の更新で同じ式に基づいて計算される。", "L1正則化とドロップアウトは別の仕組み。ドロップアウトはノードをランダムに無効化する手法で、重みを0にする仕組みとは異なる。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n  <text x=\"170\" y=\"16\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">重みを引っぱる力：L1は一定、L2は弱まる</text>\n  <line x1=\"45\" y1=\"120\" x2=\"310\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n  <line x1=\"45\" y1=\"30\" x2=\"45\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n  <text x=\"250\" y=\"132\" font-size=\"9\" fill=\"#8892a4\">重みの大きさ →</text>\n  <text x=\"8\" y=\"40\" font-size=\"9\" fill=\"#8892a4\">引っぱる力</text>\n  <path d=\"M 45 55 L 300 55\" stroke=\"#3b82f6\" stroke-width=\"3\" fill=\"none\"/>\n  <text x=\"180\" y=\"46\" font-size=\"10\" fill=\"#3b82f6\">L1：力は一定 → 0まで押し切れる</text>\n  <path d=\"M 45 120 L 300 60\" stroke=\"#c9a04a\" stroke-width=\"3\" fill=\"none\"/>\n  <text x=\"170\" y=\"98\" font-size=\"10\" fill=\"#c9a04a\">L2：0に近づくほど力が弱まる</text>\n  <circle cx=\"46\" cy=\"120\" r=\"3\" fill=\"#6ab08d\"/>\n  <text x=\"52\" y=\"112\" font-size=\"9\" fill=\"#6ab08d\">重み0（L1はここまで押し切る）</text>\n</svg>"}'),
  ('g-kentei-f-q18', '4. ディープラーニングの概要',
   '数百個ある入力変数のうち、実際に効いているのはごく一部だと分かっている。効かない変数の重みを自動的にゼロへ落として絞り込みたいとき、どちらの正則化を選ぶべきか。',
   NULL::text,
   '["L1正則化", "L2正則化", "バッチ正規化", "早期終了"]',
   0, '[0]', 'single',
   '{"asked": "『効かない変数の重みを自動的に0へ落として絞り込みたい』という場面で、選ぶべき正則化はどちらかを問う設問。", "point": "『重みをちょうど0にして特徴量を選びたい』ならL1。『全体を均等に小さくして過学習を抑えたい』ならL2。", "kid": "L1正則化は、効かない入力の重みをちょうど0まで押し切る性質があるので、使われない変数を自動的に『無い』ことにできる。L2正則化は全体を薄く小さくするだけで、0にはなりにくいので、変数を絞り込む用途には向かない。", "eg": "L1は『使っていない部屋の電気は完全に消す』掃除の仕方。L2は『全部の部屋の電気を少しだけ暗くする』掃除の仕方。部屋(変数)を減らしたいならL1。", "terms": [["L1正則化", "重みの絶対値を罰にする仕組み。重みをちょうど0にしやすく、特徴量の選択に使われる"], ["L2正則化", "重みの2乗を罰にする仕組み。重みを全体的に小さくするが0にはなりにくい"], ["バッチ正規化", "各層に入ってくる値のばらつきをそろえて学習を安定させる手法。正則化とは目的が違う"], ["早期終了", "検証データの成績が悪化し始めたら学習を打ち切る過学習対策。重みを0にする仕組みではない"]], "think": "なぜL1が『変数の絞り込み』に向くのかがカギ。L1正則化は効かない重みをちょうど0まで押し切る性質を持つ。重みが0ということは、その入力変数は出力の計算に一切関わらなくなるということ。つまりL1正則化をかけて学習すると、効く変数の重みだけが残り、効かない変数の重みは自動的に消える。これは人手で変数を選ぶ作業を、学習の過程が代わりにやってくれているのと同じこと。L2正則化は重みを小さくはするが0にはしないので、変数の数自体は減らない。", "vs": "バッチ正規化と早期終了はどちらも学習を安定させたり過学習を抑えたりする工夫だが、『重みを0にして変数を選ぶ』働きは持たない。ここを混同すると『正則化っぽい言葉』というだけで誤答しやすい。", "why_asked": "『正則化』という括りの中で、L1・L2・バッチ正規化・早期終了をまとめて覚えていると、目的別に正しく選べているか怪しくなる。場面から正しい手法を選べるかを突く定番の切り口。", "usecase": "実務で入力変数(特徴量)が多すぎてモデルが複雑になりすぎているとき、L1正則化(Lasso回帰など)をかけて自動的に変数を絞り込む、という判断に直結する。", "opt": ["正解。L1正則化は効かない変数の重みをちょうど0にできるため、変数を自動的に絞り込む用途に向く。", "L2正則化は重みを全体的に小さくするが、ちょうど0にはなりにくいため、変数の数を減らす用途には向かない。", "バッチ正規化は各層に入る値のばらつきをそろえて学習を安定させる手法で、重みを0にして変数を選ぶ働きはない。", "早期終了は検証データの成績悪化を見て学習を止める過学習対策で、重みを0にする仕組みではない。"]}'),
  ('g-kentei-f-q19', '4. ディープラーニングの概要',
   'ドロップアウトが過学習を防ぐ効果を持つのはなぜか。最も適切な理由はどれか。',
   NULL::text,
   '["毎回違うノードを無効化して学習するため、複数の少し違うネットワークで学習させ平均するのと似た効果が生まれるから", "無効化されたノードの重みをその都度2乗して罰として誤差に足すため、重み全体が徐々に小さくなっていくから", "無効化するノードの数を層が深くなるにつれて自動的に増やしていく仕組みのため、勾配消失そのものが起きにくくなるから", "ノードを無効化するたびに学習率をわずかずつ下げていく仕組みのため、更新の振れ幅がだんだん小さくなるから"]',
   0, '[0]', 'single',
   '{"asked": "ドロップアウトが過学習を防ぐ理由（なぜ効くか）を問う設問。", "point": "毎回違うノードを休ませて学習するので、実質的に少しずつ違う複数のネットワークで学習して、その結果を平均しているのと同じ効果になる。これがドロップアウトが効く理由。", "kid": "ドロップアウトは、学習のたびに一部のノードをランダムに休ませる(出力を0にする)手法。休ませるノードは毎回違うので、まるで『少し形の違うネットワーク』をたくさん作って、それぞれに少しずつ学習させているのと同じことになる。1つのネットワークだけに頼ると、そのネットワークのクセ(訓練データだけに合わせた覚え方)に寄りすぎてしまう。複数の少し違うネットワークの結果を混ぜ合わせると、1つのクセに寄りすぎず、まんべんなく効く特徴だけが残りやすくなる。これが過学習を防ぐ理由。", "eg": "クラス全員(ノード)で問題を解くとき、毎回メンバーの何人かを休ませて残ったメンバーだけで答えを出す練習を繰り返すと、特定の1人に頼りきりの解き方にならず、誰が休んでも解ける『チームとしての実力』がつく。", "terms": [["ドロップアウト", "学習のたびに一部のノードをランダムに無効化(出力を0に)する過学習対策"], ["アンサンブル", "複数の少しずつ違うモデルの予測を組み合わせて、1つのモデルより安定した結果を得る考え方"], ["過学習", "訓練データに合わせすぎて、未知のデータでは成績が落ちてしまう状態"]], "think": "なぜランダムにノードを休ませるだけで過学習が防げるのかがカギ。過学習は、ネットワークが訓練データの細かいクセ(ノイズ)にまで無理に合わせてしまうときに起きる。1つの固定されたネットワークだけで学習すると、特定のノードの組み合わせが訓練データのクセを丸暗記してしまいやすい。ドロップアウトは学習のたびに違うノードを休ませるので、どのノードの組み合わせに対しても『それなりに正しい』重みを覚えるしかなくなる。これは、少しずつ違う多数のネットワークをまとめて学習させ、最後にその平均的な判断を使っているのと同じ効果を生む。特定の組み合わせへの丸暗記ができなくなるので、未知のデータにも強くなる。", "vs": "L2正則化は重みの大きさそのものに罰を与えて全体を小さくする仕組みで、ノードを休ませるドロップアウトとは手段が違う。勾配消失は層が深いときに合図が小さくなる別の問題で、ドロップアウトの目的(過学習対策)とは別の話。", "why_asked": "ドロップアウトの定義(ノードを無効化する)は覚えていても、『なぜそれで過学習が防げるのか』の因果まで説明できるかを突く定番の切り口。", "usecase": "実務で全結合層の後にDropout層を挟むかどうかを判断するとき、『複数の少し違うネットワークの平均を取る効果がほしいか』という視点で決められる。", "opt": ["正解。毎回違うノードを休ませることで、少しずつ違う複数のネットワークを学習させて平均するのと同じ効果が生まれ、特定の組み合わせへの丸暗記を防げる。", "ドロップアウトは重みを2乗して罰にする仕組みではない。それはL2正則化の仕組み。", "ドロップアウトで無効化するノードの数は層の深さに応じて自動で増える仕組みではなく、あらかじめ決めた割合でランダムに選ばれる。", "ドロップアウトは学習率を下げる仕組みではない。学習率とノードの無効化は別のパラメータ。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n  <text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">毎回ちがうノードを休ませる（少しずつ違うネットワークの平均）</text>\n\n  <text x=\"88\" y=\"30\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">学習1回目</text>\n  <circle cx=\"60\" cy=\"55\" r=\"9\" fill=\"#3b82f6\"/>\n  <circle cx=\"60\" cy=\"85\" r=\"9\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <circle cx=\"60\" cy=\"115\" r=\"9\" fill=\"#3b82f6\"/>\n  <circle cx=\"115\" cy=\"70\" r=\"9\" fill=\"#3b82f6\"/>\n  <circle cx=\"115\" cy=\"100\" r=\"9\" fill=\"#3b82f6\"/>\n  <line x1=\"60\" y1=\"55\" x2=\"115\" y2=\"70\" stroke=\"#2a2f3f\"/>\n  <line x1=\"60\" y1=\"115\" x2=\"115\" y2=\"70\" stroke=\"#2a2f3f\"/>\n  <line x1=\"60\" y1=\"55\" x2=\"115\" y2=\"100\" stroke=\"#2a2f3f\"/>\n  <line x1=\"60\" y1=\"115\" x2=\"115\" y2=\"100\" stroke=\"#2a2f3f\"/>\n  <text x=\"55\" y=\"87\" font-size=\"9\" fill=\"#c47070\">×</text>\n\n  <line x1=\"170\" y1=\"30\" x2=\"170\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n\n  <text x=\"252\" y=\"30\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">学習2回目</text>\n  <circle cx=\"225\" cy=\"55\" r=\"9\" fill=\"#3b82f6\"/>\n  <circle cx=\"225\" cy=\"85\" r=\"9\" fill=\"#3b82f6\"/>\n  <circle cx=\"225\" cy=\"115\" r=\"9\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n  <circle cx=\"280\" cy=\"70\" r=\"9\" fill=\"#3b82f6\"/>\n  <circle cx=\"280\" cy=\"100\" r=\"9\" fill=\"#3b82f6\"/>\n  <line x1=\"225\" y1=\"55\" x2=\"280\" y2=\"70\" stroke=\"#2a2f3f\"/>\n  <line x1=\"225\" y1=\"85\" x2=\"280\" y2=\"70\" stroke=\"#2a2f3f\"/>\n  <line x1=\"225\" y1=\"85\" x2=\"280\" y2=\"100\" stroke=\"#2a2f3f\"/>\n  <text x=\"220\" y=\"118\" font-size=\"9\" fill=\"#c47070\">×</text>\n\n  <text x=\"170\" y=\"149\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">休ませるノード（赤い×）は毎回ランダムに変わる</text>\n</svg>"}'),
  ('g-kentei-f-q20', '4. ディープラーニングの概要',
   '誤差逆伝播法で、出力層から入力層へ向かって各層の勾配を効率よく計算するために使われている数学の考え方はどれか。',
   NULL::text,
   '["連鎖律（合成関数の微分をかけ算でつなげる考え方）", "ベイズの定理（条件付き確率を更新する考え方）", "最小二乗法（誤差の2乗和を最小にする考え方）", "中心極限定理（データを集めるほど平均が正規分布に近づく考え方）"]',
   0, '[0]', 'single',
   '{"asked": "誤差逆伝播法が、出力層から入力層へ勾配を効率よく伝えるために使っている数学の考え方(仕組み)を問う設問。", "point": "誤差逆伝播法の中身は連鎖律。ネットワークは関数を何層も重ねた『合成関数』なので、層をまたぐ勾配は連鎖律のかけ算でつなげて求められる。", "kid": "ニューラルネットワークは、1層目の計算結果を2層目に渡し、2層目の結果を3層目に渡し…という『関数を何重にも重ねたもの』。ある重みを少し動かしたときに出力がどれだけ動くか(勾配)を知りたいとき、途中の層を1つずつたどって、『この層が動くとこれだけ動く』を層ごとにかけ算でつなげていくと、遠く離れた層への影響も計算できる。この『かけ算でつなげる』考え方を連鎖律と呼び、誤差逆伝播法はこれを出力層から入力層へ向かって順にたどることで、全部の重みの勾配を一度に計算している。", "eg": "伝言ゲームで、最後の人が『声の大きさをどれだけ変えればいいか』を、1つ前の人、そのまた1つ前の人…とさかのぼって伝えていく。各区間で『どれだけ影響するか』を掛け合わせながら伝えるのが連鎖律のイメージ。", "terms": [["連鎖律（Chain Rule）", "直訳は「鎖の・規則」。合成関数(関数を重ねたもの)の微分を、途中の各関数の微分のかけ算でつなげて求める考え方"], ["誤差逆伝播法（Backpropagation）", "直訳は「逆・伝播」。出力層で求めた誤差を入力層へ向かって順にたどりながら、連鎖律で各層の勾配を計算する手法"], ["勾配", "『どの向きにどれだけ重みを動かせば誤差が減るか』を表す量。『直してね』の合図"], ["微分", "ある値をほんの少し動かしたとき、結果がどれだけ動くか（＝坂の傾き）を求める計算"]], "think": "なぜ連鎖律が必要なのかがカギ。入力層に近い重みを少し動かしたとき、その影響は間にあるすべての層を経由して出力に伝わる。この『何層も経由した影響』を直接計算しようとすると、層が深いほど計算量が爆発してしまう。連鎖律を使うと、『この層が動くと次の層がこれだけ動く』という各層ごとの影響を、隣り合う層どうしだけで計算し、それを出力層から入力層へ向かって順にかけ算でつなげていくだけで済む。1つずつの区間の計算は軽いので、深い層でも効率よく全部の勾配を求められる。これが誤差逆伝播法の効率の正体。", "vs": "ベイズの定理・最小二乗法・中心極限定理はどれも統計や確率の重要な考え方だが、『層をまたいで勾配をかけ算でつなげる』仕組みそのものではない。最小二乗法はMSEという誤差関数の考え方に近いが、勾配を逆向きに伝える仕組みとは別の話。", "why_asked": "誤差逆伝播法を『出力の誤差を入力側へ伝える手法』とだけ覚えていると、その裏でどんな数学が動いているかを問われたときに答えられない。仕組みの中身まで理解しているかを突く定番の切り口。", "usecase": "実務でPyTorchやTensorFlowの自動微分(autograd)がなぜ深いネットワークでも高速に勾配を計算できるのかを理解するとき、連鎖律が土台にあることを知っていると挙動を追いやすい。", "opt": ["正解。ネットワークは関数を何層も重ねた合成関数であり、連鎖律を使って各層の影響をかけ算でつなげることで、効率よく勾配を計算できる。", "ベイズの定理は新しい証拠が来たときに確率を更新する考え方で、層をまたいで勾配をつなげる仕組みとは別物。", "最小二乗法は誤差の2乗和を最小にする考え方でMSEに近いが、勾配を出力層から入力層へ伝える仕組みそのものではない。", "中心極限定理はデータを集めるほど平均の分布が正規分布に近づくという統計の定理で、誤差逆伝播法の仕組みとは関係ない。"]}'),
  ('g-kentei-f-q21', '4. ディープラーニングの概要',
   'シグモイド関数だけでなくtanh関数を活性化関数に使っても、層が深いネットワークでは勾配消失が起きやすい。その共通の理由として最も適切なものはどれか。',
   NULL::text,
   '["どちらも入力が極端な領域でグラフがほぼ平らになり、傾きがほぼ0になるから", "どちらも出力の範囲が0〜1に限定されており、負の勾配を表現できないから", "どちらも計算に指数関数を使うため、計算コストが高く勾配を計算しきれないから", "どちらも出力の合計が1になるよう正規化されており、勾配が分散してしまうから"]',
   0, '[0]', 'single',
   '{"asked": "シグモイドだけでなくtanhでも勾配消失が起きやすい共通の理由を問う設問。", "point": "シグモイドもtanhも、入力が大きくなる/小さくなるとグラフがほぼ平らになる(飽和する)。平らな場所は傾きがほぼ0なので、そこを通るたびに『直してね』の合図が小さくされていく。", "kid": "シグモイドは0〜1、tanhは-1〜+1の範囲に出力を押し込める関数。どちらも、入力がある程度大きくなったり小さくなったりすると、グラフの形がほぼ横一直線(平ら)になる。平らということは、入力を少し変えても出力がほとんど変わらない＝傾き(勾配)がほぼ0ということ。層を重ねるたびにこのほぼ0の傾きを何度も掛け合わせると、伝わる『直してね』の合図はどんどん小さくなり、深い層では合図がほぼ消えてしまう。これが勾配消失。", "eg": "伝言ゲームで、間に『声がほとんど聞こえないくらい小さくささやく人』が何人も並んでいると想像する。最初の声がどんなに大きくても、そのゾーンを通るたびに音量が激減し、最後の人にはほぼ届かない。", "terms": [["飽和（サチュレーション）", "入力を大きく変えても出力がほとんど変わらなくなる、グラフが平らな状態"], ["tanh（ハイパボリックタンジェント）", "入力を-1〜+1の範囲に変換する活性化関数。シグモイドと同じく両端で飽和する"], ["勾配消失", "層を重ねるうちに『直してね』の合図(勾配)がどんどん小さくなり、手前の層まで届かなくなる現象"]], "think": "なぜシグモイドとtanhの両方で勾配消失が起きるのかがカギ。どちらの関数も、入力の絶対値が大きくなるとグラフがほぼ横一直線になる『飽和』という共通の性質を持つ。飽和した領域では傾きがほぼ0になる。誤差逆伝播法では、層をさかのぼるたびに各層の傾きを掛け合わせて勾配を求めるので、ほぼ0の傾きが何度も掛け合わされると、掛け算の結果はどんどん0に近づいていく。層が深いほど掛け合わせる回数が増えるので、入力層に近いところではほとんど合図が届かなくなる。これがシグモイド・tanhどちらでも起きる勾配消失の正体。ReLUは正の入力側で傾きが常に1で一定(飽和しない)ため、この掛け算で小さくなり続ける問題が起きにくい。", "vs": "出力範囲が0〜1に限定されること自体や、指数関数の計算コスト、出力の合計を1にする正規化は勾配消失の直接の原因ではない。原因は『傾きがほぼ0になる領域(飽和)を何度も通ること』。", "why_asked": "『シグモイドは勾配消失を起こす』とだけ暗記していると、tanhでも同じ問題が起きることや、その共通の理由(飽和)を問われたときに答えられない。原因の本質を理解しているかを突く定番の切り口。", "usecase": "実務で深いネットワークの中間層にシグモイドやtanhを使うと学習が進みにくいと感じたとき、飽和が原因だと見抜いてReLU系の活性化関数に切り替える判断ができる。", "opt": ["正解。シグモイドもtanhも入力が大きい／小さい領域でグラフがほぼ平らになり(飽和し)、その領域の傾きがほぼ0になるため、層を重ねるとその小さい傾きが掛け合わさって勾配が消える。", "シグモイドの出力範囲は0〜1だが、tanhの出力範囲は-1〜+1で0〜1に限定されていない。この選択肢はtanhには当てはまらない。", "指数関数の計算コストが高いのは事実だが、それは計算の重さの問題であり、勾配がほぼ0になって消えていく勾配消失の直接の原因ではない。", "シグモイドやtanhの出力は各ノードごとに独立して計算され、ソフトマックスのように出力の合計を1にする正規化は行っていない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n  <text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">シグモイド・tanhは両端が平ら（飽和＝傾きほぼ0）</text>\n  <line x1=\"40\" y1=\"115\" x2=\"310\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n  <path d=\"M 40 108 C 100 108, 140 32, 170 68 C 200 104, 240 28, 300 28\" stroke=\"#3b82f6\" stroke-width=\"3\" fill=\"none\"/>\n  <text x=\"45\" y=\"98\" font-size=\"9\" fill=\"#c47070\">飽和（傾きほぼ0）</text>\n  <text x=\"215\" y=\"45\" font-size=\"9\" fill=\"#c47070\">飽和（傾きほぼ0）</text>\n  <text x=\"150\" y=\"55\" font-size=\"9\" fill=\"#60a5fa\">ここだけ傾きが立つ</text>\n  <text x=\"40\" y=\"132\" font-size=\"9\" fill=\"#8892a4\">入力が小さい</text>\n  <text x=\"250\" y=\"132\" font-size=\"9\" fill=\"#8892a4\">入力が大きい</text>\n  <text x=\"40\" y=\"146\" font-size=\"9\" fill=\"#8892a4\">ReLUは正の側で傾きがずっと1のまま（飽和しない）</text>\n</svg>"}'),
  ('g-kentei-f-q22', '4. ディープラーニングの概要',
   '最適化手法が発展してきた順番として最も適切なものはどれか。',
   NULL::text,
   '["勾配降下法 → モメンタム → RMSProp → Adam", "Adam → RMSProp → モメンタム → 勾配降下法", "RMSProp → モメンタム → 勾配降下法 → Adam", "モメンタム → 勾配降下法 → Adam → RMSProp"]',
   0, '[0]', 'single',
   '{"asked": "GD(勾配降下法)からAdamまでの最適化手法が発展してきた順番を問う設問。", "point": "基本の勾配降下法に『勢い』を足したのがモメンタム、『歩幅の自動調整』を足したのがRMSProp、その両方を組み合わせたのがAdam、という順番で発展した。", "kid": "最適化手法は、基本のやり方に工夫を1つずつ足していく形で発展してきた。まず勾配降下法(誤差が減る方向へ重みを動かす基本のやり方)がある。次に、それに『前回までの動きの勢いを引き継ぐ』工夫を足したモメンタムが生まれた。次に、『方向ごとに歩幅(学習率)を自動で調整する』工夫を足したRMSPropが生まれた。最後に、モメンタムの『勢い』とRMSPropの『歩幅調整』の両方のいいとこ取りをしたAdamが生まれた。", "eg": "自転車の進化に似ている。最初はただのペダル(勾配降下法)。次にギアを足して坂で楽になる(モメンタム)。次に自動変速機を足してさらに楽になる(RMSProp)。最後にその両方を1台にまとめた最新モデル(Adam)。", "terms": [["勾配降下法", "誤差が減る方向(勾配の逆向き)へ重みを少しずつ動かす、最適化の基本の考え方"], ["モメンタム", "前回までの更新の『勢い』を引き継ぎ、揺れを抑えつつ速く進む工夫"], ["RMSProp", "勾配の大きさに応じて、方向ごとに歩幅(学習率)を自動調整する工夫"], ["Adam（Adaptive Moment Estimation）", "直訳は「適応的な・モーメント(勢い)の・推定」。モメンタムとRMSPropの両方の利点を組み合わせた最適化手法"]], "think": "なぜこの順番なのかがカギ。勾配降下法だけだと、谷が細長い地形では毎回大きく左右に揺れながら進むため収束が遅い。この揺れを抑えるために『前回の動きの勢い』を足したのがモメンタム。しかし、モメンタムだけでは全方向に同じ歩幅を使ってしまい、方向によって適切な歩幅が違う場合にうまく対応できない。そこで、方向ごとに勾配の大きさを見て歩幅を自動調整する工夫を足したのがRMSProp。最後に、モメンタムの『勢いで揺れを抑える』良さと、RMSPropの『方向ごとに歩幅を合わせる』良さを両方取り入れたのがAdam。それぞれ前の手法の弱点を1つずつ埋める形で発展してきたので、この順番になる。", "vs": "『AdamはRMSPropとモメンタムを組み合わせたもの』という結論だけを覚えていても、どちらが先に生まれたかの順番を逆にすると誤答になる。モメンタムとRMSPropはAdamより前に別々に存在していた手法。", "why_asked": "最適化手法の名前と特徴を個別には覚えていても、発展の順番(なぜその順で工夫が積み重なったか)まで理解しているかを突く定番の切り口。", "usecase": "実務で新しい最適化手法の論文を読むとき、『これは勾配降下法の何を改良したものか』という系譜の見方ができると、手法の位置づけを素早くつかめる。", "opt": ["正解。基本の勾配降下法に『勢い』を足したモメンタム、『歩幅の自動調整』を足したRMSProp、その両方を組み合わせたAdam、の順で発展した。", "この順番は逆になっている。Adamはモメンタムと、モメンタムより後発のRMSPropの両方を組み合わせたものなので、最後に生まれた手法。", "RMSPropはモメンタムより後に生まれた手法であり、この順番は入れ替わっている。", "モメンタムは勾配降下法に工夫を足したものであり、勾配降下法より先に生まれることはない。"]}'),
  ('g-kentei-f-q23', '4. ディープラーニングの概要',
   '学習を始めたところ、損失(誤差)の値が下がるどころか、回を追うごとにどんどん大きくなって発散してしまった。まず疑うべき原因として最も適切なものはどれか。',
   NULL::text,
   '["学習率が大きすぎる", "学習率が小さすぎる", "バッチサイズが大きすぎる", "エポック数が少なすぎる"]',
   0, '[0]', 'single',
   '{"asked": "損失が下がらずどんどん発散してしまうとき、まず疑うべき原因(学習率が大きすぎるか小さすぎるか)を問う設問。", "point": "損失が振動しながら大きくなっていく(発散する)なら学習率が大きすぎるサイン。損失がほとんど動かず遅いだけなら学習率が小さすぎるサイン。", "kid": "学習率は、1回の更新で重みをどれだけ大きく動かすかを決める値。谷底(誤差が一番小さい場所)を目指して坂を下るとき、歩幅(学習率)が大きすぎると、谷底を通り過ぎて反対側の斜面まで飛んでいってしまい、次はさらに反対側へ大きく飛ぶ…を繰り返して、どんどん谷から離れていく(発散)。歩幅が小さすぎる場合は、逆に谷底へは向かうが、ちょっとずつしか進まないので時間がかかるだけで、損失が大きくなって発散することはない。", "eg": "山道を大股(学習率が大きい)で下ろうとすると、足場を飛び越えて反対側の斜面に着地し、そこからまた大股で反対側へ…と行ったり来たりしながらどんどん道からそれていく。小股(学習率が小さい)なら遅いだけで、道を外れることはない。", "terms": [["学習率", "1回の更新で重みをどれだけ動かすかを決める値。歩幅にあたる"], ["発散", "損失の値が下がらず、回を追うごとにどんどん大きくなっていく状態"], ["収束", "損失の値が下がっていき、ある値に落ち着く状態"]], "think": "なぜ『発散＝学習率が大きすぎる』と判断できるのかがカギ。学習率が大きいと、1回の更新で重みが谷底を大きく飛び越えてしまう。飛び越えた先は谷底より誤差が大きい場所なので、損失はむしろ増える。次の更新でも同じくらい大きく動くので、また反対側へ飛び越え、誤差はさらに増える。これが繰り返されると、損失はどんどん大きくなっていき、発散する。一方、学習率が小さすぎる場合は、1回の更新で動く量が小さいだけなので、遅いけれど確実に谷底へ近づいていく。損失が増え続けることはない。したがって『損失がどんどん大きくなる』という症状は、歩幅が大きすぎて谷を飛び越え続けていることを示している。", "vs": "バッチサイズやエポック数も学習の設定値だが、これらは主に学習の速さや安定性に関わるもので、『損失がどんどん大きくなって発散する』症状の第一の疑い先は学習率。バッチサイズが大きすぎても発散よりは学習が遅くなる傾向が中心。", "why_asked": "学習率という言葉と『大きすぎると発散、小さすぎると遅い』という結論は覚えていても、実際に出た症状(発散)からどちらの異常かを逆算できるかを突く定番の切り口。実務でのデバッグそのもの。", "usecase": "実務で学習を回して損失がNaNになったり爆発的に増えたりしたとき、真っ先に学習率を下げてみる、という初動判断に直結する。", "opt": ["正解。学習率が大きすぎると、更新のたびに谷底を飛び越えてしまい、損失がどんどん大きくなって発散する。", "学習率が小さすぎる場合は、学習が遅く進むだけで、損失がどんどん大きくなって発散することは通常起きない。", "バッチサイズが大きすぎることは学習の速さや安定性に影響するが、損失が発散する症状の第一の疑い先ではない。", "エポック数が少なすぎることは学習が途中で終わってしまう原因にはなるが、損失がどんどん大きくなって発散する原因ではない。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n  <text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">学習率が大きすぎると谷を飛び越えて発散する</text>\n  <path d=\"M40,45 Q170,140 300,45\" stroke=\"#2a2f3f\" stroke-width=\"2\" fill=\"none\"/>\n\n  <polyline points=\"170,105 120,72 225,48 78,38\" stroke=\"#c47070\" stroke-width=\"2\" fill=\"none\"/>\n  <circle cx=\"170\" cy=\"105\" r=\"3\" fill=\"#c47070\"/>\n  <text x=\"45\" y=\"30\" font-size=\"9\" fill=\"#c47070\">学習率が大きすぎる→発散</text>\n\n  <polyline points=\"170,105 155,92 163,85 168,81\" stroke=\"#6ab08d\" stroke-width=\"2\" fill=\"none\"/>\n  <circle cx=\"168\" cy=\"81\" r=\"3\" fill=\"#6ab08d\"/>\n  <text x=\"185\" y=\"78\" font-size=\"9\" fill=\"#6ab08d\">ちょうど良い歩幅→収束</text>\n\n  <text x=\"170\" y=\"144\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">谷底＝損失が一番小さい場所</text>\n</svg>"}'),
  ('g-kentei-f-q24', '4. ディープラーニングの概要',
   'ある重みの現在の値は10、その重みに対する勾配は4、学習率は0.5だとする。勾配降下法の更新式「新しい重み = 現在の重み - 学習率 × 勾配」で重みを1回更新すると、新しい重みはいくつになるか。',
   NULL::text,
   '["8", "6", "12", "2"]',
   0, '[0]', 'single',
   '{"asked": "勾配降下法の更新式を使って、重みを実際に1回更新する計算をさせる設問。", "point": "更新式は『新しい重み = 今の重み - 学習率 × 勾配』。まず学習率と勾配を掛け算し、それを今の重みから引く、という順番を守る。", "kid": "重みを1回更新するときは、まず『学習率×勾配』を計算して、動かす量を求める。次に、その量を今の重みから引く。引く理由は、勾配が『誤差が増える向き』を指しているので、誤差を減らすには反対向き(引き算)に動かす必要があるから。", "eg": "今いる場所(重み10)から、坂の下り方向へ『歩幅(学習率0.5)×傾きの急さ(勾配4)』ぶんだけ進む。進んだ先が新しい重み8。", "terms": [["学習率（η・イータ）", "1回の更新で重みをどれだけ動かすかを決める値"], ["勾配", "『どちらの向きにどれだけ誤差が増えるか』を表す値。更新では逆向きに動くのでマイナスを付けて使う"]], "think": "なぜ『引く』のかがカギ。勾配は『重みを増やすと誤差がどれだけ増えるか』を表す量。勾配がプラスということは、重みを増やすと誤差も増える、つまり重みを減らせば誤差が減るということ。だから勾配の向きとは逆(マイナス)に重みを動かす。動かす量は、勾配の大きさに学習率を掛けて決める。学習率は『勾配1あたりどれだけ大きく動くか』を調整するつまみ。この例では学習率0.5×勾配4=2だけ動かす必要があり、逆向き(引き算)に動かすので、10-2=8になる。", "vs": "学習率と勾配を掛けずに重みからそのまま勾配を引く(10-4=6)のはよくある計算ミス。学習率は『動く量を調整するつまみ』であって、無視してよい値ではない。", "why_asked": "更新式を言葉では知っていても、実際に数字を当てはめて計算できるかは別。手を動かして検算できるかを突く定番の切り口。", "usecase": "実務で学習率を変えたときに重みの更新量がどう変わるかを見積もる感覚を養える。学習率を10倍にすると動く量も10倍になる、といった直感につながる。", "opt": ["正解。学習率0.5×勾配4=2を求め、現在の重み10から引くと10-2=8。", "学習率を掛けずに、現在の重みから勾配をそのまま引いた値(10-4=6)。学習率という『歩幅の調整』を忘れている。", "現在の重みに、学習率×勾配の値を足してしまった値(10+2=12)。誤差を減らすには引き算で逆向きに動く必要がある。", "学習率×勾配の計算結果(0.5×4=2)だけを答えてしまい、現在の重みから引く最後のステップを忘れている。"], "calc": "①日本語で言う: 学習率×勾配を求めて、それを現在の重みから引く。\n②小さい数字で全ステップ: 学習率0.5×勾配4=2。現在の重み10から2を引く。10-2=8。だから新しい重みは8。\n③記号版: w_new = w - η × g 。wは重み、η(イータ)は学習率、gは勾配。ここではw=10, η=0.5, g=4なので、w_new = 10 - 0.5×4 = 8。"}'),
  ('g-kentei-f-q25', '4. ディープラーニングの概要',
   'モメンタムが、谷が細長く傾いた地形でジグザグに揺れながら進んでしまう勾配降下法の欠点を改善できるのはなぜか。最も適切な理由はどれか。',
   NULL::text,
   '["前回までの更新方向を『勢い』として引き継ぎ、毎回反対に振れる方向の動きを打ち消し合わせるから", "方向ごとに勾配の大きさを見て、歩幅(学習率)を自動的に大きくしたり小さくしたりするから", "学習のたびに一部のノードをランダムに休ませることで、揺れの原因になっているノードを取り除くから", "重みの大きさに罰を与えて全体を小さく保つことで、そもそも大きく動けないように制限するから"]',
   0, '[0]', 'single',
   '{"asked": "モメンタムが、谷が細長い地形でのジグザグな揺れを抑えられる理由(なぜ効くか)を問う設問。", "point": "モメンタムは前回の動きの『勢い』を引き継ぐ。毎回向きが反転する揺れの成分は勢いどうしで打ち消し合い、毎回同じ向きに進む成分は勢いが積み重なって加速する。", "kid": "谷が細長く傾いていると、勾配降下法は谷の壁を行ったり来たりジグザグに揺れながら進んでしまう。モメンタムは、今回の動きを『今回の勾配だけ』で決めず、『前回までの動きの勢い』も少し混ぜて決める。ジグザグの揺れは毎回向きが反対になる動きなので、前回の勢いと今回の動きが逆向きにぶつかり合って打ち消され、揺れが小さくなる。一方、谷底へ向かう方向はいつも同じ向きなので、前回の勢いと今回の動きが同じ向きに重なって、どんどん加速する。だから揺れが減り、谷底へは速く進めるようになる。", "eg": "ボウリングの球を転がすとき、毎回左右に軽く押す力が加わっても、球自体に前へ進む勢い(慣性)があると、左右の力に振り回されにくく、まっすぐ奥へ転がり続ける。", "terms": [["モメンタム", "前回までの更新方向の『勢い』を引き継ぎながら重みを更新する工夫"], ["慣性", "動いているものがその動きを続けようとする性質。モメンタムはこれを更新の計算に取り入れたもの"], ["ジグザグ振動", "谷が細長く傾いた地形で、勾配降下法が谷の両壁を行ったり来たりしながら進んでしまう現象"]], "think": "なぜ『勢いを引き継ぐ』だけで揺れが収まるのかがカギ。ジグザグな揺れは、更新のたびに向きが反転する成分でできている。モメンタムでは、今回の更新量を『今回の勾配』と『前回までの勢い(前回の更新量の一部)』を足し合わせて決める。向きが毎回反転する成分は、今回の勾配と前回の勢いが逆向きになるので、足し合わせると打ち消し合って小さくなる。逆に、谷底へ向かう方向のように毎回同じ向きに働く成分は、今回の勾配と前回の勢いが同じ向きになるので、足し合わせるとどんどん大きくなっていく。振動する成分は打ち消され、一貫して進みたい成分は加速される。この2つが同時に起きるので、揺れが減りながら谷底へは速く進めるようになる。", "vs": "RMSPropは方向ごとに歩幅を自動調整する仕組みで、『勢いを引き継ぐ』モメンタムとは仕組みが違う(Adamは両方を組み合わせたもの)。ドロップアウトはノードを休ませる仕組み、正則化は重みの大きさに罰を与える仕組みで、どちらもジグザグ振動を抑える直接の仕組みではない。", "why_asked": "モメンタムの定義(前回の勢いを引き継ぐ)は覚えていても、『なぜそれで揺れが収まるのか』の因果まで説明できるかを突く定番の切り口。RMSPropとの取り違えも起きやすい。", "usecase": "実務で損失がジグザグに振動しながらなかなか収束しないとき、モメンタムを使った最適化手法(SGD+Momentumなど)に切り替える判断の根拠になる。", "opt": ["正解。前回までの更新方向を『勢い』として引き継ぐことで、毎回反対向きに振れる成分は打ち消され、同じ向きに進む成分は積み重なって加速する。", "これはRMSPropの仕組み。方向ごとに勾配の大きさを見て歩幅を自動調整するのはモメンタムとは別の工夫。", "これはドロップアウトの仕組み。一部のノードを休ませるのは過学習対策であり、ジグザグな揺れを抑える仕組みとは別。", "これは正則化の仕組み。重みの大きさに罰を与えるのは過学習対策であり、揺れを抑える仕組みとは別。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n  <text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">モメンタム：ジグザグの揺れを勢いで打ち消す</text>\n\n  <text x=\"88\" y=\"30\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">勾配降下法だけ</text>\n  <polyline points=\"60,45 105,60 65,75 100,90 70,105 90,118\" stroke=\"#c47070\" stroke-width=\"2\" fill=\"none\"/>\n  <text x=\"30\" y=\"132\" font-size=\"9\" fill=\"#c47070\">谷の壁を行ったり来たり</text>\n\n  <line x1=\"170\" y1=\"24\" x2=\"170\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n\n  <text x=\"252\" y=\"30\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">モメンタムあり</text>\n  <polyline points=\"225,45 250,58 232,72 248,86 238,100 245,118\" stroke=\"#6ab08d\" stroke-width=\"2\" fill=\"none\"/>\n  <text x=\"195\" y=\"132\" font-size=\"9\" fill=\"#6ab08d\">揺れが小さく、速く進む</text>\n</svg>"}'),
  ('g-kentei-f-q26', '4. ディープラーニングの概要',
   '層の深いニューラルネットワークで勾配消失が起きて学習が進まない。対策として最も適切なものはどれか。',
   NULL::text,
   '["中間層の活性化関数をReLUに変える", "学習のバッチサイズをできるだけ大きくする", "学習のエポック数を増やしてひたすら続ける", "正則化の係数を大きくして重みへの罰を強める"]',
   0, '[0]', 'single',
   '{"asked": "勾配消失で学習が進まないときの、最も有効な対策を問う設問。", "point": "勾配消失の原因は活性化関数の飽和(グラフが平らになり傾きが0に近づくこと)。原因そのものに手を打つなら、飽和しにくいReLUに活性化関数を変えるのが最も直接的。", "kid": "勾配消失は、シグモイドのようにグラフが平らになる(飽和する)活性化関数を通るたびに、『直してね』の合図がどんどん小さくなって起きる。原因が『活性化関数の形』にあるので、対策も『活性化関数の形を変える』のが一番効く。ReLUは入力がプラスの間は傾きがずっと1のままで飽和しないので、合図が小さくされにくい。エポック数を増やしても、そもそも合図がほぼ0になっていれば何回繰り返しても重みはほとんど変わらないので、根本的な解決にはならない。", "eg": "伝言ゲームで、途中に『声がどんどん小さくなる区間』があるなら、ゲームを何度もやり直す(エポックを増やす)より、その区間の人を『普通の声で伝えられる人』に交代させる(ReLUに変える)方が効く。", "terms": [["勾配消失", "層を重ねるうちに『直してね』の合図(勾配)がどんどん小さくなり、手前の層まで届かなくなる現象"], ["ReLU（Rectified Linear Unit）", "直訳は「整流された線形の単位」。入力がプラスの間は傾きが常に1で飽和しにくい活性化関数"], ["飽和", "グラフがほぼ平らになり、入力を変えても出力がほとんど変わらなくなる状態。傾きがほぼ0になる"]], "think": "なぜエポック数を増やしても解決しないのかがカギ。勾配消失が起きているとき、手前の層に届く『直してね』の合図はほぼ0になっている。合図がほぼ0ということは、その層の重みを1回更新してもほとんど変わらないということ。これは1回だけの問題ではなく、何回更新を繰り返しても毎回ほぼ0の合図しか届かないので、エポックを何倍に増やしても手前の層はほとんど学習が進まない。バッチサイズや正則化係数も、合図が飽和で小さくされるという原因そのものには手を打っていない。根本原因である『活性化関数が飽和して傾きがほぼ0になる』ことに直接手を打つには、飽和しにくい活性化関数(ReLUなど)に変えるのが最も効果的。", "vs": "バッチサイズを大きくすることは1回の更新に使うデータ量を増やす工夫、正則化係数を強めることは過学習を抑える工夫で、どちらも勾配消失(合図が小さくなる問題)そのものへの直接の対策ではない。", "why_asked": "勾配消失の『症状』は知っていても、対策として何を変えればよいかを問われると、関係のなさそうな設定値(エポック数やバッチサイズ)をとりあえず変えようとしてしまいやすい。原因と対策を正しく結びつけられるかを突く定番の切り口。", "usecase": "実務で深いネットワークの学習が序盤からまったく進まないとき、まず中間層の活性化関数をReLU系に変えてみる、という最初のデバッグ手順に直結する。", "opt": ["正解。勾配消失の原因は活性化関数の飽和なので、飽和しにくいReLUに変えるのが最も直接的な対策になる。", "バッチサイズを大きくすることは1回の更新に使うデータ量を増やす工夫であり、活性化関数の飽和が原因の勾配消失には直接効かない。", "合図がほぼ0のまま何度更新を繰り返しても、手前の層の重みはほとんど変わらないため、エポック数を増やすだけでは解決しない。", "正則化係数を強めることは過学習を抑える工夫であり、勾配消失(合図が小さくなる問題)への対策ではない。"]}'),
  ('g-kentei-f-q27', '5. ディープラーニングの要素技術',
   'プーリング層について、畳み込み層や全結合層と比べた性質として最も適切なものはどれか。',
   NULL::text,
   '["学習によって更新される重みを持たず、代表値を取るだけの操作である", "畳み込み層と同じようにフィルタの重みを学習しながら特徴を抽出する働きを持つ", "全結合層と同じく前の層の全ノードと重みでつながる", "回帰結合層と同じく前の時刻の出力を次の時刻の入力として使う"]',
   0, '[0]', 'single',
   '{"asked": "プーリング層が畳み込み層や全結合層とどう違うかを問う設問。", "point": "重み(学習で動くつまみ)を持たず、ただ代表値をとるだけならプーリング層。", "kid": "プーリング層は「小さい四角の中から一番大きい数字(や平均)を選ぶだけ」の作業。数字を選ぶルールは最初から決まっていて、学習で変わらない。畳み込み層や全結合層は逆に、数字にかける「効き具合のつまみ(重み)」を学習でどんどん調整する。", "eg": "例えると、プーリング層は「クラス写真から一番背の高い子を選ぶ係」。誰を選ぶかのルールは「一番大きい人」で固定されていて、練習しても変わらない。一方で畳み込み層は「どの特徴に注目するかの目のつけどころ」を練習のたびに調整していく。", "terms": [["プーリング層 (Pooling Layer)", "直訳は「まとめる・集める層」。小さな領域から代表値(最大値や平均)を取り出して特徴マップを縮小する層。"], ["畳み込み層 (Convolutional Layer)", "直訳は「巻き込む層」。フィルタ(重みの束)を画像上でずらしながら当て、特徴を抽出する層。重みは学習で変わる。"], ["全結合層 (Fully Connected Layer)", "前の層の全ノードと次の層の全ノードを一本残らずつなぐ層。つなぎ目ごとに重みがあり学習で変わる。"]], "think": "見分け方は「学習で変わる重みがあるか」。畳み込み層は各マスに掛ける数字(フィルタの重み)を訓練を繰り返すたびに調整する。全結合層もつなぎ目ごとの重みを同じように調整する。ところがプーリング層は「この4マスの中で一番大きい数字を選ぶ」という操作のルールを最初から固定していて、訓練が進んでも変える対象がない。だから重みを持たない。なぜこの違いが大事かというと、重みを持たない分プーリング層は計算が軽く、過学習(訓練データだけに強くなりすぎること)の原因になる調整対象も増やさないので、CNN全体を軽くしつつ安定させる役に立つ。", "vs": "畳み込み層・全結合層はどちらも重みを学習で調整するが、プーリング層は調整するものがない「決まったルールの操作」という点で別グループ。回帰結合層(RNN)は前の時刻の出力を引き継ぐ点がプーリングと全く違う仕組み。", "why_asked": "「層」と名がつくものを全部同じ仲間だと思い込み、プーリング層にも重みがあると勘違いする受験者が多い。畳み込み・プーリング・全結合・回帰結合の4つを「学習パラメータの有無」で仕分けられるかが問われる。", "usecase": "CNNを設計するとき、パラメータを増やさずに特徴マップを縮小したい場面でプーリング層を選ぶ。計算量を抑えたいという要件があれば、学習可能な重みを持たない層だと知っていることが判断材料になる。", "opt": ["正解。プーリング層は代表値を取るだけの固定ルールの操作で、学習で更新する重みを持たない。", "畳み込み層の説明。フィルタの重みは訓練のたびに調整される。", "全結合層の説明。ノード間の一本一本のつなぎに重みがあり、学習で調整される。", "回帰結合層(RNN)の説明。前の時刻の出力を次の時刻の入力に回す点がプーリングとは別の仕組み。"]}'),
  ('g-kentei-f-q28', '5. ディープラーニングの要素技術',
   '2×2の窓に入った4つの数値が [2, 8, 4, 6] のとき、最大値プーリングと平均値プーリングの出力の組み合わせとして正しいものはどれか。',
   NULL::text,
   '["最大値プーリング=8、平均値プーリング=5", "最大値プーリング=6、平均値プーリング=8", "最大値プーリング=5、平均値プーリング=8", "最大値プーリング=8、平均値プーリング=20"]',
   0, '[0]', 'single',
   '{"asked": "最大値プーリングと平均値プーリングをそれぞれ手で計算させる設問。", "point": "窓の中で一番大きい数字を残すなら最大値プーリング、窓の中を均して1つの数字にするなら平均値プーリング。", "kid": "どちらも「小さい四角の中の数字をまとめて1個にする」作業だが、まとめ方が違う。最大値は「その中で一番目立つ数字を代表に選ぶ」、平均値は「みんなをならして真ん中くらいの数字にする」。", "eg": "例えると、最大値プーリングは班の中で一番大きい声の子の声を採用するようなもの。平均値プーリングは班全員の声の大きさを平均して1つの音量にするようなもの。", "terms": [["最大値プーリング (Max Pooling)", "直訳は「最大の・集める」。窓の中の一番大きい値だけを残す。輪郭やエッジなど目立つ特徴を拾いやすい。"], ["平均値プーリング (Average Pooling)", "直訳は「平均の・集める」。窓の中の値をならして残す。全体のなだらかな傾向を拾いやすい。"]], "think": "なぜ最大値プーリングがよく使われるのかがカギ。画像認識では「その領域にエッジ(輪郭)や模様があるかどうか」という目立つ反応が重要になる場面が多い。目立つ反応は大きい数値として表れるので、最大値をそのまま残せば目立つ特徴が消えずに次の層まで伝わる。一方で平均値プーリングは全体をならすため、目立つ反応が他の小さい反応で薄まってしまう。だから物体検出のように「特徴があるかないか」を重視するタスクでは最大値プーリングが選ばれやすい。", "vs": "最大値プーリングと平均値プーリングは「代表値の選び方」が違うだけで、どちらも窓を縮小する点(プーリング)自体は同じ。畳み込み層のフィルタ計算(重み付き和)とは違い、プーリングは重みを使わない単純な集計。", "why_asked": "「プーリング=最大値プーリングだけ」と思い込み、平均値プーリングを混同したり、最大と平均の計算を取り違える受験者が多い。小さい数字で実際に計算させることで、操作の中身を理解しているかを見る。", "usecase": "モデル設計で「エッジのようなはっきりした特徴を残したい」なら最大値プーリング、「全体のなだらかな情報を残したい」なら平均値プーリング(ネットワークの最後で使うGlobal Average Poolingなど)を選ぶ判断材料になる。", "calc": "①日本語で言う: 最大値プーリングは窓の中で一番大きい数字をそのまま出す。平均値プーリングは窓の中の数字を全部足して、個数で割る。②小さい数字で全ステップ: 窓の中の数字は 2, 8, 4, 6 の4つ。最大値プーリング→この4つのうち一番大きいのは8なので出力は8。平均値プーリング→2+8+4+6=20。20を個数4で割ると20÷4=5。だから出力は5。③記号版: max(2,8,4,6)=8(maxは英語で「最大」の意味)。mean(2,8,4,6)=(2+8+4+6)÷4=5(meanは英語で「平均」の意味)。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"10\" y=\"16\" font-size=\"11\" fill=\"#8892a4\">2×2の窓にある4つの数字</text>\n<rect x=\"20\" y=\"26\" width=\"60\" height=\"60\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<line x1=\"50\" y1=\"26\" x2=\"50\" y2=\"86\" stroke=\"#2a2f3f\"/>\n<line x1=\"20\" y1=\"56\" x2=\"80\" y2=\"56\" stroke=\"#2a2f3f\"/>\n<text x=\"35\" y=\"46\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\">2</text>\n<text x=\"65\" y=\"46\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\">8</text>\n<text x=\"35\" y=\"76\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\">4</text>\n<text x=\"65\" y=\"76\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\">6</text>\n<line x1=\"90\" y1=\"40\" x2=\"140\" y2=\"30\" stroke=\"#3b82f6\" marker-end=\"url(#arr)\"/>\n<line x1=\"90\" y1=\"70\" x2=\"140\" y2=\"95\" stroke=\"#60a5fa\" marker-end=\"url(#arr2)\"/>\n<defs>\n<marker id=\"arr\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b82f6\"/></marker>\n<marker id=\"arr2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker>\n</defs>\n<rect x=\"145\" y=\"14\" width=\"90\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"190\" y=\"27\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">最大値プーリング</text>\n<text x=\"190\" y=\"41\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\">8</text>\n<rect x=\"145\" y=\"82\" width=\"90\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\"/>\n<text x=\"190\" y=\"95\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">平均値プーリング</text>\n<text x=\"190\" y=\"109\" font-size=\"13\" fill=\"#e8eaf0\" text-anchor=\"middle\">5</text>\n<text x=\"250\" y=\"27\" font-size=\"9\" fill=\"#8892a4\">最大 = max(2,8,4,6)</text>\n<text x=\"250\" y=\"95\" font-size=\"9\" fill=\"#8892a4\">平均 = (2+8+4+6)÷4</text>\n</svg>", "opt": ["正解。窓の中の一番大きい値8がそのまま最大値プーリングの出力、(2+8+4+6)÷4=5が平均値プーリングの出力。", "最大値と平均値の計算を取り違えている。6は窓の中の最大値ではない。", "最大値プーリングの出力を平均値の位置に、平均値プーリングの出力を最大値の位置に入れ替えてしまっている。", "平均を求める際に個数4で割るのを忘れて合計の20をそのまま答えにしてしまっている。"]}'),
  ('g-kentei-f-q29', '5. ディープラーニングの要素技術',
   'プーリング層を入れることで、画像内の物体の位置が少しずれても認識結果が変わりにくくなる。この効果が生まれる理由として最も適切なものはどれか。',
   NULL::text,
   '["小さな領域の代表値(最大値など)を残すため、対象が数ピクセルずれても同じ代表値が選ばれやすいから", "訓練データそのものを回転させたり拡大縮小したりして水増しし、様々な位置での見え方を学習させているから", "層の入力の分布をそろえることで、学習を安定させ収束を速めているから", "一部のノードを訓練時にランダムに無効化し、特定のノードへの依存を減らしているから"]',
   0, '[0]', 'single',
   '{"asked": "プーリングが位置ずれへの頑健性を生む理由を問う設問。", "point": "数ピクセルずれても、その小さな領域の中の代表値(最大値など)が変わらないことが多いなら、それがプーリングの位置ずれへの強さ。", "kid": "対象が1〜2マス右にずれても、プーリングが見ている小さな窓の中に同じ「目立つ数字」がまだ入っていることが多い。だから窓の中の代表値を選ぶプーリングの出力はあまり変わらない。", "eg": "例えると、集合写真の中で一番背の高い人を探すとき、写真の中で全員が少し右にずれて並び直しても、「一番背の高い人」という答えは変わらない。並び方(位置)が多少変わっても代表(最大値)は変わらないのと同じ。", "terms": [["位置不変性(位置ずれへの頑健性)", "対象がどこにあっても同じように認識できる性質。プーリングによって強まる。"], ["プーリング窓", "プーリングが代表値を取り出すために区切る小さな領域。"]], "think": "なぜ位置ずれに強くなるのかがカギ。プーリングは画像を小さな窓に区切り、各窓の中の代表値(最大値など)だけを次の層に渡す。対象が数ピクセルずれても、多くの場合その特徴は同じ窓の中に収まったままなので、窓の中の最大値は変わらない。最大値が変わらなければプーリングの出力も変わらない。だから「対象がどこにあるか」より「その特徴があるかどうか」を重視する認識では、多少の位置ずれが結果に影響しにくくなる。これはデータ拡張(様々な見え方を訓練データとして増やす)やバッチ正規化(分布をそろえて学習を安定させる)とは別の仕組みで頑健性を生む点がポイント。", "vs": "データ拡張は「訓練データの見え方を増やして学習で慣れさせる」仕組みで、プーリングのように計算そのものが位置ずれを吸収するわけではない。バッチ正規化は学習の安定化、ドロップアウトは過学習対策が主な目的で、どちらも位置ずれへの頑健性が主目的ではない。", "why_asked": "「位置ずれに強い」という結果だけを覚えて、その理由をデータ拡張やバッチ正規化と混同する受験者が多い。プーリングの計算の仕組みからなぜその効果が生まれるかを理解しているかを問う。", "usecase": "物体が画像のどこに写っていても同じクラスとして認識したい場面で、プーリング層の効果を理解していると、なぜCNNの構成にプーリングを入れるかを説明できる。", "opt": ["正解。窓の中の代表値を残す仕組みのため、対象が数ピクセルずれても同じ代表値が選ばれやすく、出力が変わりにくい。", "データ拡張の説明。訓練データを増やす工夫であり、プーリング層そのものの計算による効果ではない。", "バッチ正規化の説明。学習の安定化が主な目的で、位置ずれへの頑健性を直接ねらった仕組みではない。", "ドロップアウトの説明。過学習を防ぐための仕組みで、位置ずれへの頑健性とは別の目的。"]}'),
  ('g-kentei-f-q30', '5. ディープラーニングの要素技術',
   '畳み込み層のストライドを2にして特徴マップを縮小する方法と、プーリング層で縮小する方法の違いとして最も適切なものはどれか。',
   NULL::text,
   '["ストライドはフィルタを画像上で動かす間隔の設定であり、プーリングのように代表値を取る別の層を追加するわけではない", "ストライドは学習後にしか使えないが、プーリングは学習前から使える", "プーリング層はフィルタの重みを誤差逆伝播で学習しながら縮小を行うが、ストライドによる縮小のほうでは何も学習されない", "ストライドは全結合層でのみ使われ、プーリングは畳み込み層でのみ使われる"]',
   0, '[0]', 'single',
   '{"asked": "ストライドによる縮小とプーリングによる縮小の仕組みの違いを問う設問。", "point": "フィルタを動かす「間隔」を変えるだけならストライド、代表値を取り出す「別の層」を挟むならプーリング。", "kid": "ストライドは、畳み込み層がフィルタ(重みの束)を画像の上でずらしていくときの「一歩の歩幅」。歩幅を2マスにすれば、1マスずつ見るより少ない回数で画像を見終わるので、出力される特徴マップが小さくなる。プーリングは畳み込みの計算とは別に、「小さい領域から代表値を選ぶ」という専用の層をあとから挟んで縮小する。", "eg": "例えると、ストライドは「歩幅を大きくして少ない歩数で道を歩き切る」こと。プーリングは「道を歩き終えたあとに、写真を何枚かのグループに分けて、各グループから一番よく撮れた1枚だけ残す」作業。どちらも最終的に手元に残る量は減るが、やっていることの中身が違う。", "terms": [["ストライド (Stride)", "直訳は「大股で歩く」。畳み込みでフィルタを動かす間隔。大きくするほど出力が小さくなる。"], ["パディング (Padding)", "直訳は「詰め物」。入力の外側に余白(多くは0)を足す操作。ストライド・プーリングとは逆に、出力サイズを保つ・調整するために使う。"]], "think": "なぜ両者を混同しやすいかがカギ。どちらも「特徴マップを縮小する」という結果は同じだが、縮小のやり方が違う。ストライドは畳み込み層自身の設定の一つで、フィルタを重み付き和で計算しながら動かす間隔を広げることで縮小する。プーリングは畳み込みの計算が終わったあとに置く別の層で、重みを使わず代表値を選ぶだけで縮小する。結果(サイズが小さくなる)が同じでも、重みを使うかどうか・独立した層かどうかが違うので、CNNの構成としては別物として扱う必要がある。", "vs": "パディングは逆に画像の外側に余白を足して出力サイズを保つ・調整する操作で、ストライドやプーリングの「縮小」とは向きが逆。ストライドは畳み込み層の設定、プーリングは独立した層という点が最大の違い。", "why_asked": "「特徴マップを縮小する」という結果だけを見て、ストライド・プーリング・パディングをまとめて同じ操作だと誤解する受験者が多い。それぞれが何に属するかを見分けられるかを問う。", "usecase": "モデルの軽量化やダウンサンプリングの方法を選ぶとき、プーリング層を省いてストライド付き畳み込みだけで縮小する設計を理解する土台になる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"10\" y=\"14\" font-size=\"10\" fill=\"#8892a4\">畳み込み層(ストライド=間隔の設定)</text>\n<rect x=\"10\" y=\"22\" width=\"200\" height=\"24\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<rect x=\"10\" y=\"22\" width=\"30\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"70\" y=\"22\" width=\"30\" height=\"24\" fill=\"none\" stroke=\"#3b82f6\" stroke-dasharray=\"2,2\"/>\n<text x=\"115\" y=\"38\" font-size=\"9\" fill=\"#8892a4\">→ 歩幅2で同じフィルタを動かす</text>\n<text x=\"10\" y=\"70\" font-size=\"10\" fill=\"#8892a4\">プーリング層(独立した別の層)</text>\n<rect x=\"10\" y=\"78\" width=\"30\" height=\"24\" fill=\"none\" stroke=\"#60a5fa\"/>\n<text x=\"25\" y=\"94\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">代表値</text>\n<rect x=\"50\" y=\"78\" width=\"30\" height=\"24\" fill=\"none\" stroke=\"#60a5fa\"/>\n<text x=\"65\" y=\"94\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">代表値</text>\n<text x=\"115\" y=\"94\" font-size=\"9\" fill=\"#8892a4\">→ 重みを使わず代表値だけ選ぶ</text>\n</svg>", "opt": ["正解。ストライドは畳み込み層内でフィルタを動かす間隔の設定であり、プーリングのように代表値を取る専用の層を追加する操作とは別物。", "ストライドとプーリングはどちらも学習の前後を問わず使える設定・層であり、使える時期が違うという説明は誤り。", "プーリング層に学習する重みは無い（最大値や平均を取るだけの固定操作）。ストライドは畳み込み層の設定で、その畳み込みのフィルタは学習される。学習の有無がちょうど逆。", "ストライドは畳み込み層の設定として使われるが、プーリングは畳み込み層専用というわけではなく、CNN全体の構成の中で独立した層として使われる。"]}'),
  ('g-kentei-f-q31', '5. ディープラーニングの要素技術',
   'RNN(再帰型ニューラルネットワーク)が、文章のような順番のあるデータを処理するときの基本的な仕組みとして最も適切なものはどれか。',
   NULL::text,
   '["各時刻で、その時刻の入力とひとつ前の時刻の出力(隠れ状態)を合わせて処理し、新しい隠れ状態を次の時刻に渡していく", "文章全体をひとまとめにして一度に読み込んでしまい、単語同士の関係を並列に重み付けして処理していくというやり方である", "画像を小さな窓に区切り、同じフィルタを使い回しながら順に特徴を抽出する", "層をいくつか飛び越えて、入力をそのまま先の層に足し込みながら処理する"]',
   0, '[0]', 'single',
   '{"asked": "RNNの再帰(前の時刻の出力を次の時刻に持ち越す仕組み)を問う設問。", "point": "「ひとつ前の時刻の出力を、次の時刻の入力と一緒にまた使う」なら、それがRNNの再帰。", "kid": "RNNは文章を先頭の単語から順番に1つずつ読んでいくAI。1つ読むたびに「ここまで読んで覚えていること(隠れ状態)」を更新し、それを次の単語を読むときにまた一緒に使う。この「さっきの結果をまた自分の入力として使う」繰り返しが「再帰」という名前の由来。", "eg": "例えると、小説を1ページずつ読みながら、そのたびに「ここまでのあらすじメモ」を書き直していく読み方。次のページを読むときは、そのページの文章と「今までのあらすじメモ」の両方を見て、メモを更新する。メモが隠れ状態にあたる。", "terms": [["回帰結合層(RNN, Recurrent Neural Network)", "直訳は「繰り返しつながるニューラルネットワーク」。前の時刻の出力を次の時刻の入力に回して、順番のあるデータを処理する。"], ["隠れ状態", "その時刻までに読んだ内容の「覚えていること」を数値でまとめたもの。次の時刻に持ち越される。"]], "think": "なぜこの仕組みが「順番のあるデータ」に向いているのかがカギ。文章や時系列データは、前に来た情報が後の意味に影響する(例えば「彼は」の後に「走った」と続くと主語と動詞のつながりが意味を持つ)。RNNは各時刻で、その時刻の入力だけでなく「ひとつ前までの記憶(隠れ状態)」も一緒に使って処理し、更新した記憶を次の時刻にまた渡す。この「前の結果を次に持ち越す」繰り返しがあるおかげで、離れた場所にある単語同士のつながりも、記憶を介して間接的に伝わる。だから順番に意味がある系列データを扱えるようになる。", "vs": "全結合層や畳み込み層は各時刻の入力を独立に(あるいは同じ画像内で)処理するだけで、前の時刻の結果を次に持ち越す仕組みを持たない。スキップ結合(層を飛び越えて足し込む)は「層の間」の話であり、RNNの再帰は「時刻の間」で結果を持ち越す点が違う。", "why_asked": "RNNを「文章を扱うニューラルネットワーク」という結果だけで覚え、具体的に何を次の時刻に渡しているか(隠れ状態)を説明できない受験者が多い。再帰の仕組みそのものを理解しているかを問う。", "usecase": "文章生成や機械翻訳、時系列予測など、「順番」に意味があるデータを扱うモデルを選ぶときに、RNN系の仕組みを理解していると設計の判断がしやすくなる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<rect x=\"130\" y=\"40\" width=\"80\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"170\" y=\"64\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">RNNセル</text>\n<text x=\"60\" y=\"55\" font-size=\"10\" fill=\"#8892a4\">入力 x_t</text>\n<line x1=\"90\" y1=\"60\" x2=\"128\" y2=\"60\" stroke=\"#8892a4\" marker-end=\"url(#a1)\"/>\n<text x=\"240\" y=\"55\" font-size=\"10\" fill=\"#8892a4\">出力 h_t</text>\n<line x1=\"212\" y1=\"60\" x2=\"238\" y2=\"60\" stroke=\"#8892a4\" marker-end=\"url(#a1)\"/>\n<path d=\"M 170 40 C 170 10, 240 10, 240 40\" fill=\"none\" stroke=\"#60a5fa\"/>\n<path d=\"M 240 40 L 245 30 L 235 32 z\" fill=\"#60a5fa\"/>\n<text x=\"205\" y=\"16\" font-size=\"9\" fill=\"#8892a4\">前の時刻の h(t-1) を次の入力に</text>\n<defs><marker id=\"a1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#8892a4\"/></marker></defs>\n<text x=\"170\" y=\"105\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">同じセルを時刻ごとに繰り返し使い、記憶(隠れ状態)を渡していく</text>\n</svg>", "opt": ["正解。ひとつ前の時刻の隠れ状態と今の入力を合わせて処理し、更新した隠れ状態を次の時刻へ渡していく仕組みがRNNの再帰。", "Transformerの自己注意の説明。文章全体を一度に見て並列に重み付けする点がRNNの逐次処理とは異なる。", "CNNの畳み込み層の説明。画像の窓を区切ってフィルタを使い回す点がRNNの時刻ごとの処理とは異なる。", "スキップ結合(残差接続)の説明。層を飛び越えて足し込む仕組みで、時刻をまたいで記憶を持ち越すRNNの再帰とは別物。"]}'),
  ('g-kentei-f-q32', '5. ディープラーニングの要素技術',
   '通常のRNNで系列が長くなるほど、勾配消失(学習の合図が入力側まで届きにくくなる現象)が起きやすくなる理由として最も適切なものはどれか。',
   NULL::text,
   '["誤差を伝える計算で同じ重みを何度も繰り返し掛け合わせるため、1未満の値が積み重なって合図がどんどん小さくなるから", "フィルタの重みを画像全体で使い回す仕組みに由来しており、局所的な特徴しか捉えられなくなってしまうという説明である", "訓練データを水増しする際に、様々な変形を加えすぎて元の特徴が薄まるから", "層の入力の分布が訓練が進むにつれて大きくばらつき、学習が不安定になるから"]',
   0, '[0]', 'single',
   '{"asked": "通常のRNNで長い系列ほど勾配消失が起きやすい理由を問う設問。", "point": "同じ重みを何度も繰り返し掛けるほど、1より小さい値は掛けるたびにもっと小さくなるなら、それが長い系列でのRNNの勾配消失。", "kid": "RNNは「どれだけ間違えたか」という直してねの合図を、出口の時刻から入り口の時刻へ向かって順番に伝えて学習する。このとき、伝える計算の中で毎回同じ重みを掛け合わせる。もしその重みが1より小さい数だったら、掛けるたびにどんどん小さくなっていき、系列が長い(掛ける回数が多い)ほど、入り口に着く頃には合図がほとんど0になってしまう。", "eg": "例えると、伝言ゲームで、1人伝えるたびに声の大きさが半分になるルールだとする。10人に伝われば声はほぼ聞こえなくなる。RNNの勾配消失も、時刻をまたぐたびに合図が同じ割合で小さくなっていく点が同じ。", "terms": [["勾配消失", "学習の合図(どれだけ間違えたかの情報)が、層や時刻をさかのぼるにつれて小さくなり、最終的にほぼ0になってしまう現象。"], ["重み", "各時刻でRNNが入力や前の隠れ状態にかける「効き具合のつまみ」。学習で調整される。"]], "think": "なぜ系列が長いほど深刻になるのかがカギ。RNNは各時刻で同じ重みを使って隠れ状態を更新する。学習の合図(勾配)を出口から入口へ伝えるときも、この同じ重みを時刻の数だけ繰り返し掛け合わせる計算になる。重みが1より小さい値だと、掛ける回数(=系列の長さ)が増えるほど、合図は指数関数的に小さくなっていく。合図が小さくなりすぎると、入り口に近い時刻の重みは「直してね」の合図をほとんど受け取れず、更新されなくなる。だから系列が長いRNNほど、遠く離れた単語同士のつながりを学習しにくくなる。", "vs": "畳み込み層のフィルタ共有や、データ拡張、バッチ正規化はいずれも別の目的の仕組みで、系列の長さに応じて誤差が指数的に小さくなる現象とは直接関係しない。LSTMはこの現象への対策として、掛け算ではなく足し算で情報を運ぶ経路(セル)を用意している。", "why_asked": "「RNNは長い系列が苦手」という結果だけを覚えて、なぜ苦手なのか(同じ重みの繰り返し掛け算)を説明できない受験者が多い。LSTMがなぜ効くかを理解する前提として、RNN自身の弱点の仕組みを問う。", "usecase": "長い文章や長い時系列を扱うときに、通常のRNNではなくLSTMやGRU、Transformerを選ぶ理由を説明する場面で、この因果を理解していると判断に説得力が出る。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"10\" y=\"14\" font-size=\"10\" fill=\"#8892a4\">出口(t=3)から入口(t=0)へ、同じ重みを繰り返し掛ける</text>\n<rect x=\"20\" y=\"30\" width=\"50\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"45\" y=\"49\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">t=0</text>\n<rect x=\"100\" y=\"30\" width=\"50\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"125\" y=\"49\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">t=1</text>\n<rect x=\"180\" y=\"30\" width=\"50\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"205\" y=\"49\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">t=2</text>\n<rect x=\"260\" y=\"30\" width=\"50\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"285\" y=\"49\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">t=3</text>\n<line x1=\"260\" y1=\"80\" x2=\"230\" y2=\"80\" stroke=\"#c47070\" stroke-width=\"5\"/>\n<line x1=\"180\" y1=\"90\" x2=\"150\" y2=\"90\" stroke=\"#c47070\" stroke-width=\"3\"/>\n<line x1=\"100\" y1=\"97\" x2=\"70\" y2=\"97\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n<text x=\"290\" y=\"80\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"end\">合図(勾配)大</text>\n<text x=\"45\" y=\"112\" font-size=\"8\" fill=\"#8892a4\">合図ほぼ消える</text>\n</svg>", "opt": ["正解。同じ重みを時刻の数だけ繰り返し掛け合わせる計算になるため、1未満の値が積み重なって合図が指数的に小さくなる。", "CNNの重み共有の説明。局所特徴の抽出はRNNの勾配消失とは別の話。", "データ拡張の説明。訓練データの水増しであり、勾配が時刻をまたいで小さくなる現象とは別の話。", "バッチ正規化が対処する現象に近い説明だが、RNNの勾配消失の直接の原因ではない。"]}'),
  ('g-kentei-f-q33', '5. ディープラーニングの要素技術',
   'LSTMが持つ「ゲート」の役割として最も適切なものはどれか。',
   NULL::text,
   '["記憶セルに出入りする情報をどれだけ忘れる・取り込む・出力するかを、0から1までの割合で細かく調整する", "画像のフィルタを画像全体でずらしながら当てて、局所的な特徴を抽出していくという畳み込み層が行う働きである", "層の入力の分布を平均0・分散1にそろえて学習を安定させる", "複数の異なる観点の注意を同時に計算して組み合わせる"]',
   0, '[0]', 'single',
   '{"asked": "LSTMのゲートが何を調整しているかを問う設問。", "point": "「情報をどれだけ通すか・忘れるか」を0〜1の割合で決める門(ゲート)なら、それがLSTMのゲート。", "kid": "LSTMには「記憶セル」という、長く覚えておくための情報の通り道がある。ゲートはその通り道の途中にある門のようなもので、「今までの記憶をどれだけ忘れるか」「新しい情報をどれだけ取り込むか」「記憶の中身をどれだけ次に出力するか」を、0(全く通さない)から1(そのまま通す)の割合で調整する。", "eg": "例えると、記憶セルは水が流れる水路で、ゲートはその水路にある水門。水門の開き具合(0〜1)で、今流れている水(古い記憶)をどれだけ流し続けるか、新しい水(新しい情報)をどれだけ足すかを調整する。", "terms": [["記憶セル(セルステート)", "LSTMが情報を長く運ぶための専用の通り道。ゲートによって足し引きが調整される。"], ["忘却ゲート・入力ゲート・出力ゲート", "記憶セルの情報をそれぞれ「忘れる量」「取り込む量」「出力する量」を0〜1の割合で決める3つの門。"]], "think": "なぜゲートという仕組みが要るのかがカギ。通常のRNNは新しい情報が来るたびに記憶をまるごと上書きしてしまい、古い情報も新しい情報もひとまとめに掛け算で変換され続けるため、長く覚えておくのが苦手だった。LSTMは記憶セルという別の通り道を用意し、そこに何をどれだけ足すか・消すかをゲート(0〜1の割合)で細かく調整できるようにした。必要な情報だけを長く保ち、不要になった情報だけを忘れることができるので、遠く離れた時刻の情報でも記憶セルを通じて保持しやすくなる。", "vs": "畳み込みのフィルタ共有、バッチ正規化(分布をそろえる)、マルチヘッドアテンション(複数の注意を組み合わせる)は、いずれもLSTMのゲートとは別の目的・別の仕組み。ゲートは「記憶セルの情報の出し入れを割合で調整する」点が固有の役割。", "why_asked": "LSTMを「長期記憶ができるRNN」という結果だけで覚え、その中身(ゲートが何を調整しているか)を説明できない受験者が多い。ゲートの役割を具体的に理解しているかを問う。", "usecase": "長い文章の文脈を保ちたい自然言語処理のタスクで、通常のRNNではなくLSTMを選ぶ理由や、ゲートの仕組みがなぜ長期記憶を可能にするかを説明する場面で役立つ。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"10\" y=\"14\" font-size=\"10\" fill=\"#8892a4\">記憶セルの通り道と3つのゲート(門)</text>\n<line x1=\"20\" y1=\"60\" x2=\"320\" y2=\"60\" stroke=\"#2a2f3f\" stroke-width=\"6\"/>\n<rect x=\"70\" y=\"42\" width=\"30\" height=\"36\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"85\" y=\"35\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\">忘却ゲート</text>\n<rect x=\"150\" y=\"42\" width=\"30\" height=\"36\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"165\" y=\"35\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\">入力ゲート</text>\n<rect x=\"230\" y=\"42\" width=\"30\" height=\"36\" fill=\"none\" stroke=\"#c9a04a\"/><text x=\"245\" y=\"35\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\">出力ゲート</text>\n<text x=\"20\" y=\"95\" font-size=\"8\" fill=\"#8892a4\">各ゲートは0〜1の割合で情報の出し入れを調整する</text>\n</svg>", "opt": ["正解。ゲートは記憶セルの情報をどれだけ忘れる・取り込む・出力するかを0〜1の割合で調整する仕組み。", "畳み込み層の説明。フィルタを画像全体で使い回す点はLSTMのゲートとは無関係。", "バッチ正規化の説明。分布をそろえて学習を安定させる仕組みで、記憶セルの出し入れとは別の目的。", "マルチヘッドアテンションの説明。複数の注意を組み合わせる仕組みで、LSTMのゲートとは別物。"]}'),
  ('g-kentei-f-q34', '5. ディープラーニングの要素技術',
   'LSTMが通常のRNNより勾配消失を起こしにくい理由として最も適切なものはどれか。',
   NULL::text,
   '["記憶セルの情報を掛け算ではなく足し算主体で次の時刻へ運ぶ経路があり、合図が急激に小さくなりにくいから", "フィルタの重みを画像全体で共有する仕組みに由来しており、パラメータの数を減らすことが目的であるという説明である", "訓練データを回転・拡大縮小して増やし、様々なパターンに慣れさせているから", "複数の注意を同時に計算し、系列全体を並列に処理できるから"]',
   0, '[0]', 'single',
   '{"asked": "LSTMが勾配消失を起こしにくい理由(仕組み)を問う設問。", "point": "情報を運ぶ経路が「掛け算の繰り返し」ではなく「足し算主体」なら、合図は急に小さくなりにくい。それがLSTMの勾配消失対策。", "kid": "通常のRNNは、時刻を1つ進めるたびに情報に同じ重みを掛け算していく。掛け算を繰り返すと、1より小さい数はどんどん小さくなっていく。LSTMは記憶セルという別の通り道を用意し、そこでは情報を「足し算」で運ぶ(ゲートで調整した量を足したり引いたりする)。足し算は掛け算のように繰り返すほど急激に小さくなることがないので、学習の合図(勾配)も遠くの時刻まで消えずに届きやすい。", "eg": "例えると、通常のRNNは伝言ゲームで毎回声の大きさを半分にして伝える方式。LSTMの記憶セルは、伝言を紙に書いて手渡しでリレーするようなもので、多少書き加えたり消したりはしても、声のように毎回半分になるわけではないので、最後まで内容が残りやすい。", "terms": [["勾配消失", "学習の合図が層や時刻をさかのぼるにつれて小さくなり、ほぼ0になる現象。"], ["記憶セル(セルステート)", "LSTMが情報を足し算主体で運ぶ専用の通り道。"]], "think": "なぜ足し算のほうが合図を守れるのかがカギ。勾配消失は「同じ重みを繰り返し掛け算する」ことで1未満の値がどんどん小さくなる現象だった(通常のRNN)。LSTMの記憶セルは、ゲートで調整した「足す量」「忘れる量」を足し引きする経路を持つ。足し算は掛け算と違い、繰り返しても値が指数的に縮んでいくことがない。だから学習の合図を出口から入口へ伝えるときも、記憶セルを通る経路では急激に小さくならず、遠く離れた時刻まで合図が届きやすくなる。結果として、LSTMは長い系列でも学習が進みやすい。", "vs": "フィルタ共有(CNN)やデータ拡張、マルチヘッドアテンション(Transformer)はいずれも別の仕組みで、LSTMが勾配消失を防ぐ理由とは直接関係しない。通常のRNNとLSTMの違いは「掛け算だけの経路」か「足し算主体の経路を追加したか」という点にある。", "why_asked": "LSTMが勾配消失に強いという結果は知っていても、なぜ強いのか(足し算主体の経路)を説明できない受験者が多い。ゲート・記憶セルの構造が具体的にどう勾配消失を防ぐかという因果を問う。", "usecase": "長い系列を扱うモデルを設計するとき、通常のRNNではなくLSTMやGRUを選ぶ根拠を、単なる知識でなく仕組みの理由として説明できるようになる。", "opt": ["正解。記憶セルは情報を足し算主体で運ぶ経路を持ち、掛け算の繰り返しのように合図が急激に縮まないため、勾配消失が起きにくい。", "CNNのフィルタ共有の説明。パラメータ削減が目的で、勾配消失を防ぐ仕組みとは別の話。", "データ拡張の説明。訓練データの水増しであり、勾配が時刻をまたいで消える現象とは別の話。", "マルチヘッドアテンション(Transformer)の説明。並列処理が特徴で、LSTMのゲート・記憶セルの仕組みとは別物。"]}'),
  ('g-kentei-f-q35', '5. ディープラーニングの要素技術',
   'GRUがLSTMと比べて構造を簡単にしている点として最も適切なものはどれか。',
   NULL::text,
   '["記憶セルを別に持たず、更新ゲートとリセットゲートの2つだけで隠れ状態を直接調整する", "ゲートというものを一切使わずに、隠れ状態の値をそのまま次の時刻へとただ渡していくだけの仕組みにしている", "畳み込みのフィルタを導入し、局所的な特徴を抽出できるようにしている", "注意機構を導入し、系列全体を一度に参照できるようにしている"]',
   0, '[0]', 'single',
   '{"asked": "GRUがLSTMと比べてどう構造を簡略化しているかを問う設問。", "point": "「記憶セルを別に持たず、隠れ状態そのものを2つのゲートで直接調整する」ならGRU。", "kid": "LSTMは「隠れ状態」とは別に「記憶セル」という長期記憶専用の通り道を持ち、3つのゲート(忘却・入力・出力)で調整していた。GRUはこの記憶セルを廃止し、隠れ状態だけを使う。代わりに「更新ゲート(どれだけ新しい情報に置き換えるか)」と「リセットゲート(どれだけ過去の情報を忘れて計算するか)」の2つのゲートで、隠れ状態を直接調整する。", "eg": "例えると、LSTMは「メモ帳(隠れ状態)」と「金庫(記憶セル)」の2つを持ち、金庫の出し入れを3つの鍵(ゲート)で管理する仕組み。GRUはメモ帳1冊だけを持ち、2つの鍵(更新・リセット)でメモ帳への書き込み方を管理する仕組み。持ち物が減った分、扱いが簡単になる。", "terms": [["GRU(Gated Recurrent Unit)", "直訳は「門(ゲート)がついた再帰の単位」。LSTMより少ないゲートで長期の情報を保持できるようにした手法。"], ["更新ゲート・リセットゲート", "GRUが持つ2つのゲート。更新ゲートは新旧の情報の混ぜ具合、リセットゲートは過去の情報をどれだけ無視するかを決める。"]], "think": "なぜ構造を簡単にできるのかがカギ。LSTMは記憶セルと隠れ状態という2種類の情報を、3つのゲートで別々に管理していた。GRUは隠れ状態1つに情報をまとめてしまい、更新ゲートで新旧の情報の混ぜ具合を、リセットゲートで過去の情報をどれだけ無視して新しい候補を作るかを決める、というやり方に変えた。管理する情報の種類とゲートの数を減らしても、長期の依存関係を保つという目的(足し算主体で情報を運ぶ発想)は引き継いでいるため、LSTMに近い性能を保ちながら計算量を減らせる。", "vs": "LSTMは記憶セル+3ゲート(忘却・入力・出力)、GRUは記憶セルなし+2ゲート(更新・リセット)という構成の違いがある。畳み込みやAttentionの導入はGRUの簡略化とは別の話で、GRUはあくまで「RNN系列」の中の軽量版という位置づけ。", "why_asked": "「GRUはLSTMを軽くしたもの」という結果だけを覚え、具体的に何を減らしたか(記憶セルを廃止し、ゲート数を3つから2つにした)を説明できない受験者が多い。構造の違いを具体的に問う。", "usecase": "計算資源が限られる場面や、LSTMほど複雑な記憶が要らないタスクで、GRUを選ぶ判断の根拠(構造が軽い分、学習・推論が速い)を説明できるようになる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"10\" y=\"14\" font-size=\"10\" fill=\"#8892a4\">LSTM: 記憶セル + 3ゲート</text>\n<line x1=\"20\" y1=\"35\" x2=\"150\" y2=\"35\" stroke=\"#2a2f3f\" stroke-width=\"5\"/>\n<rect x=\"45\" y=\"24\" width=\"18\" height=\"22\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"80\" y=\"24\" width=\"18\" height=\"22\" fill=\"none\" stroke=\"#3b82f6\"/>\n<rect x=\"115\" y=\"24\" width=\"18\" height=\"22\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"10\" y=\"75\" font-size=\"10\" fill=\"#8892a4\">GRU: 記憶セルなし・隠れ状態 + 2ゲート</text>\n<line x1=\"20\" y1=\"96\" x2=\"150\" y2=\"96\" stroke=\"#2a2f3f\" stroke-width=\"5\"/>\n<rect x=\"55\" y=\"85\" width=\"18\" height=\"22\" fill=\"none\" stroke=\"#60a5fa\"/>\n<rect x=\"95\" y=\"85\" width=\"18\" height=\"22\" fill=\"none\" stroke=\"#60a5fa\"/>\n<text x=\"170\" y=\"30\" font-size=\"8\" fill=\"#8892a4\">忘却・入力・出力</text>\n<text x=\"170\" y=\"95\" font-size=\"8\" fill=\"#8892a4\">更新・リセット</text>\n</svg>", "opt": ["正解。GRUは記憶セルを持たず、更新ゲートとリセットゲートの2つで隠れ状態を直接調整する構造にしている。", "GRUもLSTMと同じくゲートを使う仕組みであり、ゲートを一切使わないという説明は誤り。", "畳み込みフィルタの導入はCNNの特徴で、GRUの簡略化とは無関係。", "注意機構の導入はTransformerの特徴で、GRUの簡略化とは無関係。"]}'),
  ('g-kentei-f-q36', '5. ディープラーニングの要素技術',
   'オートエンコーダとPCA(主成分分析)はどちらも次元削減に使えるが、両者の違いとして最も適切なものはどれか。',
   NULL::text,
   '["オートエンコーダは活性化関数を挟んだ非線形な変換で圧縮できるが、PCAは線形な変換に限られる", "オートエンコーダは正解ラベルを使う教師あり学習だが、PCAは正解ラベルを使わない教師なし学習である", "オートエンコーダは分類タスク専用であり、PCAは回帰タスク専用である", "オートエンコーダはクラスタリング手法であり、PCAは生成モデルである"]',
   0, '[0]', 'single',
   '{"asked": "オートエンコーダとPCAの本質的な違いを問う設問。", "point": "活性化関数を挟んだ非線形な圧縮ができるならオートエンコーダ、線形な変換に限られるならPCA。", "kid": "PCAはデータのばらつきが一番大きい方向を直線(まっすぐな軸)で探して、そこに射影(データを軸に映す)することで次元を減らす手法。直線的な変換しかできない。オートエンコーダはニューラルネットワークなので、活性化関数(S字カーブやReLUのような折れ線)を挟んだ層を重ねられる。そのため、直線ではなく曲がった変換で圧縮でき、PCAでは捉えられない複雑な特徴も圧縮できる。", "eg": "例えると、PCAは「まっすぐな物差しで一番効率よく影が伸びる角度を探して、そこに影を落とす」やり方。オートエンコーダは「曲がる粘土板を使って、元の形を保ったまま自由に折りたたむ」やり方。まっすぐな道具しか使えないPCAより、曲げられるオートエンコーダのほうが複雑な形を圧縮できる。", "terms": [["主成分分析(PCA, Principal Component Analysis)", "直訳は「主な成分の分析」。データのばらつきが一番大きい方向(直線)を見つけて射影する、線形な次元削減の手法。"], ["活性化関数", "ニューラルネットワークの各層の出力を折れ曲がった形に変える関数。これを挟むことで非線形な変換ができる。"]], "think": "なぜ非線形かどうかが本質的な違いになるのかがカギ。データの中には、直線的な変換だけでは捉えきれない複雑な構造(曲がった塊や渦を巻いたような分布)がある。PCAは行列の掛け算（数の表どうしを一定の規則で掛け合わせる、比例計算の集まり）(線形変換)だけで軸を回転させる方法なので、こうした曲がった構造をうまく圧縮できない。オートエンコーダは各層に活性化関数を挟むことで、線形変換を何度も曲げながら重ねられる。曲げる操作を組み合わせられる分、複雑な構造も少ない次元にうまく圧縮できる。だから「データが直線的にばらついているか、曲がった構造をしているか」で、PCAで十分か、オートエンコーダが必要かが変わってくる。", "vs": "教師あり・教師なしの区別で言えば、どちらも正解ラベルを使わない教師なし学習に分類される点は同じで、そこが違いではない。分類・回帰専用という説明も誤りで、どちらもタスク専用の手法ではなく、次元削減・特徴抽出のための手法。", "why_asked": "「オートエンコーダもPCAも次元削減」という共通点だけを覚え、線形か非線形かという本質的な違いを説明できない受験者が多い。数学的な性質の違いを理解しているかを問う。", "usecase": "データの構造が複雑で直線的な圧縮では情報が失われすぎる場合に、PCAではなくオートエンコーダを選ぶ根拠として使える。逆に計算を軽くしたい・解釈しやすさを優先したい場合はPCAを選ぶ判断にもつながる。", "opt": ["正解。オートエンコーダは活性化関数を挟んだ非線形変換で圧縮でき、PCAは線形変換に限られる。", "オートエンコーダもPCAも正解ラベルを使わない教師なし学習に分類され、教師あり・なしの違いという説明は誤り。", "どちらも分類・回帰専用の手法ではなく、次元削減や特徴抽出に使う手法という点で誤り。", "オートエンコーダはクラスタリング手法ではなく、PCAも生成モデルではないという点で誤り。"]}'),
  ('g-kentei-f-q37', '5. ディープラーニングの要素技術',
   'オートエンコーダと変分オートエンコーダ(VAE)の違いとして最も適切なものはどれか。',
   NULL::text,
   '["VAEは圧縮した表現を確率分布として扱うため、そこから新しいデータをサンプリングして生成できる", "オートエンコーダは画像データを扱う専用の手法であり、VAEは文章データだけを扱う専用の手法である", "オートエンコーダは教師あり学習であり、VAEは教師なし学習である", "オートエンコーダはゲートを持つが、VAEはゲートを持たない"]',
   0, '[0]', 'single',
   '{"asked": "オートエンコーダとVAEの違い(生成できるかどうか)を問う設問。", "point": "圧縮した表現を「1つの値」として扱うなら普通のオートエンコーダ、「確率分布」として扱い、そこから新しいデータを作れるならVAE。", "kid": "普通のオートエンコーダは、入力を圧縮するとき「この入力ならこの1点」というように、決まった1つの値(点)に圧縮する。VAEは圧縮するとき「この入力なら、だいたいこのあたりの範囲(確率分布)」という形で表す。範囲として表しておくと、その範囲の中から新しい点をランダムに選んで(サンプリングして)、まだ見たことのない新しいデータを作り出せるようになる。", "eg": "例えると、普通のオートエンコーダは「この人の顔を1枚の写真(1点)に圧縮して保存する」やり方。VAEは「この人の顔を、少しずつ違う似顔絵が生まれる範囲(確率分布)として保存する」やり方。後者なら、保存した範囲から少しずつ違う新しい似顔絵を何枚でも作り出せる。", "terms": [["変分オートエンコーダ(VAE, Variational AutoEncoder)", "直訳は「変分を使った、自ら符号化するもの」。圧縮した表現を確率分布として学習し、そこから新しいデータを生成できるオートエンコーダの発展形。"], ["サンプリング", "確率分布からランダムに1つの値を選び出す操作。VAEはこれを使って新しいデータを生成する。"]], "think": "なぜ確率分布にすると生成ができるようになるのかがカギ。普通のオートエンコーダは圧縮した表現が1点しかないため、そこから復元できるのは元の入力とほぼ同じものだけで、「まだ見たことのない新しいデータ」を作る仕組みがない。VAEは圧縮した表現を「平均と広がり(確率分布)」として学習する。学習後は、その分布の中から自由に点をランダムに選んでデコーダ(復元する部分)に通せば、元の入力そのものではない、しかし似た性質を持つ新しいデータを作り出せる。この「点ではなく分布で表す」工夫が、圧縮(次元削減)だけの道具だったオートエンコーダを、新しいデータを生み出す生成モデルに変えている。", "vs": "画像専用・文章専用という区別ではなく、どちらもデータの種類を選ばない仕組み。教師あり・教師なしの違いでもなく、どちらも正解ラベルを使わない教師なし学習。ゲートの有無はLSTM・GRUの話であり、オートエンコーダ・VAEの違いとは無関係。", "why_asked": "VAEを「オートエンコーダの発展形」という結果だけで覚え、具体的に何が発展したのか(点ではなく確率分布で圧縮する)を説明できない受験者が多い。生成できる・できないの違いがどこから生まれるかを問う。", "usecase": "新しい画像やデータを生成したいタスクでは、圧縮だけのオートエンコーダではなく、確率分布として扱うVAEを選ぶ理由を説明できるようになる。", "opt": ["正解。VAEは圧縮した表現を確率分布として学習するため、そこから新しいデータをサンプリングして生成できる。", "オートエンコーダ・VAEともにデータの種類を選ばない仕組みで、画像専用・文章専用という区別は誤り。", "オートエンコーダ・VAEともに正解ラベルを使わない教師なし学習であり、教師あり・なしの違いという説明は誤り。", "ゲートの有無はLSTM・GRUの違いであり、オートエンコーダとVAEの違いとは無関係。"]}'),
  ('g-kentei-f-q38', '5. ディープラーニングの要素技術',
   'Attention(注意機構)が行っている計算の基本的な考え方として最も適切なものはどれか。',
   NULL::text,
   '["出力の各要素を作るときに、入力の各部分がどれだけ重要かを表す重みを計算し、その重みに応じて入力を混ぜ合わせる", "入力全体をあらかじめ小さな窓に区切ったうえで、その窓の中にある代表値だけを残して縮小していくという操作である", "入力全体の分布の平均と分散をそろえて、学習を安定させる", "層をいくつか飛び越えて、入力をそのまま先の層に足し込む"]',
   0, '[0]', 'single',
   '{"asked": "Attentionが行っている計算の基本発想を問う設問。", "point": "入力の各部分に「どれだけ重要か」の重みをつけて混ぜ合わせるなら、それがAttentionの基本発想。", "kid": "Attentionは、何かを判断するときに「入力のどこに注目すべきか」を数値の重みで表す仕組み。重要な部分には大きい重み、そうでない部分には小さい重みをつけて、その重みに応じて入力を混ぜ合わせた結果を使う。重みは固定ではなく、扱う場面ごとに計算し直される。", "eg": "例えると、長い会議の議事録から要点をまとめるとき、全部の発言を同じ重さで扱うのではなく、重要そうな発言には線を引いて重点的に読み、雑談には軽く目を通すくらいにする。Attentionはこの「重要度に応じて注目の度合いを変える」作業を数値で自動的にやる。", "terms": [["Attention(注意機構)", "直訳は「注意」。入力の各部分の重要度を重みで表し、その重みに応じて情報を混ぜ合わせる仕組み。"], ["重み(注目の度合い)", "入力のどの部分をどれだけ重視するかを表す0以上の数値。場面ごとに計算し直される。"]], "think": "なぜ重み付けという発想が有効なのかがカギ。文章や系列データでは、ある部分を理解するのに必要な手がかりが、離れた場所に散らばっていることが多い(例えば代名詞「それ」が何を指すかは、ずっと前の単語を見ないとわからない)。RNNのように前から順番に情報を圧縮していくやり方だと、遠くの情報が薄まってしまう。Attentionは、注目したい部分に対して入力の全ての部分との関連度を計算し、関連が強い部分には大きい重みを、弱い部分には小さい重みをつけて混ぜ合わせる。これにより、距離に関係なく必要な情報を直接参照できるようになる。", "vs": "プーリングは窓の中の代表値を「選ぶ」だけで重み付けの計算をしない。バッチ正規化は分布をそろえる仕組みで注目度とは無関係。スキップ結合は層を飛び越えて足し込む仕組みで、Attentionの「重要度に応じて混ぜ合わせる」計算とは別物。", "why_asked": "Attentionを「機械翻訳やTransformerで使う」という結果だけで覚え、計算の中身(重要度の重みを計算して混ぜ合わせる)を説明できない受験者が多い。仕組みそのものの理解を問う。", "usecase": "長い文章の中で重要な部分を自動的に見つけたいタスクや、離れた位置にある情報同士を結びつけたいタスクで、Attentionを使う理由を説明する場面で役立つ。", "opt": ["正解。入力の各部分の重要度を表す重みを計算し、その重みに応じて入力を混ぜ合わせるのがAttentionの基本発想。", "プーリング層の説明。窓の中の代表値を選ぶだけで、重要度の重みを計算して混ぜ合わせる仕組みではない。", "バッチ正規化の説明。分布をそろえて学習を安定させる仕組みで、注目度の計算とは無関係。", "スキップ結合(残差接続)の説明。層を飛び越えて足し込む仕組みで、Attentionの重み付けとは別物。"]}'),
  ('g-kentei-f-q39', '5. ディープラーニングの要素技術',
   'スキップ結合(残差接続)を導入すると、非常に深いネットワークでも学習が進みやすくなる理由として最も適切なものはどれか。',
   NULL::text,
   '["入力をそのまま先の層へ足し込む近道があり、学習の合図はその近道を通って手前の層まで小さくならずに届く", "各層の入力の分布をそろえることで、内部の値の変動を抑えているから", "訓練データを回転や拡大縮小によって変形させて水増しすることで、様々なパターンを学習させていく工夫である", "小さな領域の代表値を取ることで、パラメータの数を減らしているから"]',
   0, '[0]', 'single',
   '{"asked": "スキップ結合が深いネットワークの学習を助ける理由(仕組み)を問う設問。", "point": "入力をそのまま足し込む近道があり、その近道を通って学習の合図が小さくならずに手前の層まで届くなら、それがスキップ結合の効果。", "kid": "普通のネットワークは、層を通るたびに学習の合図(どれだけ間違えたかの合図)が少しずつ小さくなっていき、層が多いと手前の層まで届かなくなることがある(勾配消失)。スキップ結合は、何層か先まで入力をそのまま足し込む「近道」を作る仕組み。この近道のおかげで、合図は近道を通って手前の層まで小さくならずに直接届けられる。", "eg": "例えると、伝言ゲームで、1人ずつ順番に伝える普通のルートに加えて、「先頭から最後尾まで直接声を届けられる特別な通路」を用意しておくようなもの。普通のルートで声が小さくなっても、特別な通路を使えば最初の声がそのまま最後尾まで届く。", "terms": [["スキップ結合(残差接続, Residual Connection)", "直訳は「残った差をつなぐ」。層をいくつか飛び越えて入力をそのまま先の層に足し込む近道。"], ["恒等写像", "入力をそのまま(何も変えずに)出力する変換。スキップ結合の近道はこの働きをする。"]], "think": "なぜ「そのまま足し込む」ことが勾配消失を防ぐのかがカギ。深いネットワークでは、学習の合図(勾配)を出口から入口へ伝える計算の中で、層を通るたびに重みを掛け合わせる。この掛け算が何層分も重なると、通常のRNNの勾配消失と同じように、合図が指数的に小さくなってしまう。スキップ結合は「その層の変換結果」に「入力をそのまま足したもの」を出力とする構造にする。この構造だと、学習の合図を逆向きに伝える計算の中に「そのまま(=1倍)伝わる経路」が必ず含まれるため、掛け算だけで小さくなっていく経路とは別に、合図が縮まずに伝わる近道が確保される。だから層をどれだけ重ねても、手前の層まで学習の合図が届き続け、非常に深いネットワークでも学習が進む。", "vs": "バッチ正規化は各層の入力の分布をそろえて学習を安定させる仕組みで、近道を作るスキップ結合とは別のアプローチ。データ拡張は訓練データを増やす工夫、プーリングは代表値を取って縮小する仕組みで、いずれも「合図をそのまま届ける近道」とは無関係。", "why_asked": "スキップ結合を「層を飛び越えて足し込む仕組み」という結果だけで覚え、なぜそれで深いネットワークが学習できるようになるのか(合図が縮まず届く近道になる)を説明できない受験者が多い。ResNetの中心的な発想の因果を問う。", "usecase": "非常に多くの層を重ねたモデル(ResNetなど)を設計・理解する場面で、なぜ層を増やしても学習が破綻しないのかを説明する根拠になる。", "viz": "<svg viewBox=\"0 0 340 120\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<rect x=\"30\" y=\"40\" width=\"60\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"60\" y=\"59\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">層1</text>\n<rect x=\"130\" y=\"40\" width=\"60\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"160\" y=\"59\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">層2</text>\n<rect x=\"230\" y=\"40\" width=\"60\" height=\"30\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"260\" y=\"59\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">層3</text>\n<line x1=\"90\" y1=\"55\" x2=\"128\" y2=\"55\" stroke=\"#8892a4\" marker-end=\"url(#a3)\"/>\n<line x1=\"190\" y1=\"55\" x2=\"228\" y2=\"55\" stroke=\"#8892a4\" marker-end=\"url(#a3)\"/>\n<path d=\"M 60 40 C 60 15, 260 15, 260 40\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"2\"/>\n<path d=\"M 260 40 L 265 30 L 255 32 z\" fill=\"#6ab08d\"/>\n<text x=\"160\" y=\"18\" font-size=\"9\" fill=\"#6ab08d\">入力をそのまま足し込む近道(スキップ結合)</text>\n<defs><marker id=\"a3\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#8892a4\"/></marker></defs>\n<text x=\"160\" y=\"95\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\">学習の合図は近道を通って縮まずに手前まで届く</text>\n</svg>", "opt": ["正解。入力をそのまま足し込む近道があるため、学習の合図がその近道を通って縮まずに手前の層まで届きやすくなる。", "バッチ正規化の説明。分布をそろえて学習を安定させる仕組みで、近道を作る仕組みとは別のアプローチ。", "データ拡張の説明。訓練データを水増しする工夫であり、層を飛び越える近道とは無関係。", "プーリング層の説明。代表値を取って縮小する仕組みであり、学習の合図を届ける近道とは無関係。"]}'),
  ('g-kentei-f-q40', '5. ディープラーニングの要素技術',
   'バッチ正規化(Batch Normalization)が行っていることとして最も適切なものはどれか。',
   NULL::text,
   '["ミニバッチという処理のまとまりごとに、各層の入力の平均と分散をそろえて値の分布が偏らないようにする", "訓練のときに一部のノードをランダムに無効化して、特定のノードへの依存を減らしていくという仕組みである", "入力の一部を回転・拡大縮小して変形させ、訓練データを水増しする", "層をいくつか飛び越えて、入力をそのまま先の層に足し込む"]',
   0, '[0]', 'single',
   '{"asked": "バッチ正規化が具体的に何をしている仕組みかを問う設問。", "point": "ミニバッチ(一度に処理するデータのまとまり)単位で、各層に入ってくる値の平均と分散をそろえるなら、それがバッチ正規化。", "kid": "ニューラルネットワークは層を通るたびに値の分布(平均や散らばり具合)が変わっていく。学習が進むにつれてこの分布が層ごとに大きくずれていくと、後ろの層は「入力の当たり前」が毎回変わってしまい、学習がうまく進みにくくなる。バッチ正規化は、一度に処理するデータのまとまり(ミニバッチ)ごとに、各層に入る値の平均を0、散らばり具合(分散)を1にそろえ直す処理を挟む。", "eg": "例えると、複数の生徒が違う単位(センチとインチ)で身長を報告してくると、比べるのが大変になる。バッチ正規化は、報告が来るたびに全員の単位をそろえ直してから次の作業に渡すようなもの。単位がそろっていれば、後の作業がやりやすくなる。", "terms": [["バッチ正規化(Batch Normalization)", "直訳は「まとまり(バッチ)の正規化」。ミニバッチ単位で各層の入力の平均と分散をそろえ、学習を安定させる仕組み。"], ["ミニバッチ", "一度の学習ステップでまとめて処理するデータの小さなまとまり。"]], "think": "なぜ分布をそろえると学習が安定するのかがカギ。学習が進むと、各層の重みが更新されるたびに、その層に入ってくる値の分布(平均・散らばり)も変わっていく。次の層は「前の層からの入力はだいたいこの範囲」という前提で重みを調整しているので、入力の分布が毎回大きくずれると、その前提が崩れて学習がやり直しに近くなり、収束が遅くなったり不安定になったりする。バッチ正規化は各層の入力をミニバッチごとに平均0・分散1にそろえ直すことで、後ろの層が受け取る値の範囲を安定させる。範囲が安定していれば、後ろの層はより大きな学習率でも安定して学習を進められ、収束が速くなる。", "vs": "ドロップアウトは一部のノードをランダムに無効化して過学習を防ぐ仕組みで、分布をそろえる仕組みとは目的が違う。データ拡張は訓練データを増やす工夫、スキップ結合は層を飛び越える近道を作る仕組みで、いずれもバッチ正規化の「分布をそろえる」計算とは別物。", "why_asked": "バッチ正規化を「学習を安定させる仕組み」という結果だけで覚え、具体的に何をそろえているのか(ミニバッチ単位で平均と分散をそろえる)を説明できない受験者が多い。仕組みの中身を問う。", "usecase": "深いネットワークの学習が不安定だったり収束が遅かったりする場面で、バッチ正規化を導入する理由(各層の入力分布を安定させ、学習率を上げても崩れにくくする)を説明できるようになる。", "opt": ["正解。ミニバッチ単位で各層の入力の平均と分散をそろえ、値の分布が大きく偏らないようにする。", "ドロップアウトの説明。ノードをランダムに無効化する仕組みで、分布をそろえる仕組みとは別物。", "データ拡張の説明。訓練データを水増しする工夫であり、分布をそろえる処理とは別物。", "スキップ結合(残差接続)の説明。層を飛び越えて足し込む仕組みで、バッチ正規化の分布調整とは別物。"]}'),
  ('g-kentei-f-q41', '6. ディープラーニングの応用例',
   '物体検出（Object Detection）の方式のうち、YOLOやSSDのように、位置の候補出しと種類の判定を1回のネットワーク処理でまとめて行う方式を何と呼ぶか。',
   NULL::text,
   '["一段階検出（One-Stage Detection）", "二段階検出（Two-Stage Detection）", "セマンティックセグメンテーション", "アンサンブル学習"]',
   0, '[0]', 'single',
   '{"asked": "YOLOやSSDのように、候補出しと判定を1回の処理でまとめて行う検出方式の名前を問うている。", "point": "候補探しと判定を1回のネットワークで済ませるなら一段階（YOLO/SSD）。候補探しと判定を2回に分けるなら二段階（R-CNN系）。", "kid": "物体検出とは、画像の中にある物の場所（枠）と種類を当てるタスク。二段階方式は「まずここに何かありそうという場所の候補をたくさん出す」作業と「その候補が実際に何なのか判定する」作業を、順番に2回に分けて行う。一段階方式はこの2つの作業を1回のネットワーク処理でまとめてやってしまう。", "eg": "一段階は「写真をひと目見て『あそこに猫、ここに車』と即座に言い切る人」。二段階は「まず怪しい場所に付箋を貼ってから、1つずつ付箋を確認して『これは猫』と判定していく人」。", "terms": [["YOLO（You Only Look Once）", "直訳は「一度だけ見る」。画像を1回だけネットワークに通し、位置と種類を同時に出す一段階方式の代表"], ["SSD（Single Shot MultiBox Detector）", "直訳は「一発・複数枠・検出器」。YOLOと同じく1回の処理で検出する一段階方式"], ["R-CNN（Region-based CNN）", "直訳は「領域ベースの畳み込みニューラルネットワーク」。まず候補領域を出し、その後で種類を判定する二段階方式の元祖"]], "think": "なぜ一段階の方が速いのかがカギ。二段階方式は「候補となる場所を出す専用の処理」を先に走らせ、その後で「候補ごとに種類を判定する処理」を別に走らせる。処理が2回に分かれる分、精度を上げやすい一方で計算の手間が増え、動画のようにコマ数が多い場面ではリアルタイムに追いつきにくい。一段階方式は候補出しと判定を1つのネットワークで同時に済ませるので、通す回数が1回で済み、その分速い。ただし2段階に分けてじっくり絞り込む二段階方式に比べると、細かい精度では譲ることがある。だから「速さ優先の一段階」「精度優先の二段階」という使い分けが生まれる。", "vs": "二段階方式（R-CNN、Fast R-CNN、Faster R-CNNなど）は候補領域を出す処理と判定する処理が分かれている点で一段階方式と混同しやすい。名前だけで「YOLOは物体検出全般を指す言葉」と覚えると、二段階方式と並べたときに区別できなくなる。", "why_asked": "「物体検出＝YOLO」のように方式を1つに絞って覚えていると、二段階方式の名前（R-CNN系）が出た瞬間に判断が止まる。試験ではYOLO/SSDとR-CNN系を対比させ、どちらの系統かを問う形で出やすい。", "usecase": "リアルタイム性が要る自動運転のカメラ認識や監視カメラでは速さを優先して一段階方式が好まれ、医療画像診断のように精度を優先する場面では二段階方式が選ばれることがある。", "opt": ["正解。YOLOやSSDは候補の位置出しと種類の判定を1つのネットワークで同時に行う一段階方式の代表。", "二段階検出（Two-Stage Detection）。まず候補領域を出し、その後で種類を判定する処理を別に行う方式で、R-CNN系が代表。", "セマンティックセグメンテーション。画像の画素ごとにクラスを割り当てるタスクで、枠を出す物体検出とは出力の形が異なる。", "アンサンブル学習。複数のモデルの予測を組み合わせて精度を上げる手法で、物体検出の方式区分とは別の話。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">物体検出の一段階と二段階</text>\n\n<text x=\"10\" y=\"34\" font-size=\"9\" fill=\"#60a5fa\">一段階（YOLO / SSD）</text>\n<rect x=\"8\" y=\"40\" width=\"46\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"31\" y=\"55\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">画像</text>\n<text x=\"60\" y=\"55\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">→</text>\n<rect x=\"70\" y=\"40\" width=\"120\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"130\" y=\"55\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">ネットワーク1回</text>\n<text x=\"198\" y=\"55\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">→</text>\n<rect x=\"206\" y=\"40\" width=\"126\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<text x=\"269\" y=\"55\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">位置＋種類 同時に出す</text>\n\n<text x=\"10\" y=\"86\" font-size=\"9\" fill=\"#c9a04a\">二段階（R-CNN系）</text>\n<rect x=\"8\" y=\"92\" width=\"42\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"29\" y=\"107\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">画像</text>\n<text x=\"56\" y=\"107\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">→</text>\n<rect x=\"64\" y=\"92\" width=\"80\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#c9a04a\"/>\n<text x=\"104\" y=\"107\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">候補出し</text>\n<text x=\"150\" y=\"107\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">→</text>\n<rect x=\"158\" y=\"92\" width=\"80\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#c9a04a\"/>\n<text x=\"198\" y=\"107\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">種類判定</text>\n<text x=\"244\" y=\"107\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">→</text>\n<rect x=\"252\" y=\"92\" width=\"80\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<text x=\"292\" y=\"107\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">検出結果</text>\n\n<text x=\"170\" y=\"140\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">同じ検出でも、処理を1回で済ますか2回に分けるかが違う</text>\n</svg>"}'),
  ('g-kentei-f-q42', '6. ディープラーニングの応用例',
   '転移学習でファインチューニングを行うとき、入力に近い浅い層の重みを凍結（固定）し、出力に近い深い層だけを新しいタスクのデータで再学習することが多い。この工夫の狙いとして最も適切なものはどれか。',
   NULL::text,
   '["浅い層が学ぶ線や角のような汎用的な特徴を使い回し、深い層だけを課題向けに調整するため", "深い層の重みをすべて削り取り、モデル全体のパラメータ数そのものを減らして軽くするため", "浅い層と深い層の並びを入れ替え、出力に近い層から先に学習を始めさせる順番にするため", "浅い層の重みをいったんランダムな値に初期化し直し、そこから改めて学習させて過学習を防ぐため"]',
   0, '[0]', 'single',
   '{"asked": "浅い層を凍結し深い層だけ再学習するファインチューニングの工夫が、何のためにあるのかを問うている。", "point": "浅い層＝線や角などどのタスクにも使える特徴なら凍結して使い回し、深い層＝タスク固有の判断なら再学習する。", "kid": "ニューラルネットワークの浅い層（入力に近い層）は「線がある」「角がある」といった、どんな画像にも共通する基本的な特徴を捉える。深い層（出力に近い層）は、その基本的な特徴を組み合わせて「これは猫」「これは犬」のような、その課題に特有の判断をする。転移学習では、大量のデータで既に学習済みのモデルを持ってきて、別の新しい課題に使い回す。ファインチューニングはその重みを新しいデータに合わせて微調整する作業。浅い層はどの課題でも同じような特徴を見ているので固定（凍結）してそのまま使い、深い層だけを新しい課題向けに再学習することが多い。", "eg": "料理人が「野菜の切り方」という基本技術（浅い層）は使い回して、店ごとに違う「味付けの最終仕上げ」（深い層）だけ習い直すようなもの。基本から全部学び直すより早く一人前になれる。", "terms": [["転移学習（Transfer Learning）", "直訳は「移し替える学習」。大量データで学習済みのモデルの知識を、別の新しい課題に活かす総称"], ["ファインチューニング（Fine-tuning）", "直訳は「微調整」。転移学習の具体的なやり方の一つで、学習済みの重みを新しいデータに合わせて少しだけ更新すること"], ["凍結（Freeze）", "層の重みを学習中に更新しないよう固定すること"]], "think": "なぜ浅い層を凍結すると効くのかがカギ。ゼロから学習し直すと、大量のデータと計算時間が必要になり、手元の新しいデータが少ないと十分に学習しきれず精度が落ちてしまう。浅い層が捉える線や角のような特徴は、猫でも車でも道路標識でも共通して使われる汎用的なパーツなので、別の課題でもそのまま使い回して問題ない。そこを固定して更新の対象から外せば、少ないデータと計算量でも、課題に固有の判断をする深い層だけを効率よく調整できる。だから浅い層凍結・深い層再学習という工夫が効く。", "vs": "転移学習（既存の知識を別課題に活かすという総称）とファインチューニング（その重みを実際に更新する具体的なやり方）を同じ意味で混同しやすい。層を凍結せず全層を再学習するやり方もファインチューニングの一種であり、「層を凍結すること」自体がファインチューニングの定義ではない点にも注意。", "why_asked": "転移学習とファインチューニングの言葉の階層関係（総称と具体手法）を問う出題が多い中で、実際にどの層をどう扱うかという実務的な工夫まで踏み込んで問われると、定義を丸暗記しているだけの人は答えに詰まる。", "usecase": "画像認識モデルを自社の少量の商品画像だけで一から学習するのは非現実的だが、大規模データで学習済みの公開モデルの深い層だけを自社データで再学習すれば、少ないデータと計算資源でも実用的な精度が出せる。", "opt": ["正解。浅い層が学ぶ線や角のような汎用的な特徴を使い回し、深い層だけを課題向けに調整するために凍結する。", "深い層の重みをすべて削り取るのは枝刈り（Pruning）など軽量化の目的であり、浅い層を凍結するファインチューニングの狙いとは別。", "層の並びを入れ替える操作ではない。凍結と再学習は層の順番はそのままに、更新するかしないかだけを層ごとに分ける工夫。", "凍結は「初期化し直す」のではなく「学習済みの値のまま固定する」こと。ランダムに初期化し直したら学習済みの知識が失われてしまう。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 140\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">ファインチューニングでの層の扱い</text>\n\n<rect x=\"10\" y=\"40\" width=\"50\" height=\"34\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"35\" y=\"61\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">層1</text>\n<rect x=\"68\" y=\"40\" width=\"50\" height=\"34\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"93\" y=\"61\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">層2</text>\n<rect x=\"126\" y=\"40\" width=\"50\" height=\"34\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"151\" y=\"61\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">層3</text>\n<rect x=\"184\" y=\"40\" width=\"50\" height=\"34\" rx=\"3\" fill=\"none\" stroke=\"#c9a04a\"/>\n<text x=\"209\" y=\"61\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">層4</text>\n<rect x=\"242\" y=\"40\" width=\"50\" height=\"34\" rx=\"3\" fill=\"none\" stroke=\"#c9a04a\"/>\n<text x=\"267\" y=\"61\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">層5</text>\n\n<line x1=\"60\" y1=\"57\" x2=\"68\" y2=\"57\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<line x1=\"118\" y1=\"57\" x2=\"126\" y2=\"57\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<line x1=\"176\" y1=\"57\" x2=\"184\" y2=\"57\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n<line x1=\"234\" y1=\"57\" x2=\"242\" y2=\"57\" stroke=\"#8892a4\" stroke-width=\"1\"/>\n\n<text x=\"93\" y=\"94\" text-anchor=\"middle\" font-size=\"9\" fill=\"#60a5fa\">凍結（そのまま使う）</text>\n<text x=\"93\" y=\"106\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">浅い層＝線や角などの汎用的な特徴</text>\n\n<text x=\"267\" y=\"94\" text-anchor=\"middle\" font-size=\"9\" fill=\"#c9a04a\">再学習する</text>\n<text x=\"267\" y=\"106\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">深い層＝この課題固有の判断</text>\n\n<text x=\"8\" y=\"24\" font-size=\"8\" fill=\"#8892a4\">入力に近い</text>\n<text x=\"292\" y=\"24\" text-anchor=\"end\" font-size=\"8\" fill=\"#8892a4\">出力に近い</text>\n</svg>"}'),
  ('g-kentei-f-q43', '6. ディープラーニングの応用例',
   'BERTとGPTはどちらもTransformerをもとにした言語モデルだが、得意なタスクの傾向に違いがある。その説明として最も適切なものはどれか。',
   NULL::text,
   '["前後の文脈を両方見て理解するBERTは穴埋めや意味理解に向き、前から次の語を予測するGPTは文章生成に向く", "BERTは文章を生成する処理に特化しており、GPTは文中の穴埋め問題を理解する処理に特化している", "BERTもGPTも文の前後両方を見る同じ双方向の処理を採用しているため、得意なタスクに違いは生じないと考えられる", "BERTもGPTも次の語を予測する生成方式のみを採用しており、文脈理解のタスクは一切扱えない設計になっている"]',
   0, '[0]', 'single',
   '{"asked": "BERTとGPTの構造の違いが、それぞれどんなタスクに向いているかという得意分野の違いにどうつながるかを問うている。", "point": "前後両方見て理解するBERTは穴埋め・分類向き。前だけ見て予測するGPTは文章生成向き。", "kid": "Transformerというネットワークの仕組みをもとにした言語モデルには色々な種類があるが、BERTとGPTは代表的な2つ。BERTは文章の前後両方を同時に見て、それぞれの単語の意味を理解する。だから「この文の穴あき部分に入る言葉は何か」のような、文全体の意味をつかむ作業が得意。GPTは文章を前から順番に読んで、次にどんな言葉が来るかを予測しながら文章を作っていく。だから続きの文章を書く、質問に答える文章を作る、といった文章を生成する作業が得意。", "eg": "BERTは「虫食いの手紙を、前後の文脈から欠けた言葉を推理する探偵」。GPTは「書き出しの一文だけをもらって、その続きを考えて書き足す小説家」。", "terms": [["BERT（Bidirectional Encoder Representations from Transformers）", "直訳は「Transformerによる双方向のエンコーダ表現」。文の前後両方を見て意味を理解する言語モデル"], ["GPT（Generative Pre-trained Transformer）", "直訳は「生成的な事前学習済みTransformer」。前から順に次の語を予測しながら文章を生成する言語モデル"], ["Transformer", "文中の単語同士の関係の強さ（Attention）を使って文脈を捉えるニューラルネットワークの仕組み"]], "think": "なぜ見る方向の違いがそのまま得意タスクの違いになるのかがカギ。BERTは学習のときにわざと文中の単語を隠して、その前後にある単語をヒントに隠れた単語を当てる練習をする。前後両方の情報を使えるので、文全体の意味を正確に理解する力が育つ。一方GPTは学習のときに「ここまでの単語列から次の単語を当てる」練習だけを繰り返す。まだ出ていない後ろの単語は見えない設計なので、文章を最後まで作り切る力が育つ。だから理解が主な仕事（穴埋め・分類・意味の把握）にはBERT、生成が主な仕事（文章の続きを作る・対話に応答する）にはGPTが向く。", "vs": "「どちらもTransformerだから性能に優劣がある」と捉えるのは誤り。優劣ではなく、前後両方を見るか（BERT＝理解向き）、前だけ見て予測するか（GPT＝生成向き）という設計の違いによる得意分野の差。", "why_asked": "BERTとGPTの「双方向か一方向か」という構造の違いは覚えていても、それが「では実務でどちらを使うべきか」というタスク適性の判断に結びつかない人が多い。試験では構造の違いをタスクの向き不向きに変換させる形で問われる。", "usecase": "文章の感情分析やカテゴリ分類のように「文を理解して判定する」業務にはBERT系のモデルが、チャットボットの応答文生成や文章要約のように「文章を新しく作り出す」業務にはGPT系のモデルが選ばれることが多い。", "opt": ["正解。前後の文脈を両方見て理解するBERTは穴埋めや意味理解に向き、前から次の語を予測するGPTは文章生成に向く。", "BERTとGPTの得意分野の説明が逆になっている。BERTは前後両方を見て理解する双方向モデル、GPTは前から予測して生成するモデル。", "BERTもGPTも同じ双方向処理と説明しているが、GPTは前から順に次の語を予測する一方向の処理であり、この説明は誤り。", "BERTもGPTも生成方式のみと説明しているが、BERTは穴埋めのような文脈理解に強く、生成だけに限られるわけではない。"]}'),
  ('g-kentei-f-q44', '6. ディープラーニングの応用例',
   'GAN（敵対的生成ネットワーク）とVAE（変分オートエンコーダ）は、どちらもデータを新しく作り出す生成モデルだが、学習のさせ方に違いがある。その説明として最も適切なものはどれか。',
   NULL::text,
   '["GANは生成器と識別器を競わせて本物らしさを高め、VAEは確率分布に圧縮してから復元する誤差を小さくするよう学習する", "GANはデータを確率分布に圧縮して復元するように学習するのに対し、VAEは生成器と識別器を競わせて本物らしさを高めていく", "GANもVAEも同じように識別器と生成器の両方を用意して競わせることで、本物らしいデータを作れるように学習していく", "GANもVAEも教師あり学習の一種であり、あらかじめ正解ラベルが付けられたデータが用意されていないと学習を進められない"]',
   0, '[0]', 'single',
   '{"asked": "GANとVAEという2つの生成モデルが、それぞれどういう仕組みで学習するかの違いを問うている。", "point": "生成器と識別器を競わせて本物らしさを競うのがGAN。確率分布に圧縮して復元誤差を小さくするのがVAE。", "kid": "生成モデルとは、本物そっくりの新しいデータ（画像など）を作り出すAIのこと。GANは「偽物を作る係（生成器）」と「本物か偽物か見破る係（識別器）」の2つのネットワークを用意し、生成器は識別器を騙せるように、識別器は騙されないように、互いに競争しながら鍛え合う。この競争を繰り返すうちに、生成器はどんどん本物そっくりのデータを作れるようになる。VAEは、データをいったん小さな数字の並び（潜在変数と呼ばれる、データの特徴をぎゅっと圧縮した表現）に圧縮し、そこから元のデータをできるだけ忠実に復元する練習をする。復元がうまくいくように圧縮の仕方を学ぶことで、その圧縮された表現から新しいデータも作れるようになる。", "eg": "GANは「偽札を作る偽造者と、それを見破ろうとする鑑定士がお互いに腕を磨き合う」関係。VAEは「絵の特徴を短いメモに書き留めて、そのメモだけを見て絵を描き直す練習を繰り返す画家」。メモが上手にとれるようになるほど、メモから新しい絵も描けるようになる。", "terms": [["GAN（Generative Adversarial Network）", "直訳は「敵対的生成ネットワーク」。生成器と識別器を競わせて学習する生成モデル"], ["VAE（Variational Autoencoder）", "直訳は「変分オートエンコーダ」。データを確率分布に圧縮してから復元する誤差を小さくして学習する生成モデル"], ["識別器（Discriminator）", "GANで、渡されたデータが本物か生成器が作った偽物かを見分ける役目のネットワーク"], ["潜在変数（Latent Variable）", "データの特徴をぎゅっと圧縮した、少ない数字の並びで表した表現"]], "think": "なぜ2つの仕組みが同じ「生成」でもやり方がこんなに違うのかがカギ。GANは「本物らしさ」を直接定義するのが難しいという問題を、識別器という採点係を用意して解決する。生成器は識別器を騙せなければ改善の合図（勾配）を受け取り、少しずつ本物に近づく。識別器も見破れなければ改善の合図を受け取り、少しずつ目が肥える。この綱引きが釣り合うところまで来ると、生成器は本物と見分けがつかないデータを作れるようになる。VAEは逆に「圧縮して復元する」という素直な目標を立てる。復元がうまくいくように圧縮のやり方（潜在変数の作り方）を学べば、その圧縮のルールを逆に使って、ランダムな数字の並びからでも「それらしいデータ」を新しく作り出せる。だからGANは競争によって、VAEは圧縮と復元の練習によって、それぞれ生成する力を身につける。", "vs": "拡散モデル（Diffusion Model、ノイズを段階的に取り除いて生成する方式）と混同しないよう注意。GAN＝競争、VAE＝圧縮と復元、拡散モデル＝ノイズ除去、と学習のさせ方で3方式を区別する。", "why_asked": "「GAN・VAE・拡散モデルはどれも生成AIの一種」とひとまとめに覚えていると、それぞれの学習のさせ方の違いを問われたときに区別できない。試験ではこの3方式のどれについて説明しているかを言い換えて問う形が多い。", "usecase": "GANは顔写真の生成やスタイル変換のように、見た目の質感が重要な画像生成でよく使われる。VAEはデータの特徴を圧縮した表現（潜在変数）自体を異常検知や特徴抽出に活用する場面でも使われる。", "opt": ["正解。GANは生成器と識別器を競わせて本物らしさを高め、VAEは確率分布に圧縮してから復元する誤差を小さくするよう学習する。", "GANとVAEの説明が逆になっている。GANが生成器と識別器を競わせ、VAEが圧縮と復元による学習を行う。", "GANもVAEも同じ競争による学習と説明しているが、VAEには識別器による競争の仕組みはなく、圧縮と復元の誤差を小さくする学習を行う。", "GANもVAEも教師あり学習で正解ラベルが必須と説明しているが、どちらも正解ラベル付きデータを必須とはしない生成モデル。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">GANとVAEの学習のさせ方</text>\n\n<text x=\"8\" y=\"32\" font-size=\"9\" fill=\"#60a5fa\">GAN（競わせる）</text>\n<rect x=\"8\" y=\"38\" width=\"70\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/>\n<text x=\"43\" y=\"53\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">生成器</text>\n<text x=\"86\" y=\"53\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n<rect x=\"94\" y=\"38\" width=\"66\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"127\" y=\"53\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">偽データ</text>\n<text x=\"168\" y=\"53\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n<rect x=\"176\" y=\"38\" width=\"70\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#c47070\"/>\n<text x=\"211\" y=\"53\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">識別器</text>\n<path d=\"M 211 62 Q 130 84 43 62\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n<text x=\"127\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#c47070\">見破られたら合図を返す＝競争</text>\n\n<text x=\"8\" y=\"98\" font-size=\"9\" fill=\"#c9a04a\">VAE（圧縮して復元）</text>\n<rect x=\"8\" y=\"104\" width=\"66\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"41\" y=\"119\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">データ</text>\n<text x=\"82\" y=\"119\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n<rect x=\"90\" y=\"104\" width=\"86\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#c9a04a\"/>\n<text x=\"133\" y=\"119\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">圧縮(潜在変数)</text>\n<text x=\"184\" y=\"119\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">→</text>\n<rect x=\"192\" y=\"104\" width=\"80\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\"/>\n<text x=\"232\" y=\"119\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">復元データ</text>\n<text x=\"278\" y=\"146\" text-anchor=\"end\" font-size=\"8\" fill=\"#8892a4\"></text>\n<text x=\"133\" y=\"144\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">復元がうまくいくよう圧縮の仕方を学ぶ</text>\n</svg>"}'),
  ('g-kentei-f-q45', '6. ディープラーニングの応用例',
   '強化学習において、状態と行動の組み合わせごとの価値（Q値）を、テーブルで管理する代わりにニューラルネットワークで近似することで、状態の種類が膨大な問題にも対応できるようにした手法はどれか。',
   NULL::text,
   '["DQN（Q値をネットワークで近似する強化学習手法）", "k-means（データをグループに分けるクラスタリング）", "オートエンコーダ（データを圧縮してから復元する仕組み）", "ランダムフォレスト（決定木を複数束ねて予測する手法）"]',
   0, '[0]', 'single',
   '{"asked": "Q値をテーブルではなくニューラルネットワークで近似する強化学習の手法の名前を問うている。", "point": "Q値をテーブルではなくニューラルネットワークで近似する強化学習の手法ならDQN。", "kid": "強化学習は、AIが行動した結果もらえる「報酬」を手がかりに、試行錯誤しながら良い行動を学ぶ仕組み。Q値とは「ある状況（状態）で、ある行動をとったとき、この先どれくらい良い結果が期待できるか」を数字で表したもの。昔ながらのQ学習は、この数字を「状態と行動の組み合わせごとに1つずつ」の表（テーブル）に書き込んで管理していた。しかし、画像のようにありうる状態の数が天文学的に多い問題では、表がとても収まりきらない。DQNは、この表の代わりにニューラルネットワークを使って「この状態でこの行動をとったらQ値はだいたいこれくらい」と近似的に計算させることで、状態の種類が膨大でも扱えるようにした手法。", "eg": "昔のQ学習は「あらゆる場面と行動の組み合わせを1冊の分厚い辞書に書き出しておく」やり方。DQNは「辞書を丸暗記する代わりに、似た場面ならだいたいこれくらいの価値と推測できる勘の良い判定係（ニューラルネットワーク）を育てる」やり方。", "terms": [["DQN（Deep Q-Network）", "直訳は「深いQネットワーク」。Q値をニューラルネットワークで近似する強化学習の手法"], ["Q値", "ある状態である行動をとったときに、この先期待できる報酬の大きさを表す数字"], ["深層強化学習", "強化学習にディープラーニングを組み合わせた手法の総称。DQNやAlphaGoが代表例"]], "think": "なぜテーブルからニューラルネットワークに置き換えると効くのかがカギ。テーブルで管理する方式は、状態と行動の組み合わせが少ないうちは正確に書き出せるが、状態の数が爆発的に増えると表が大きくなりすぎて記録も検索も現実的でなくなる。加えて、表には「一度も経験していない状態」のQ値は書き込みようがなく、初めて見る場面にまったく対応できない。ニューラルネットワークで近似すれば、似た状態の間でQ値の傾向を一般化できるので、表に載っていない初めての状態でもそれらしいQ値を推測できる。だから状態の種類が膨大な問題（画像を状態として扱うゲームなど）でも、DQNなら現実的な計算量で強化学習が回せる。", "vs": "AlphaGoと同じ「深層強化学習」の枠組みだが、AlphaGoは囲碁という特定の課題向けに、木を先読みする探索（モンテカルロ木探索）とニューラルネットワークを組み合わせた専用の仕組みを持つ点でDQNとは構成が異なる。両方とも「ニューラルネットワークを使う」という共通点だけで同一視しないよう注意。", "why_asked": "「強化学習＝試行錯誤で学ぶ」という定義だけ覚えていると、DQNが具体的に何を置き換えて何を解決した手法なのかという一段深い問いに答えられない。試験では強化学習の基礎から一歩踏み込んだ具体手法の理解を問う形で出やすい。", "usecase": "ゲームのプレイ画面のような、ありうる状態の数が膨大で表にまとめきれない問題で、DQNは実際にAtariのゲームを人間並みかそれ以上のスコアでプレイする成果を上げ、深層強化学習の広がりのきっかけになった。", "opt": ["正解。DQNはQ値をテーブルではなくニューラルネットワークで近似することで、状態の種類が膨大な問題にも対応できるようにした強化学習の手法。", "k-means。データをいくつかのグループに分けるクラスタリングの手法で、報酬をもとに行動を学ぶ強化学習とは別の枠組み。", "オートエンコーダ。データを圧縮してから復元する練習をする仕組みで、Q値の近似とは目的が異なる。", "ランダムフォレスト。複数の決定木の予測を束ねて精度を上げる手法で、強化学習のQ値近似とは別の分野の手法。"]}'),
  ('g-kentei-f-q46', '6. ディープラーニングの応用例',
   '画像認識モデルが、入力された画像のどの部分に注目してその判断（たとえば「これは猫」）を下したのかを、ヒートマップとして可視化する手法はどれか。',
   NULL::text,
   '["Grad-CAM（判断に効いた場所をヒートマップで示す手法）", "データ拡張（学習データを回転や反転で水増しする手法）", "バッチ正規化（層の入力を整えて学習を安定させる手法）", "蒸留（大きなモデルの判断を小さなモデルにまねさせて軽くする手法）"]',
   0, '[0]', 'single',
   '{"asked": "画像認識モデルの判断根拠を、画像上のヒートマップとして可視化する手法の名前を問うている。", "point": "画像のどこに注目して判断したかをヒートマップで見せるならGrad-CAM。", "kid": "ディープラーニングのモデルは高い精度で判断を下せるが、その内部の計算はとても複雑で、「なぜその判断に至ったのか」が人には分かりにくい。これを「ブラックボックス」と呼ぶ。Grad-CAMは、画像認識モデルが「これは猫」と判断したときに、画像のどの部分（耳のあたり、顔の輪郭など）を重視して判断したのかを、色の濃淡で塗り分けたヒートマップとして表示する手法。濃い色の部分ほど、その判断に強く影響したことを示す。", "eg": "先生が答案を採点するとき、どこに丸や線を引いたかを見れば、先生がどこを根拠に採点したか分かる。Grad-CAMは、AIの判断根拠に同じように「ここを見て判断したよ」という印を画像の上に付けてくれる。", "terms": [["Grad-CAM（Gradient-weighted Class Activation Mapping）", "直訳は「勾配で重み付けしたクラス活性化マッピング」。判断に効いた画像の場所をヒートマップで示す解釈手法"], ["ブラックボックス", "内部の計算が複雑すぎて、人が判断の理由を追いにくいモデルの状態を指す言葉"], ["勾配", "どれだけその判断に効いたかを表す、出口から入口へ伝わる合図"]], "think": "なぜ勾配を使うと注目箇所が分かるのかがカギ。Grad-CAMは、「これは猫」という判断結果に対して、画像の各場所の情報がどれくらい強くその結果を後押ししたかを、勾配（その場所の値を少し変えたら判断がどれだけ変わるか、という合図）を使って測る。この合図が大きい場所ほど「その判断にとって重要な場所」だと言える。この重要度を画像の位置ごとに色で塗り分ければ、モデルが画像のどこを見て判断したのかが人の目で分かる形になる。だから、モデルの中身を直接読み解かなくても、勾配という手がかりから「どこを見たか」を逆算して可視化できる。", "vs": "LIME/SHAPは個々の予測に対して「どの入力項目（特徴量）が効いたか」を近似的なモデルで説明する手法で、画像に限らず表形式のデータなどにも使える。Grad-CAMは画像認識モデルに特化し、勾配を直接使って「画像のどこを見たか」を可視化する点で仕組みが異なる。", "why_asked": "モデルの解釈性（なぜその判断をしたか説明する技術）は、精度の話とは別軸の出題として増えている。LIME/SHAP/Grad-CAMをまとめて「説明可能AIの手法」とだけ覚えていると、どれが画像特化でどれが汎用かを問われたときに答えられない。", "usecase": "医療画像診断でAIが「腫瘍がある」と判断したとき、Grad-CAMで画像のどこを根拠にしたかを医師が確認できれば、AIの判断を鵜呑みにせず妥当性を検証できる。", "opt": ["正解。Grad-CAMは画像認識モデルが判断のとき画像のどこに注目したかを、色の濃淡のヒートマップとして可視化する手法。", "データ拡張（Data Augmentation）。学習データを回転・反転などで水増しする工夫で、判断根拠の可視化とは別の目的。", "バッチ正規化（Batch Normalization）。層の入力を整えて学習を安定させる工夫で、判断根拠の可視化とは別の目的。", "蒸留（知識蒸留）。大きなモデルの判断を小さなモデルにまねさせて軽くする手法で、判断根拠の可視化とは別の目的。"], "viz": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 150\" font-family=\"sans-serif\">\n<defs>\n<radialGradient id=\"heat\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n<stop offset=\"0%\" stop-color=\"#c47070\" stop-opacity=\"0.9\"/>\n<stop offset=\"60%\" stop-color=\"#c9a04a\" stop-opacity=\"0.45\"/>\n<stop offset=\"100%\" stop-color=\"#c9a04a\" stop-opacity=\"0\"/>\n</radialGradient>\n</defs>\n<text x=\"170\" y=\"14\" text-anchor=\"middle\" font-size=\"11\" fill=\"#e8eaf0\">Grad-CAM：判断に効いた場所を可視化</text>\n\n<rect x=\"30\" y=\"26\" width=\"140\" height=\"100\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"100\" y=\"120\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">入力画像</text>\n<ellipse cx=\"100\" cy=\"60\" rx=\"55\" ry=\"12\" fill=\"url(#heat)\"/>\n<text x=\"100\" y=\"64\" text-anchor=\"middle\" font-size=\"8\" fill=\"#e8eaf0\">耳・顔のあたり</text>\n\n<rect x=\"200\" y=\"26\" width=\"120\" height=\"100\" rx=\"3\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"260\" y=\"40\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">判断「猫」</text>\n<text x=\"260\" y=\"60\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">濃い色ほど</text>\n<text x=\"260\" y=\"72\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">判断への影響が大きい</text>\n<rect x=\"230\" y=\"90\" width=\"60\" height=\"8\" fill=\"#c47070\"/>\n<rect x=\"230\" y=\"90\" width=\"30\" height=\"8\" fill=\"#c9a04a\" opacity=\"0.5\"/>\n<text x=\"230\" y=\"108\" font-size=\"7\" fill=\"#8892a4\">低</text>\n<text x=\"290\" y=\"108\" text-anchor=\"end\" font-size=\"7\" fill=\"#8892a4\">高（注目度）</text>\n\n<text x=\"170\" y=\"142\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">勾配を使って、画像のどこが判断を後押ししたかを塗り分ける</text>\n</svg>"}'),
  ('g-kentei-f-q47', '6. ディープラーニングの応用例',
   '個々の予測結果に対して、「その予測にどの入力項目（特徴量）がどれくらい影響したか」を、予測対象の近くだけで成り立つ単純なモデルで近似することで説明する手法はどれか。',
   NULL::text,
   '["LIME（個々の予測を単純なモデルで近似して説明する手法）", "Grad-CAM（画像の注目箇所をヒートマップで示す手法）", "ドロップアウト（学習中に一部を無効化する正則化手法）", "バッチ正規化（層の入力を整えて学習を安定させる手法）"]',
   0, '[0]', 'single',
   '{"asked": "個々の予測を、その近くだけで成り立つ単純なモデルで近似して説明する解釈手法の名前を問うている。", "point": "個々の予測を、その近くだけで成り立つ単純なモデルで近似して説明するならLIME。", "kid": "複雑なモデルの判断の理由を丸ごと理解するのは難しいが、「今回のこの1件の予測」だけに絞れば、その周辺だけを単純なモデル（直線のような分かりやすい式）で近似的に真似させることができる。LIME（ライム）は、説明したい1件の予測の近くにたくさんの似たデータを作り、複雑なモデルがそれらに対して出す予測結果を観察して、「この範囲でならこの単純なモデルでだいたい同じ判断になる」という近似モデルを作る。その単純なモデルを見れば、どの入力項目がどれくらい予測を後押ししたかが人に分かる形で示せる。", "eg": "複雑な会社全体の意思決定の仕組みを丸ごと理解するのは難しいが、「今回のこの1件の決裁」だけに注目すれば、「今回は予算とスケジュールのこの2点が決め手だった」と簡単に説明できるようなもの。LIMEは複雑なモデル全体ではなく、1件の予測の周辺だけを簡単な言葉に翻訳する。", "terms": [["LIME（Local Interpretable Model-agnostic Explanations）", "直訳は「局所的で解釈可能な、モデルによらない説明」。個々の予測の近くだけを単純なモデルで近似して説明する手法"], ["SHAP（SHapley Additive exPlanations）", "直訳は「シャープレイ加算的説明」。各入力項目の貢献度を、ゲーム理論の考え方を使って公平に配分し説明する手法"], ["特徴量", "予測に使う入力項目のこと。たとえば家賃予測なら広さ・築年数・駅からの距離など"]], "think": "なぜ「近くだけ単純なモデルで近似する」というやり方で説明できるのかがカギ。複雑なモデル全体の計算式は人には追いきれないが、予測したい1件のデータのごく近くの範囲だけを見れば、複雑な曲線でも部分的にはほぼ直線のように振る舞う場面が多い。LIMEはこの性質を使い、説明したい1件の周辺に似たデータをたくさん作って複雑なモデルに予測させ、その結果に一番よく合う単純なモデル（直線的な式）を近くの範囲だけで作る。単純なモデルなら「この項目がこれだけ効いた」と人に読める形で示せるので、複雑なモデル本体を直接読み解かなくても、その1件に限れば妥当な説明が得られる。", "vs": "SHAPも同じく個々の予測の項目ごとの貢献度を出す手法だが、ゲーム理論の考え方（全員で分け合う利益をどう公平に配分するか）をもとに貢献度を計算する点でLIMEとは根拠となる理論が異なる。Grad-CAMは画像に特化した勾配ベースの手法で、LIME/SHAPのようなモデルの種類を選ばない汎用手法とは前提が異なる。", "why_asked": "「モデルの解釈性を高める手法」とひとまとめに覚えていると、Grad-CAM（画像特化・勾配ベース）とLIME/SHAP（汎用・近似モデルベース）の仕組みの違いを問われたときに区別できない。", "usecase": "融資審査AIが「この人は審査に通らない」と判断した理由を、LIMEやSHAPを使って「年収」「借入件数」のどの項目がどれだけ効いたかを示せれば、審査対象者への説明責任を果たしやすくなる。", "opt": ["正解。LIMEは個々の予測の近くだけで成り立つ単純なモデルで近似することで、どの入力項目が予測に効いたかを説明する手法。", "Grad-CAM。画像認識モデルに特化し、勾配を使って画像のどこに注目したかをヒートマップで示す手法で、近似モデルによる説明とは仕組みが異なる。", "ドロップアウト。学習中に一部のノードを無効化して過学習を防ぐ正則化の手法で、予測結果の説明とは別の目的。", "バッチ正規化。層の入力を整えて学習を安定させる手法で、予測結果の説明とは別の目的。"]}'),
  ('g-kentei-f-q48', '6. ディープラーニングの応用例',
   'モデルの軽量化手法である「蒸留」「枝刈り（Pruning）」「量子化（Quantization）」の説明の組み合わせとして最も適切なものはどれか。',
   NULL::text,
   '["蒸留は大きなモデルの判断を小さなモデルにまねさせ、枝刈りは影響の小さい重みを削り、量子化は重みの数値の精度（桁数）を落とす", "蒸留は重みの数値の精度（桁数）を落とし、枝刈りは大きなモデルの判断を小さなモデルにまねさせ、量子化は影響の小さい重みを削る", "蒸留・枝刈り・量子化はどれも、学習データを回転や反転などで水増しして増やす手法のことである", "蒸留・枝刈り・量子化はどれも学習済みモデルの重みを一切変更せず、ただ実行速度だけを測定して比較する手法である"]',
   0, '[0]', 'single',
   '{"asked": "蒸留・枝刈り・量子化という3つの軽量化手法が、それぞれ何をする手法かの正しい対応を問うている。", "point": "教える（蒸留）・削る（枝刈り）・精度を落とす（量子化）、軽量化の手段の違いで見分ける。", "kid": "ディープラーニングのモデルは高精度になるほど大きく重くなりがちで、スマホや組み込み機器で動かすには重すぎることがある。そこでモデルを小さく軽くする工夫がいくつかある。蒸留（知識蒸留）は、大きくて性能の良いモデル（先生）の判断のしかたを、小さなモデル（生徒）にまねさせて学習させ、性能をなるべく保ちながら軽くする方法。枝刈り（Pruning）は、モデルの中で判断にほとんど影響していない重み（効き具合のつまみ）を見つけて削り取り、ネットワークそのものを小さくする方法。量子化（Quantization）は、重みを表す数値の細かさ（桁数）を落とす、たとえば非常に細かい小数で持っていた重みを、もっと粗い数値で表すことで、モデルが占めるデータ量を減らす方法。", "eg": "蒸留は「ベテラン職人の技を、新人に短期集中で仕込む」。枝刈りは「使っていない部屋を家から取り除いて家をコンパクトにする」。量子化は「写真の色数を減らして、見た目はほぼそのままでファイルサイズを小さくする」。", "terms": [["蒸留（Knowledge Distillation）", "直訳は「知識の蒸留」。大きなモデル（先生）の判断を小さなモデル（生徒）にまねさせて軽くする手法"], ["枝刈り（Pruning）", "直訳は「刈り込み」。判断への影響が小さい重みを削ってネットワークを小さくする手法"], ["量子化（Quantization）", "直訳は「量子化・数値の段階分け」。重みの数値の精度（桁数）を落としてデータ量を減らす手法"]], "think": "なぜ3つとも「軽量化」でありながらやり方がこんなに違うのかがカギ。モデルが重くなる原因は主に「パラメータ（重み）の数が多いこと」と「その一つひとつを高い精度の数値で持っていること」の2つ。枝刈りは前者に切り込み、影響の小さい重みごと削ってパラメータの数自体を減らす。量子化は後者に切り込み、数値の精度を落として一つひとつのデータ量を減らす。蒸留はこの2つとは違うアプローチで、そもそも最初から小さいモデルを、大きなモデルの判断パターンを手本にして育てることで、少ないパラメータでも近い性能を出せるようにする。原因の場所が違うからこそ、3つの手法は組み合わせて使うこともできる。", "vs": "データ拡張（Data Augmentation、学習データを増やす工夫）と混同しないこと。軽量化はモデルの側を小さくする工夫で、データ拡張は学習データの側を増やす工夫であり、目的も操作対象もまったく別。", "why_asked": "「軽量化＝蒸留」とだけ覚えている人が多く、枝刈り・量子化という具体的な手段まで問われると答えに詰まりやすい。試験では3つの手法をシャッフルして説明を入れ替えた選択肢で正確な対応を問う形が定番。", "usecase": "スマホアプリに組み込む画像認識モデルや、工場のエッジ端末で動かす異常検知モデルでは、蒸留・枝刈り・量子化を組み合わせてモデルを軽くし、限られた計算資源でもリアルタイムに動かせるようにする。", "opt": ["正解。蒸留は大きなモデルの判断を小さなモデルにまねさせ、枝刈りは影響の小さい重みを削り、量子化は重みの数値の精度（桁数）を落とす。", "蒸留・枝刈り・量子化の説明が入れ替わっている。蒸留＝まねさせる、枝刈り＝重みを削る、量子化＝精度を落とす、が正しい対応。", "蒸留・枝刈り・量子化を学習データの水増しと説明しているが、これはデータ拡張の説明であり、いずれもモデル側を軽くする手法とは別。", "蒸留・枝刈り・量子化を重みを変更しない速度測定と説明しているが、3つとも実際にモデルの重みや構造を変更して軽くする手法。"]}'),
  ('g-kentei-f-q49', '6. ディープラーニングの応用例',
   '音声波形を、直前の少数のサンプルだけでなく、より広い範囲の過去の波形を効率よく参照しながら1サンプルずつ生成していく、拡張畳み込み（Dilated Convolution）を使った音声合成モデルはどれか。',
   NULL::text,
   '["WaveNet（拡張畳み込みで音声波形を生成するモデル）", "CTC（音声と文字列のズレを扱う音声認識の学習手法）", "word2vec（単語を意味の近さで表すベクトル化手法）", "BERT（文の前後を見て文脈を理解する言語モデル）"]',
   0, '[0]', 'single',
   '{"asked": "拡張畳み込みを使って音声波形を1サンプルずつ生成する音声合成モデルの名前を問うている。", "point": "音声波形を1サンプルずつ、拡張畳み込みで広い範囲の過去を見ながら生成するならWaveNet。", "kid": "音声合成（文字からそれらしい人の声を作り出すタスク）では、音の波形を非常に細かい時間刻み（1秒間に何万個ものサンプル）で生成する必要がある。WaveNetは、この波形を1つずつ順番に生成していくモデルで、拡張畳み込み（Dilated Convolution、畳み込み層で見る範囲を層が深くなるほど飛び飛びに広げていく工夫）を使うことで、直前の数個の波形だけでなく、もっと広い範囲の過去の波形を効率よく参照しながら、自然な音声を作り出す。", "eg": "普通の畳み込みが「すぐ隣の数マスだけを見るルーペ」だとすると、拡張畳み込みは「マス目を少しずつ飛ばしながら見る範囲を段階的に広げるルーペ」。層を重ねるごとに見える範囲が大きく広がり、ずっと前の音の流れも踏まえて次の一音を決められる。", "terms": [["WaveNet", "音声波形を1サンプルずつ、拡張畳み込みを使って生成する音声合成モデル"], ["拡張畳み込み（Dilated Convolution）", "直訳は「膨張させた畳み込み」。畳み込みで見る範囲を層ごとに飛び飛びに広げ、少ない層数でも広い範囲を参照できるようにする工夫"], ["CTC（Connectionist Temporal Classification）", "直訳は「コネクショニスト時系列分類」。音声認識で、音声と文字列の長さのズレを扱いながら学習させる手法"]], "think": "なぜ拡張畳み込みが音声合成に効くのかがカギ。自然な音声を作るには、直前の数サンプルだけでなく、もっと前の音の流れ（抑揚やリズム）まで踏まえて次の一音を決める必要がある。普通の畳み込みで広い範囲を見ようとすると、層をとても多く重ねなければならず計算が重くなる。拡張畳み込みは、層が深くなるごとに参照する間隔を飛び飛びに広げていくことで、少ない層数でも指数的に広い範囲の過去を参照できるようにする。だから計算量を抑えながら、自然でなめらかな音声波形を生成できる。", "vs": "CTC（音声認識で、話された音声と正解の文字列の長さのズレを扱いながら学習させる手法）と混同しないこと。WaveNetは音声を作り出す生成（音声合成）側の技術、CTCは音声を聞き取って文字にする認識側の学習手法であり、扱う方向が逆。", "why_asked": "音声処理は画像や自然言語処理に比べて出題頻度は低いが、「音声合成の代表モデルは何か」「その仕組みの核となる工夫は何か」という形で、生成側の技術を問う出題が見られる。CTCとまとめて音声処理の用語として丸暗記していると、生成と認識のどちらの技術かで取り違えやすい。", "usecase": "スマートスピーカーやカーナビの音声読み上げのように、自然で聞き取りやすい合成音声が求められる場面でWaveNet系の技術が使われている。", "opt": ["正解。WaveNetは拡張畳み込みを使い、広い範囲の過去の波形を参照しながら音声波形を1サンプルずつ生成する音声合成モデル。", "CTC（Connectionist Temporal Classification）。音声認識で、音声と文字列の長さのズレを扱いながら学習させる手法で、音声を作る生成側ではなく聞き取る認識側の技術。", "word2vec。単語を意味的な近さが距離に反映されたベクトルにする手法で、音声波形の生成とは対象が異なる。", "BERT。文の前後両方を見て文脈を理解する言語モデルで、音声波形の生成とは対象が異なる。"]}'),
  ('g-kentei-f-q50', '6. ディープラーニングの応用例',
   '画像とその説明文（テキスト）の大量のペアを学習し、画像とテキストを同じ「意味の空間」に埋め込むことで、画像とテキストをまたいだ類似度の比較やゼロショットの画像分類を可能にしたモデルはどれか。',
   NULL::text,
   '["CLIP（画像とテキストを同じ意味空間に埋め込むモデル）", "word2vec（単語を意味の近さで表すベクトル化手法）", "オートエンコーダ（データを圧縮してから復元する仕組み）", "GAN（生成器と識別器を競わせる生成モデル）"]',
   0, '[0]', 'single',
   '{"asked": "画像とテキストを同じ意味の空間に埋め込み、ゼロショットの画像分類を可能にしたマルチモーダルなモデルの名前を問うている。", "point": "画像とテキストを同じ意味の空間に埋め込んで類似度比較やゼロショット分類ができるならCLIP。", "kid": "マルチモーダルとは、画像・テキスト・音声のように種類の違う情報を一緒に扱えるAIのこと。CLIPは、インターネット上にある大量の「画像とその説明文」のペアを学習することで、画像とテキストのどちらも同じ「意味の座標（埋め込み空間）」の中の点として表現できるようにしたモデル。似た意味の画像とテキストは、この座標の中で近い位置に置かれる。この仕組みのおかげで、「この画像に一番近い意味の言葉はどれか」を計算するだけで、一度も学習していない新しいカテゴリの画像分類（ゼロショット、例を一つも見せずに新しいタスクをこなすやり方）までできるようになる。", "eg": "CLIPは、写真と、その写真を説明する短いキャプションを、同じ「意味の地図」の上に一緒に置いていく作業を大量に練習した結果、その地図さえあれば「この写真に一番近い言葉は何か」を地図上の距離だけで当てられるようになった案内人のようなもの。", "terms": [["CLIP（Contrastive Language-Image Pre-training）", "直訳は「対照的な言語-画像の事前学習」。画像とテキストを同じ意味の空間に埋め込むモデル"], ["マルチモーダル", "画像・テキスト・音声のように種類の違う情報を一緒に扱えるAIを指す言葉"], ["ゼロショット", "大規模なモデルに、例を一つも見せずに指示や説明文だけで新しいタスクをこなさせるやり方"], ["埋め込み（Embedding）", "データの意味を、数字の並び（ベクトル）として表現すること。似た意味のものは近い位置に置かれる"]], "think": "なぜ画像とテキストを同じ空間に埋め込むとゼロショット分類ができるのかがカギ。ふつうの画像分類モデルは「猫」「犬」といった決まったカテゴリの中でしか判定できず、新しいカテゴリを追加するには学習し直しが必要になる。CLIPは画像とテキストをあらかじめ同じ意味の空間に置く練習を大量にしているので、分類したいカテゴリの名前を文章として与えるだけで、その文章の埋め込みと画像の埋め込みがどれだけ近いかを計算すれば、そのカテゴリに当てはまるかどうかを判定できる。新しいカテゴリでも、専用の学習データを用意する代わりに、そのカテゴリを表す言葉を1つ用意するだけで済むので、一度も見たことのない分類にも対応できる。", "vs": "word2vec（単語だけを意味的な近さが反映されたベクトルにする手法）と混同しないこと。word2vecはテキストだけを対象にするが、CLIPは画像とテキストという種類の違う情報を同じ空間にまたがって埋め込む点が異なる。", "why_asked": "生成AI・基盤モデルの領域はシラバス2024で追加され出題が増えている分野で、マルチモーダルという言葉の定義だけでなく、その代表例であるCLIPが具体的にどんな仕組みでモダリティをまたぐ処理を実現しているかまで問われることがある。", "usecase": "画像検索で「夕焼けの海辺の犬」のような文章から近い画像を探し出す、あるいは新製品カテゴリの画像を一から学習し直さずに分類する、といった場面でCLIPのような画像とテキストをまたぐ埋め込みが活用されている。", "opt": ["正解。CLIPは画像とテキストの大量のペアを学習し、両方を同じ意味の空間に埋め込むことで、類似度比較やゼロショットの画像分類を可能にしたモデル。", "word2vec。単語を意味的な近さが反映されたベクトルにする手法で、テキストのみを対象とし、画像とはまたがらない。", "オートエンコーダ。データを圧縮してから復元する練習をする仕組みで、画像とテキストをまたぐ埋め込みを目的とした手法ではない。", "GAN。生成器と識別器を競わせて本物らしいデータを作る生成モデルで、画像とテキストの意味空間を揃える手法ではない。"]}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-f'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
